function VR_InvokeV3(Hash, ...) local x, y, z = Natives.InvokeV3(Hash, ...) return {x = x, y = y, z = z} end
function GetKeyName(index) local keyMap = { [19] = "ALT", [36] = "CTRL", [21] = "SHIFT", [137] = "CAPS", [192] = "TAB", [44] = "Q", [32] = "W", [38] = "E", [45] = "R", [245] = "T", [173] = "DOWN", [20] = "Z", [73] = "X", [26] = "C", [0] = "V", [29] = "B", [47] = "G", [18] = "MOUSE 1", [91] = "MOUSE 2", [174] = "LEFT", [172] = "UP", [175] = "RIGHT" } return keyMap[index] and keyMap[index] or "KEY [" .. tostring(index) .. "]" end
local function getPlayerPed() return GTA.PointerToHandle(GTA.GetLocalPed()) end
local function getAllPeds() local count = PoolMgr.GetMaxPedCount() - 1; local peds = {} for i = 0, count do local ped = PoolMgr.GetPed(i); if ped ~= nil then table.insert(peds, ped) end end return peds end
local function getAllVehicles() local count = PoolMgr.GetCurrentVehicleCount() - 1; local vehs = {} for i = 0, count do local veh = PoolMgr.GetVehicle(i); if veh ~= nil then table.insert(vehs, veh) end end return vehs end
local function loadAndPlayAnim(dict, anim, blendIn, flags) local pid = Natives.InvokeInt(0x43A66C31C68491C0, GTA.GetLocalPlayerId()) Natives.InvokeVoid(0xD3BD40951412FEF6, dict) local timeout = 0 while not Natives.InvokeBool(0xD031A9162D01088C, dict) and timeout < 100 do Script.Yield(10); timeout = timeout + 1 end if Natives.InvokeBool(0xD031A9162D01088C, dict) then Natives.InvokeVoid(0xEA47FE3719165B94, pid, dict, anim, blendIn, -2.0, -1, flags, 0, true, true, false) end end
local function resetState() forceActive = false; animWaiting = false; pushPending = false; pushDelay = 0 ragdolled = false; ragCount = 0 SET_TIME_SCALE(1.0) CLEAR_PED_TASKS(getPlayerPed()) end
local function getDistance3D(pid, entity) local a = GET_ENTITY_COORDS(pid); local b = GET_ENTITY_COORDS(entity) local dx = a.x-b.x; local dy = a.y-b.y; local dz = a.z-b.z return math.sqrt(dx*dx + dy*dy + dz*dz) end
local function releaseTarget(pid, playerCoord) if targetGrabbed == nil then return end loadAndPlayAnim(PushAnimCore, PushAnim, 10.0, 1) Script.Yield(500) SET_ENTITY_INVINCIBLE(targetGrabbed, false) local coord = GET_ENTITY_COORDS(targetGrabbed) local fx = coord.x-playerCoord.x; local fy = coord.y-playerCoord.y; local fz = coord.z-playerCoord.z local len = math.sqrt(fx*fx+fy*fy+fz*fz) if len > 0 then fx=fx/len; fy=fy/len; fz=fz/len end for _ = 1, 3 do APPLY_FORCE_TO_ENTITY(targetGrabbed,1,targetForce*fx,targetForce*fy,targetForce*fz+40,math.random(-5,5),math.random(-5,5),math.random(-5,5),true,false,true,true,true,true) end PLAY_SOUND_FRONTEND(-1, "FocusOut", "HintCamSounds", true) Script.Yield(400) CLEAR_PED_TASKS(pid) targetGrabbed = nil end
function GV() local v = LV() return v and v:GetAddress() or nil end
local function getStationDisplayName(internalName) return vr_radio_display_map[internalName] or internalName end
function HSLToRGB(h, s, l) local r, g, b
function hue2rgb(p, q, t) if t < 0 then t = t + 1 end if t > 1 then t = t - 1 end if t < 1/6 then return p + (q - p) * 6 * t end if t < 1/2 then return q end if t < 2/3 then return p + (q - p) * (2/3 - t) * 6 end return p end
q = l < 0.5 and l * (1 + s) or l + s - l * s
p = 2 * l - q r, g, b = hue2rgb(p, q, h + 1/3), hue2rgb(p, q, h), hue2rgb(p, q, h - 1/3) return math.floor(r * 255), math.floor(g * 255), math.floor(b * 255) end
function RequestModelAndWait(modelHash) VR_InvokeVoid(0x963D27A58DF860AC, modelHash) local timeout = 0 while not VR_InvokeBool(0x98A4EB5D89A0C952, modelHash) and timeout < 200 do Script.Yield(15) timeout = timeout + 1 end return VR_InvokeBool(0x98A4EB5D89A0C952, modelHash) end
function isConnected(pid) if pid < 0 or pid >= MAX_PLAYERS then return false end if pid == 0 then return false end if pid == Natives.InvokeInt(0x4F8644AF03D0E0D6) then return false end return Natives.InvokeBool(0x93DC1BE4E1ABE9D1, pid) end
function GetVroomDirectory() local userProfile = os.getenv("USERPROFILE") local oneDrive = os.getenv("OneDrive") local standardPath = userProfile .. "\\Documents\\Cherax\\Lua\\VROOM\\" if oneDrive then local oneDrivePath = oneDrive .. "\\Documents\\Cherax\\Lua\\VROOM\\" local testFile = io.open(oneDrivePath .. "settings.json", "r") if testFile then testFile:close() return oneDrivePath end testFile = io.open(oneDrivePath .. "highscore.json", "r") if testFile then testFile:close() return oneDrivePath end end return standardPath end vroomDir = GetVroomDirectory()
