valid_indices = {3, 4, 5, 6, 7, 9, 10, 11} xenon_colors = { {r=0,   g=255, b=150}, {r=100, g=255, b=0}, {r=255, g=255, b=0}, {r=255, g=215, b=0}, {r=255, g=165, b=0}, {r=255, g=0,   b=0}, {r=255, g=0,   b=100}, {r=150, g=0,   b=255} }
current_hyd_force = 0.20 hyd_toggle = false rainbow_speed = 0.75 rainbow_toggle_ref = false last_veh = 0 last_wheel_veh = 0 lastXenonStep = -1 plate_base_text = "VROOM    " plate_timer = 0 plate_scroll_speed = 15 scrolling_plate_text = "VROOM    " plate_user_speed = 4.0 last_scroll_time = 0 scroll_plate_ref = false
FeatureMgr.AddFeature(Utils.Joaat("VR_HYDR_FORCE"), "Hydraulic Force", eFeatureType.SliderFloat, "Adjust Hydraulic Power\n ", function(f) current_hyd_force = f:GetFloatValue() end):SetLimitValues(0.0, 0.65):SetFloatValue(0.3)
