FeatureMgr.AddFeature(Utils.Joaat("VR_CYCLE_SPEED"), "Rainbow Cycle Speed", eFeatureType.SliderFloat, "Controls How Fast Colors Shift\n ", function(f) rainbow_speed = f:GetFloatValue() end):SetLimitValues(0.1, 3.0):SetFloatValue(0.75)
FeatureMgr.AddFeature(Utils.Joaat("VR_CYCLE_COLORS"), "Rainbow Ride", eFeatureType.Toggle, "Cycles Neons, Paint, Plate,\nSmoke, Xenon & Install\nRegular Activator Rims.\nGo To LSC...\n \n ", function(f) rainbow_toggle_ref = f:IsToggled() end)
FeatureMgr.AddFeature(Utils.Joaat("VR_SCROLL_PLATE"), "Scrolling Plate", eFeatureType.Toggle, "Scrolls Custom Text On Plate\n ", function(f) scroll_plate_ref = f:IsToggled() end)
FeatureMgr.AddFeature(Utils.Joaat("VR_PLATE_SPEED"), "Plate Scroll Speed", eFeatureType.SliderFloat, "Controls How Fast The Plate Scrolls\n ", function(f) plate_user_speed = f:GetFloatValue() end):SetLimitValues(0.5, 30.0):SetFloatValue(4.0)
FeatureMgr.AddFeature(Utils.Joaat("VR_SCROLL_PLATE_INPUT"), "Set Plate Text", eFeatureType.Button, "Click To Enter Custom Text For Your Plate\n(Use Spaces If Less Than 8 Characters)\n ", function()
Script.QueueJob(function() Natives.InvokeVoid(0x00DC833F2568DBF6, 1, "FMMC_KEY_TIP8", "", "", "", "", "", 15) while Natives.InvokeInt(0x0CF2B696BBF945AE) == 0 do Script.Yield(10) end if Natives.InvokeInt(0x0CF2B696BBF945AE) == 1 then local inputText = Natives.InvokeString(0x8362B09B91893647) if inputText and #inputText > 0 then scrolling_plate_text = inputText .. "    " if GUI and GUI.AddToast then GUI.AddToast("Scrolling Plate", "Text Updated to: " .. inputText, 3000) end end end end) end)
Script.RegisterLooped(function() local veh = vr_myVehicle() if hyd_toggle and vr_isDriving() then if veh ~= 0 then local height = Natives.InvokeFloat(0x1DD55701034110E5, veh) or 0.0 if height < 1.0 then local PITCH_POWER = current_hyd_force * 1.4 local ROLL_POWER  = current_hyd_force * 0.3 local isHoldingX = VR_IS_CONTROL_PRESSED(0, 73)
if isHoldingX then if VR_IS_CONTROL_PRESSED(0, 111) or VR_IS_CONTROL_PRESSED(0, 61) then VR_InvokeVoid(0xC5F68BE9613E2D18, veh, 1, 0.0, 0.0, PITCH_POWER, 0.0, 2.5, 0.0, true, true, true, true, false, true) elseif VR_IS_CONTROL_PRESSED(0, 112) or VR_IS_CONTROL_PRESSED(0, 36) then VR_InvokeVoid(0xC5F68BE9613E2D18, veh, 1, 0.0, 0.0, PITCH_POWER, 0.0, -2.5, 0.0, true, true, true, true, false, true) elseif VR_IS_CONTROL_PRESSED(0, 34) then VR_InvokeVoid(0xC5F68BE9613E2D18, veh, 1, 0.0, ROLL_POWER, ROLL_POWER, 7.5, 2.45, 0.0, true, true, true, true, false, true) elseif VR_IS_CONTROL_PRESSED(0, 35) then VR_InvokeVoid(0xC5F68BE9613E2D18, veh, 1, 0.0, -ROLL_POWER, ROLL_POWER, -7.5, 2.45, 0.0, true, true, true, true, false, true) end end end end end
if rainbow_toggle_ref then if veh ~= 0 then if veh ~= last_veh then VR_InvokeVoid(0x2A1F4F37F95BAD08, veh, 22, true) VR_InvokeVoid(0x2A1F4F37F95BAD08, veh, 20, true) lastXenonStep = -1 last_veh = veh end if veh ~= last_wheel_veh then VR_InvokeVoid(0x1F2AA07F00B3217A, veh, 0) VR_InvokeVoid(0x487EB21CC7295BA1, veh, 8) VR_InvokeVoid(0x6AF0636DDEDCB6DD, veh, 23, 55, true) VR_InvokeVoid(0x1F2AA07F00B3217A, veh, 1) last_wheel_veh = veh end
if valid_indices and xenon_colors then local time = os.clock() * rainbow_speed local list_count = #valid_indices local current_pos = math.floor(time) % list_count + 1 local next_pos = (current_pos % list_count) + 1 local fraction = time % 1.0 local c1 = xenon_colors[current_pos] local c2 = xenon_colors[next_pos] local r = math.floor(c1.r + (c2.r - c1.r) * fraction) local g = math.floor(c1.g + (c2.g - c1.g) * fraction) local b = math.floor(c1.b + (c2.b - c1.b) * fraction) VR_InvokeVoid(0x9088EB5A43FFB0A1, veh, 5) for i = 0, 3 do SET_VEHICLE_NEON_LIGHT_ENABLED(veh, i, true) end VR_InvokeVoid(0x7141766F91D15BEA, veh, r, g, b) VR_InvokeVoid(0x36CED73BFED89754, veh, r, g, b) VR_InvokeVoid(0x8E0A582209A62695, veh, r, g, b) VR_InvokeVoid(0xB5BA80F839791C0F, veh, r, g, b) local actual_xenon_idx = valid_indices[current_pos] if lastXenonStep ~= actual_xenon_idx then VR_InvokeVoid(0xE41033B25D003A07, veh, actual_xenon_idx) lastXenonStep = actual_xenon_idx end end plate_timer = plate_timer + 1 if plate_timer >= plate_scroll_speed then plate_base_text = string.sub(plate_base_text, 2) .. string.sub(plate_base_text, 1, 1) VR_InvokeVoid(0x95A88F0B409CDA47, veh, plate_base_text) plate_timer = 0 end else last_wheel_veh = 0 last_veh = 0 end end if scroll_plate_ref then if veh ~= 0 and #scrolling_plate_text > 0 then local current_time = os.clock() local interval = 1.0 / plate_user_speed if (current_time - last_scroll_time) >= interval then scrolling_plate_text = string.sub(scrolling_plate_text, 2) .. string.sub(scrolling_plate_text, 1, 1) VR_InvokeVoid(0x95A88F0B409CDA47, veh, scrolling_plate_text) last_scroll_time = current_time end end end Script.Yield(10) return true end)
-- Aggressive NPC
CachedPeds = {} function PoolMgr.GetCachedPeds() local count = PoolMgr.GetMaxPedCount() if #CachedPeds > 1000 then CachedPeds = {} end for i = 0, count - 1 do local ped = PoolMgr.GetPed(i) if nil ~= ped and 0 ~= ped and ped ~= getPlayerPed() and (not table.find or not table.find(CachedPeds, ped)) then table.insert(CachedPeds, ped) end end local vehCount = PoolMgr.GetCurrentVehicleCount() and (PoolMgr.GetCurrentVehicleCount() - 1) or 0 for i = 0, vehCount do local veh = PoolMgr.GetVehicle(i) if nil ~= veh and 0 ~= veh and (not table.find or not table.find(CachedPeds, veh)) then table.insert(CachedPeds, veh) end end Script.Yield(500) end
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_AGGRESSIVE_NPC"), "Aggressive NPC", eFeatureType.Toggle, "Make Nearby Peds Attack The Selected Player\n ", function(feature) while feature:IsToggled() do PoolMgr.GetCachedPeds() local playerID = feature:GetPlayerIndex() local ped = InvokeInt(0x50FAC3A3E030A6E1, playerID) if CachedPeds then for _, entity in pairs(CachedPeds) do if entity and entity ~= 0 then if not InvokeBool(0x12534C348C6CB68B, entity) then if not InvokeBool(0x01BF60A500E28887, entity) then InvokeBool(0xB69317BF5E782347, entity) end local netID = InvokeInt(0xA11700682F3AD45C, entity) InvokeVoid(0x299EEB23175895FC, netID, false) InvokeVoid(0x9F8AA94D6D97DBF4, entity, true) if InvokeBool(0x997ABD671D25CA0B, entity, false) then local vehicle = InvokeInt(0x9A9112A0FE9A4713, entity, false) local vehNetID = InvokeInt(0xA11700682F3AD45C, vehicle) InvokeVoid(0x299EEB23175895FC, vehNetID, false) local driver = InvokeInt(0xBB40DD2270B65366, vehicle, -1, false) if driver ~= 0 and not InvokeBool(0x12534C348C6CB68B, driver) then InvokeVoid(0xA731F608CA104E3C, driver, 1.0 + 0.0) InvokeVoid(0x9454528DF15D657A, driver, vehicle, ped, 6, 100.0 + 0.0, 4981344, 2000.0 + 0.0, 0.0 + 0.0, true) end else InvokeVoid(0xF166E48407BAC484, entity, ped, 0, 16) end end end end end Script.Yield(250) end local playerID = feature:GetPlayerIndex() local ped = InvokeInt(0x50FAC3A3E030A6E1, playerID) if CachedPeds then for _, entity in pairs(CachedPeds) do if entity and entity ~= 0 and not InvokeBool(0x12534C348C6CB68B, entity) then InvokeVoid(0xA731F608CA104E3C, entity, 0.0 + 0.0) InvokeVoid(0xE1EF3C1216AFF2CD, entity) InvokeVoid(0x22B0D0E37CCB840D, entity, ped, 1000.0 + 0.0, 9999, true, false) end end end end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_AGGRESSIVE_NPC_ENHANCED"), "Aggressive NPC", eFeatureType.Toggle, "Make Nearby Peds Attack The Selected Player\n ", function(feature) while feature:IsToggled() do local playerID = feature:GetPlayerIndex() local targetPed = VR_InvokeInt(0x50FAC3A3E030A6E1, playerID) if targetPed and targetPed ~= 0 then local playerCoords = VR_GET_ENTITY_COORDS(targetPed, true) local peds = getAllPeds() local vehicles = getAllVehicles() if playerCoords then for _, ped in ipairs(peds) do if ped and ped ~= 0 and ped ~= getPlayerPed() then if not VR_InvokeBool(0x3317DEDB88C95038, ped, true) then local pedCoords = VR_GET_ENTITY_COORDS(ped, true) if pedCoords then local dx = pedCoords.x - playerCoords.x local dy = pedCoords.y - playerCoords.y local dz = pedCoords.z - playerCoords.z local distSq = (dx * dx) + (dy * dy) + (dz * dz) if distSq < (75.0 * 75.0) then VR_InvokeVoid(0xAD738C3085FE7E11, ped, true, true) VR_InvokeVoid(0xE1EF3C1216AFF2CD, ped) if not VR_InvokeBool(0x01BF60A500E28887, ped) then VR_InvokeBool(0xB69317BF5E782347, ped) end VR_InvokeVoid(0xBE8796DB2B90A437, ped, 46, true) VR_InvokeVoid(0xBE8796DB2B90A437, ped, 5, true) VR_InvokeVoid(0x9F8AA94D6D97DBF4, ped, true) VR_InvokeVoid(0xF166E48407BAC484, ped, targetPed, 0, 16) end end end end end for _, veh in ipairs(vehicles) do if veh and veh ~= 0 then local driver = VR_InvokeInt(0xBB40DD2270B65366, veh, -1, false) if driver ~= 0 and driver ~= getPlayerPed() then if not VR_InvokeBool(0x3317DEDB88C95038, driver, true) then VR_InvokeVoid(0xAD738C3085FE7E11, veh, true, true) VR_InvokeVoid(0xAD738C3085FE7E11, driver, true, true) VR_InvokeVoid(0xE1EF3C1216AFF2CD, driver) VR_InvokeVoid(0x7AEFB85C1D49DEB6, driver, 1.0) VR_InvokeVoid(0x9454528DF15D657A, driver, veh, targetPed, 6, 100.0 + 0.0, 0, 2000.0 + 0.0, 0.0 + 0.0, true) end end end end end end Script.Yield(600) end local peds = getAllPeds() for _, ped in ipairs(peds) do if ped and ped ~= 0 then VR_InvokeVoid(0xE1EF3C1216AFF2CD, ped) end end end)
