function saveWalkStyleFavorites() local file = io.open(walkStyleFavoritesPath, "w") if file then file:write("{\n  \"walk_styles\": [\n") local first = true for name, _ in pairs(favoriteWalkStyles) do if not first then file:write(",\n") end file:write("    \"" .. name .. "\"") first = false end file:write("\n  ],\n  \"animations\": [\n") first = true for name, _ in pairs(favoriteAnimations) do if not first then file:write(",\n") end file:write("    \"" .. name .. "\"") first = false end file:write("\n  ],\n  \"combos\": [\n") first = true for comboStr, _ in pairs(favoriteAnimationCombos) do if not first then file:write(",\n") end file:write("    \"" .. comboStr .. "\"") first = false end file:write("\n  ],\n  \"props\": [\n") first = true for propStr, _ in pairs(favoritePropPlacements) do if not first then file:write(",\n") end file:write("    \"" .. propStr .. "\"") first = false end file:write("\n  ]\n}") file:close() else print("[Walk_Style] Error: Could Not Write Favorites To " .. walkStyleFavoritesPath) end end
function loadWalkStyleFavorites() local file = io.open(walkStyleFavoritesPath, "r") if file then local contents = file:read("*a") file:close() if contents then local current_section = "" for line in string.gmatch(contents, "[^\r\n]+") do if string.match(line, '"walk_styles"') then current_section = "walk_styles" elseif string.match(line, '"animations"') then current_section = "animations" elseif string.match(line, '"combos"') then current_section = "combos" elseif string.match(line, '"props"') then current_section = "props" else local name = string.match(line, '"([^"]+)"') if name then if current_section == "walk_styles" then favoriteWalkStyles[name] = true elseif current_section == "animations" then favoriteAnimations[name] = true elseif current_section == "combos" then favoriteAnimationCombos[name] = true elseif current_section == "props" then favoritePropPlacements[name] = true end end end end end end end loadWalkStyleFavorites()
function getWalkStylePlayerPed() local localPed = GTA.GetLocalPed() return localPed and GTA.PointerToHandle(localPed) or 0 end
function deleteAttachedProp() if attachedPropEntity ~= 0 then local ent = attachedPropEntity attachedPropEntity = 0 Script.QueueJob(function() if Natives.InvokeBool(0x7239B21A38F536BA, ent) then Natives.InvokeVoid(0xAD738C3085FE7E11, ent, true, true) local ptr = Memory.AllocInt() Memory.WriteInt(ptr, ent) Natives.InvokeVoid(0x539E0AE3E6634B9F, ptr) Memory.Free(ptr) end end) end end
function attachSelectedProp() Script.QueueJob(function() deleteAttachedProp() Script.Yield(100) local pedHandle = getWalkStylePlayerPed() if not pedHandle or pedHandle == 0 then return end local hash = Natives.InvokeInt(0xD24D37CC275948CC, selectedPropModel) if not Natives.InvokeBool(0x98A4EB5D89A0C952, hash) then Natives.InvokeVoid(0x963D27A58DF860AC, hash) local timeout = 0 while not Natives.InvokeBool(0x98A4EB5D89A0C952, hash) and timeout < 40 do Script.Yield(50) timeout = timeout + 1 end end if Natives.InvokeBool(0x98A4EB5D89A0C952, hash) then attachedPropEntity = Natives.InvokeInt(0x509D5878EB39E842, hash, 0.0, 0.0, 0.0, false, false, false) if attachedPropEntity ~= 0 then local boneIndex = Natives.InvokeInt(0x3F428D08BE5AAE31, pedHandle, selectedBoneId) Natives.InvokeVoid(0x6B9BBD38AB0796DF, attachedPropEntity, pedHandle, boneIndex, propPosX, propPosY, propPosZ, propRotX, propRotY, propRotZ, false, false, false, false, 2, true ) end end end) end
function updatePropAttachment() if attachedPropEntity ~= 0 then local pedHandle = getWalkStylePlayerPed() if pedHandle ~= 0 then local boneIndex = Natives.InvokeInt(0x3F428D08BE5AAE31, pedHandle, selectedBoneId) Natives.InvokeVoid(0x6B9BBD38AB0796DF, attachedPropEntity, pedHandle, boneIndex, propPosX, propPosY, propPosZ, propRotX, propRotY, propRotZ, false, false, false, false, 2, true ) end end end
function saveCurrentAnimationCombo() local comboStr = string.format("%s|%s|%s|%.2f|%.2f|%.2f|%.2f|%.2f|%.2f", selectedAnimation, selectedPropName, selectedBoneName, propPosX, propPosY, propPosZ, propRotX, propRotY, propRotZ) favoriteAnimationCombos[comboStr] = true saveWalkStyleFavorites() end
function saveCurrentPropPlacement() local propStr = string.format("%s|%s|%.2f|%.2f|%.2f|%.2f|%.2f|%.2f", selectedPropName, selectedBoneName, propPosX, propPosY, propPosZ, propRotX, propRotY, propRotZ) favoritePropPlacements[propStr] = true saveWalkStyleFavorites() end
function applyWalkStyle(clipName) Script.QueueJob(function() local pedHandle = getWalkStylePlayerPed() local pedWaitTimeout = 0 while (not pedHandle or pedHandle == 0) and pedWaitTimeout < 100 do Script.Yield(100) pedHandle = getWalkStylePlayerPed() pedWaitTimeout = pedWaitTimeout + 1 end if not pedHandle or pedHandle == 0 then return end if clipName == "" or not walkStyleEnabled then Natives.InvokeVoid(0xAA74EC0CB0AAEA2C, pedHandle, 0.0) return end local attempts = 0 while attempts < 5 and not Natives.InvokeBool(0x318234F4F3738AF3, clipName) do Natives.InvokeVoid(0xD2A71E1A77418A49, clipName) local timeout = 0 while not Natives.InvokeBool(0x318234F4F3738AF3, clipName) and timeout < 60 do Script.Yield(50) timeout = timeout + 1 end attempts = attempts + 1 end if Natives.InvokeBool(0x318234F4F3738AF3, clipName) then pedHandle = getWalkStylePlayerPed() if pedHandle and pedHandle ~= 0 then Natives.InvokeVoid(0xAF8A94EDE7712BEF, pedHandle, clipName, 1.0) end end end) end
function applyStandingAnimation() Script.QueueJob(function() local pedHandle = getWalkStylePlayerPed() if not pedHandle or pedHandle == 0 then return end if selectedAnimDict == "" then return end if not Natives.InvokeBool(0xD031A9162D01088C, selectedAnimDict) then Natives.InvokeVoid(0xD3BD40951412FEF6, selectedAnimDict) local timeout = 0 while not Natives.InvokeBool(0xD031A9162D01088C, selectedAnimDict) and timeout < 40 do Script.Yield(50) timeout = timeout + 1 end end if Natives.InvokeBool(0xD031A9162D01088C, selectedAnimDict) then local base_flags = bypassLowerBody and 48 or 32 local anim_flags = animLooped and (base_flags + 1) or base_flags Natives.InvokeVoid(0xEA47FE3719165B94, pedHandle, selectedAnimDict, selectedAnimName, 8.0, -8.0, -1, anim_flags, 0.0, false, false, false ) animationActive = true end end) end
function cancelStandingAnimation() Script.QueueJob(function() local pedHandle = getWalkStylePlayerPed() if not pedHandle or pedHandle == 0 then return end if bypassLowerBody then Natives.InvokeVoid(0x176CECF6F920D707, pedHandle) else Natives.InvokeVoid(0xE1EF3C1216AFF2CD, pedHandle) end if not keepPropOnStop then if attachedPropEntity ~= 0 then Natives.InvokeVoid(0x961AC54BF0613F5D, attachedPropEntity, true, true) end end animationActive = false end) end
function getSortedWalkStyles() local sorted = {} local favs = {} local others = {} for _, style in ipairs(walkStyles) do if favoriteWalkStyles[style.name] then table.insert(favs, style) else table.insert(others, style) end end for _, s in ipairs(favs) do table.insert(sorted, s) end for _, s in ipairs(others) do table.insert(sorted, s) end return sorted end
function getSortedAnimations() local filtered = {} local query = string.lower(animSearchFilter and animSearchFilter.text or "") for _, anim in ipairs(standing_animations) do if query == "" or string.find(string.lower(anim.name), query, 1, true) then table.insert(filtered, anim) end end table.sort(filtered, function(a, b) local aFav = favoriteAnimations[a.name] and 1 or 0 local bFav = favoriteAnimations[b.name] and 1 or 0 if aFav ~= bFav then return aFav > bFav end return a.name < b.name end) return filtered end
function getFilteredProps() local filtered = {} local query = string.lower(propSearchFilter.text or "") for _, p in ipairs(propsList) do if query == "" or string.find(string.lower(p.name), query, 1, true) then table.insert(filtered, p) end end return filtered end
function getFilteredAnimations() local filtered = {} local query = string.lower(animSearchFilter and animSearchFilter.text or "") for _, anim in ipairs(standing_animations) do if query == "" or string.find(string.lower(anim.name), query, 1, true) then table.insert(filtered, anim) end end table.sort(filtered, function(a, b) local aFav = favoriteAnimations[a.name] and 1 or 0 local bFav = favoriteAnimations[b.name] and 1 or 0 if aFav ~= bFav then return aFav > bFav end return a.name < b.name end) return filtered end
function getSortedAnimationCombos() local sorted = {} for comboStr, _ in pairs(favoriteAnimationCombos) do table.insert(sorted, comboStr) end table.sort(sorted) return sorted end
function getSortedPropPlacements() local sorted = {} for propStr, _ in pairs(favoritePropPlacements) do table.insert(sorted, propStr) end table.sort(sorted) return sorted end
Script.QueueJob(function() while true do if standingAnimEnabled then if Natives.InvokeBool(0x580417101DDB492F, 0, 73) then if animationActive then cancelStandingAnimation() else applyStandingAnimation() end end else if animationActive then cancelStandingAnimation() end end Script.Yield(0) end end)
Script.QueueJob(function() local lastPedHandle = getWalkStylePlayerPed() local wasDead = false while true do if walkStyleEnabled and selectedWalkStyleClip ~= "" then local currentPed = getWalkStylePlayerPed() if currentPed ~= 0 then local pedChanged = (currentPed ~= lastPedHandle) lastPedHandle = currentPed local isDead = Natives.InvokeBool(0x3317DEDB88C95038, currentPed, true) if isDead then wasDead = true elseif wasDead and not isDead then wasDead = false Script.Yield(1500) applyWalkStyle(selectedWalkStyleClip) elseif pedChanged then Script.Yield(3000) applyWalkStyle(selectedWalkStyleClip) end else lastPedHandle = 0 end else lastPedHandle = getWalkStylePlayerPed() wasDead = false end Script.Yield(200) end end)
function renderAnimationsTab() if ClickGUI.BeginCustomChildWindow("Walk Styles") then ImGui.Spacing() local oldEnabled = walkStyleEnabled walkStyleEnabled = ImGui.Checkbox("Enable Walk Style", walkStyleEnabled) if walkStyleEnabled ~= oldEnabled then applyWalkStyle(walkStyleEnabled and selectedWalkStyleClip or "") end local currentDisplay = (favoriteWalkStyles[selectedWalkStyle] and "★ " or "") .. (selectedWalkStyle ~= "" and selectedWalkStyle or "Select Walk Style...") if ImGui.BeginCombo("Select Walk Style", currentDisplay) then for _, style in ipairs(getSortedWalkStyles()) do local displayName = (favoriteWalkStyles[style.name] and "★ " or "") .. style.name local isSelected = selectedWalkStyle == style.name if ImGui.Selectable(displayName, isSelected) then selectedWalkStyle = style.name selectedWalkStyleClip = style.clip if walkStyleEnabled then applyWalkStyle(selectedWalkStyleClip) end end if isSelected then ImGui.SetItemDefaultFocus() end end ImGui.EndCombo() end if favoriteWalkStyles[selectedWalkStyle] then if ImGui.Button("Unfavorite Walk Style") then favoriteWalkStyles[selectedWalkStyle] = nil saveWalkStyleFavorites() end else if ImGui.Button("Favorite Walk Style") then if selectedWalkStyle ~= "" then favoriteWalkStyles[selectedWalkStyle] = true saveWalkStyleFavorites() end end end ClickGUI.EndCustomChildWindow() end
if ClickGUI.BeginCustomChildWindow("Standing Animations") then ImGui.Spacing() local oldAnimEnabled = standingAnimEnabled standingAnimEnabled = ImGui.Checkbox("Enable Standing Animations (Press X)", standingAnimEnabled) if not standingAnimEnabled and oldAnimEnabled and animationActive then cancelStandingAnimation() end local oldBypass = bypassLowerBody bypassLowerBody = ImGui.Checkbox("Bypass Lower Body Restrictions", bypassLowerBody) if bypassLowerBody ~= oldBypass and animationActive then applyStandingAnimation() end local oldLoop = animLooped animLooped = ImGui.Checkbox("Loop Animation", animLooped) if animLooped ~= oldLoop and animationActive then applyStandingAnimation() end keepPropOnStop = ImGui.Checkbox("Keep Prop Attached", keepPropOnStop) animSearchFilter.text = ImGui.InputText("Search Animation", animSearchFilter.text or "") local currentDisplay = (favoriteAnimations[selectedAnimation] and "★ " or "") .. selectedAnimation if ImGui.BeginCombo("Select Animation", currentDisplay) then for _, anim in ipairs(getFilteredAnimations()) do local displayName = (favoriteAnimations[anim.name] and "★ " or "") .. anim.name local isSelected = selectedAnimation == anim.name if ImGui.Selectable(displayName, isSelected) then selectedAnimation = anim.name selectedAnimDict = anim.dict selectedAnimName = anim.anim animLooped = anim.looped ~= false end
if isSelected then ImGui.SetItemDefaultFocus() end end ImGui.EndCombo() end if favoriteAnimations[selectedAnimation] then if ImGui.Button("Unfavorite Animation") then favoriteAnimations[selectedAnimation] = nil saveWalkStyleFavorites() end else if ImGui.Button("Favorite Animation") then favoriteAnimations[selectedAnimation] = true saveWalkStyleFavorites() end end ImGui.SameLine() if standingAnimEnabled then if ImGui.Button("Play Animation (Or Press X)") then applyStandingAnimation() end ImGui.SameLine() if ImGui.Button("Stop Animation") then cancelStandingAnimation() end else ImGui.TextDisabled("Enable Standing Animations To Use") end ClickGUI.EndCustomChildWindow() end if ClickGUI.BeginCustomChildWindow("Prop Attachments") then ImGui.Spacing() propSearchFilter.text = ImGui.InputText("Search Prop", propSearchFilter.text or "") if ImGui.BeginCombo("Select Prop", selectedPropName) then for _, prop in ipairs(getFilteredProps()) do if ImGui.Selectable(prop.name, selectedPropName == prop.name) then selectedPropName = prop.name selectedPropModel = prop.model end end ImGui.EndCombo() end if ImGui.BeginCombo("Select Bone", selectedBoneName) then for _, bone in ipairs(bonesList) do if ImGui.Selectable(bone.name, selectedBoneName == bone.name) then selectedBoneName = bone.name selectedBoneId = bone.id end end ImGui.EndCombo() end
propUpdateNeeded = false local newX = ImGui.SliderFloat("X Offset", propPosX, -1.5, 1.5) if newX ~= propPosX then propPosX = newX; propUpdateNeeded = true end local newY = ImGui.SliderFloat("Y Offset", propPosY, -1.5, 1.5) if newY ~= propPosY then propPosY = newY; propUpdateNeeded = true end local newZ = ImGui.SliderFloat("Z Offset", propPosZ, -1.5, 1.5) if newZ ~= propPosZ then propPosZ = newZ; propUpdateNeeded = true end local newRX = ImGui.SliderFloat("Pitch (X Rot)", propRotX, -180.0, 180.0) if newRX ~= propRotX then propRotX = newRX; propUpdateNeeded = true end local newRY = ImGui.SliderFloat("Roll (Y Rot)", propRotY, -180.0, 180.0) if newRY ~= propRotY then propRotY = newRY; propUpdateNeeded = true end local newRZ = ImGui.SliderFloat("Yaw (Z Rot)", propRotZ, -180.0, 180.0) if newRZ ~= propRotZ then propRotZ = newRZ; propUpdateNeeded = true end if propUpdateNeeded then updatePropAttachment() end if ImGui.Button("Attach Prop") then attachSelectedProp() end ImGui.SameLine() if ImGui.Button("Drop Prop") then deleteAttachedProp() end ClickGUI.EndCustomChildWindow() end if ClickGUI.BeginCustomChildWindow("Saved Placements & Combos") then ImGui.Spacing() local activePropKey = string.format("%s|%s|%.2f|%.2f|%.2f|%.2f|%.2f|%.2f", selectedPropName, selectedBoneName, propPosX, propPosY, propPosZ, propRotX, propRotY, propRotZ)
currentPropFav = favoritePropPlacements[activePropKey] == true local propDisplay = currentPropFav and ("★ " .. (string.match(activePropKey, "([^|]+|[^|]+)") or "Select Prop Setup...")) or "Select Prop Setup..." if ImGui.BeginCombo("Load Saved Prop", propDisplay) then for _, propStr in ipairs(getSortedPropPlacements()) do local displayName = string.match(propStr, "([^|]+|[^|]+)") or propStr ImGui.Selectable("★ " .. displayName, activePropKey == propStr) if ImGui.IsItemHovered() and ImGui.IsMouseClicked(0) then local parts = {} for part in string.gmatch(propStr, "([^|]+)") do table.insert(parts, part) end if #parts == 8 then selectedPropName = parts[1] selectedBoneName = parts[2] propPosX = tonumber(parts[3]) or 0.0 propPosY = tonumber(parts[4]) or 0.0 propPosZ = tonumber(parts[5]) or 0.0 propRotX = tonumber(parts[6]) or 0.0 propRotY = tonumber(parts[7]) or 0.0 propRotZ = tonumber(parts[8]) or 0.0 for _, prop in ipairs(propsList) do if prop.name == selectedPropName then selectedPropModel = prop.model break end end for _, bone in ipairs(bonesList) do if bone.name == selectedBoneName then selectedBoneId = bone.id break end end attachSelectedProp() end end end ImGui.EndCombo() end if currentPropFav then if ImGui.Button("Unfavorite Prop Placement") then favoritePropPlacements[activePropKey] = nil saveWalkStyleFavorites() end else
if ImGui.Button("Save Current Prop Placement") then saveCurrentPropPlacement() end end ImGui.Spacing() local activeComboKey = string.format("%s|%s|%s|%.2f|%.2f|%.2f|%.2f|%.2f|%.2f", selectedAnimation, selectedPropName, selectedBoneName, propPosX, propPosY, propPosZ, propRotX, propRotY, propRotZ) local currentComboFav = favoriteAnimationCombos[activeComboKey] == true local comboDisplay = currentComboFav and ("★ " .. (string.match(activeComboKey, "([^|]+|[^|]+)") or "Select Combo...")) or "Select Combo..." if ImGui.BeginCombo("Load Favorite Combo", comboDisplay) then for _, comboStr in ipairs(getSortedAnimationCombos()) do local displayName = string.match(comboStr, "([^|]+|[^|]+)") or comboStr ImGui.Selectable("★ " .. displayName, activeComboKey == comboStr) if ImGui.IsItemHovered() and ImGui.IsMouseClicked(0) then local parts = {} for part in string.gmatch(comboStr, "([^|]+)") do table.insert(parts, part) end if #parts == 9 then selectedAnimation = parts[1] selectedPropName = parts[2] selectedBoneName = parts[3] propPosX = tonumber(parts[4]) or 0.0 propPosY = tonumber(parts[5]) or 0.0 propPosZ = tonumber(parts[6]) or 0.0 propRotX = tonumber(parts[7]) or 0.0 propRotY = tonumber(parts[8]) or 0.0 propRotZ = tonumber(parts[9]) or 0.0 for _, anim in ipairs(standing_animations) do if anim.name == selectedAnimation then selectedAnimDict = anim.dict selectedAnimName = anim.anim
animLooped = anim.looped ~= false break end end for _, prop in ipairs(propsList) do if prop.name == selectedPropName then selectedPropModel = prop.model break end end for _, bone in ipairs(bonesList) do if bone.name == selectedBoneName then selectedBoneId = bone.id break end end if standingAnimEnabled then applyStandingAnimation() end attachSelectedProp() end end end ImGui.EndCombo() end if currentComboFav then if ImGui.Button("Unfavorite Combo") then favoriteAnimationCombos[activeComboKey] = nil saveWalkStyleFavorites() end else if ImGui.Button("Favorite Combo") then saveCurrentAnimationCombo() end end ImGui.SameLine() if ImGui.Button("Save Current Anim + Prop Combo") then saveCurrentAnimationCombo() end ImGui.SameLine() if ImGui.Button("Clear Saved Combos") then favoriteAnimationCombos = {} saveWalkStyleFavorites() end ClickGUI.EndCustomChildWindow() end end
