Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then for vehAddr, original in pairs(modifiedVehicles) do if vehAddr ~= nil and vehAddr ~= 0 then local handlingPtr = Memory.ReadLong(vehAddr + 0x0915) if handlingPtr ~= nil and handlingPtr ~= 0 then Memory.WriteFloat(handlingPtr + 0x00EC, original.suspensionForce) Memory.WriteFloat(handlingPtr + 0x00F0, original.suspensionRebound) end end end modifiedVehicles = {} lastSuspensionCompression = {} return false end local isToggled = FeatureMgr.IsFeatureEnabled(antiCurbHash) local vehAddr = GV() if not isToggled then if vehAddr and modifiedVehicles[vehAddr] then local handlingPtr = Memory.ReadLong(vehAddr + 0x0915) if handlingPtr ~= nil and handlingPtr ~= 0 then Memory.WriteFloat(handlingPtr + 0x00EC, modifiedVehicles[vehAddr].suspensionForce) Memory.WriteFloat(handlingPtr + 0x00F0, modifiedVehicles[vehAddr].suspensionRebound) end modifiedVehicles[vehAddr] = nil lastSuspensionCompression[vehAddr] = nil end return true end
if vehAddr ~= nil and vehAddr ~= 0 then local handlingPtr = Memory.ReadLong(vehAddr + 0x0915) if handlingPtr ~= nil and handlingPtr > 0x10000000000 and handlingPtr < 0x0007FFFFFFFFFFFF then local suspForce = Memory.ReadFloat(handlingPtr + 0x00EC) local suspRebound = Memory.ReadFloat(handlingPtr + 0x00F0) if suspForce ~= nil and suspRebound ~= nil and suspForce > 0.0 and suspRebound > 0.0 then if not modifiedVehicles[vehAddr] then modifiedVehicles[vehAddr] = { suspensionForce = suspForce, suspensionRebound = suspRebound, impactTimer = 0 } end local maxCompression = 0.0 for wheel = 0, 3 do local compression = Natives.InvokeFloat(0x84FD40F56075E816, vehAddr, wheel) if compression ~= nil and compression > maxCompression then maxCompression = compression end end local lastCompression = lastSuspensionCompression[vehAddr] or maxCompression local compressionDelta = maxCompression - lastCompression lastSuspensionCompression[vehAddr] = maxCompression if compressionDelta > 0.12 and maxCompression > 0.35 then modifiedVehicles[vehAddr].impactTimer = 250 end
if modifiedVehicles[vehAddr].impactTimer > 0 then Memory.WriteFloat( handlingPtr + 0x00EC, modifiedVehicles[vehAddr].suspensionForce * 1.35 ) Memory.WriteFloat( handlingPtr + 0x00F0, modifiedVehicles[vehAddr].suspensionRebound * 1.15 ) modifiedVehicles[vehAddr].impactTimer = modifiedVehicles[vehAddr].impactTimer - 16 else Memory.WriteFloat( handlingPtr + 0x00EC, modifiedVehicles[vehAddr].suspensionForce ) Memory.WriteFloat( handlingPtr + 0x00F0, modifiedVehicles[vehAddr].suspensionRebound ) end end end end return true end)
