antilag_enabled = false is_anti_lag_running = false vr_setRevRatio = function(v) local a = GV() if a then Memory.WriteFloat(a + 0x08C8, v + .0) end end vr_setBoostPressure = function(v) local a = GV() if a then Memory.WriteFloat(a + 0x08D4, v + .0) end end vr_boostngears = { [1] = 0.5, [2] = 0.6, [3] = 0.7, [4] = 0.8, [5] = 0.9, [6] = 1.0 }
