Script.RegisterLooped(function() if antilag_enabled then if FeatureMgr.IsFeatureEnabled(Utils.Joaat("VR_LAUNCHRPM")) then GUI.AddToast("Anti-Lag", "Can't Use Anti-Lag With Launch Control", 3000) local antilag_feat = FeatureMgr.GetFeature(Utils.Joaat("VR_ANTILAG")) if antilag_feat then antilag_feat:Toggle() end antilag_enabled = false return true end if VR_IS_CONTROL_JUST_PRESSED(0, 76) then vr_auto_speed = VR_GET_ENTITY_SPEED(vr_myVehicle()) end if VR_IS_CONTROL_PRESSED(0, 76) and VR_IS_CONTROL_PRESSED(0, 71) then repeat Script.Yield() until vr_getRevRatio() > 0.9 or not VR_IS_CONTROL_PRESSED(0, 76) or not VR_IS_CONTROL_PRESSED(0, 71) if VR_IS_CONTROL_PRESSED(0, 76) and VR_IS_CONTROL_PRESSED(0, 71) then repeat vr_setRevRatio(0.9) Script.Yield(100) vr_setRevRatio(0.5) vr_setBoostPressure(1.0) Script.Yield(50) until VR_IS_CONTROL_RELEASED(0, 76) or VR_IS_CONTROL_RELEASED(0, 71) or not antilag_enabled if VR_IS_TOGGLE_MOD_ON(vr_myVehicle(), 18) then local currentGear = vr_getCurrentGear() if not vr_boostngears[currentGear] or vr_boostngears[currentGear] == 0 then VR_SET_VEHICLE_CHEAT_POWER_INCREASE(vr_myVehicle(), 1.0) else VR_SET_VEHICLE_CHEAT_POWER_INCREASE(vr_myVehicle(), vr_boostngears[currentGear]) end end end end end return true end)
