FeatureMgr.AddFeature(Utils.Joaat("VR_AUTO_YEETER"), "Auto Yeeter", eFeatureType.Toggle, "Fling Cars Out Of The Way\nAutomatically When Toggled On\n ", function(f) auto_yeeter_enabled = f:IsToggled() end)
Script.RegisterLooped(function() if not auto_yeeter_enabled then return end local veh = vr_myVehicle() if veh == 0 then return end local current_time = os.clock() if current_time - auto_yeeter_ram_cooldown > 0.15 then local playerSpeed = Natives.InvokeFloat(0xD5037BA82E12416F, veh) if playerSpeed > 8.0 then local playerPos = VR_GET_ENTITY_COORDS(veh, false) local forward = VR_GET_ENTITY_FORWARD_VECTOR(veh) local bumperX = playerPos.x + (forward.x * 4.5) local bumperY = playerPos.y + (forward.y * 4.5) local bumperZ = playerPos.z local allVehs = getAllVehicles() for _, otherVeh in ipairs(allVehs) do if otherVeh ~= veh then local otherPos = VR_GET_ENTITY_COORDS(otherVeh, false) local dx = otherPos.x - bumperX local dy = otherPos.y - bumperY local dz = otherPos.z - bumperZ local dist = math.sqrt(dx*dx + dy*dy + dz*dz) if dist < 6.5 and dist > 0.1 then local dot = (dx * forward.x + dy * forward.y + dz * forward.z) / dist if dot > 0.55 then local forceMult = playerSpeed * 40.0 local pushX = (dx / dist) * forceMult * 0.5 + forward.x * forceMult local pushY = (dy / dist) * forceMult * 0.5 + forward.y * forceMult local pushZ = 1500.0 + (playerSpeed * 2.0) Natives.InvokeVoid(0xC5F68BE9613E2D18, otherVeh, 1, pushX, pushY, pushZ, 0, 0, 0, 0, false, false, true, false, true) Natives.InvokeVoid(0xC5F68BE9613E2D18, otherVeh, 1, pushY * 0.2, -pushX * 0.2, 0, 0, 0, 0, false, false, true, false, true) auto_yeeter_ram_cooldown = current_time end end end end end end end)
