-- Bind Manager
Binds = { folder = vroomDir, global = {}, held = {}, state = 0, searchQuery = "", selectKey = 191, cancelKey = 194, maxKey = 511, maxMouse = 30, maxController = 35, maxWheel = 65, currentTarget = "" } Binds.file = Binds.folder .. "newbinds.json" Binds.oldFile = Binds.folder .. "binds.json"
function ParseOldBinds() local oldFile = io.open(Binds.oldFile, "r") if oldFile then local content = oldFile:read("*all") oldFile:close() if content and #content > 0 then for name, keyStr in string.gmatch(content, '"([^"]+)":(%d+)') do local key = tonumber(keyStr) if key and not Binds.global[name] then Binds.global[name] = { key = key, hash = 0, cachedFeature = nil, cacheAttempted = false } end end end end end
function LoadBinds() local file = io.open(Binds.file, "r") if file then local content = file:read("*all") file:close() if content and #content > 0 then for name, dataStr in string.gmatch(content, '"([^"]+)":({[^}]+})') do local key = tonumber(dataStr:match('"key":(%-?%d+)')) local hash = tonumber(dataStr:match('"hash":(%-?%d+)')) if key and hash then Binds.global[name] = { key = key, hash = hash, cachedFeature = nil, cacheAttempted = false } end end for name, keyStr in string.gmatch(content, '"([^"]+)":(%d+)') do local key = tonumber(keyStr) if key and not Binds.global[name] then Binds.global[name] = { key = key, hash = 0, cachedFeature = nil, cacheAttempted = false } end end else ParseOldBinds() end else ParseOldBinds() end end
function SaveBinds() local file = io.open(Binds.file, "w") if file then local entries = {} for k, v in pairs(Binds.global) do table.insert(entries, string.format('"%s":{"key":%d,"hash":%d}', tostring(k), v.key, v.hash)) end file:write("{" .. table.concat(entries, ",") .. "}") file:close() end end LoadBinds()
Script.RegisterLooped(function() if not FeatureMgr then return end if Binds.state == 1 then local focused = FeatureMgr.GetFocusedFeature() if focused and InvokeBool(0x580417101DDB492F, 0, Binds.selectKey) then Binds.currentTarget = focused:GetName() Binds.state = 2 GUI.AddToast("Bind Manager", "Feature: " .. Binds.currentTarget .. "\nPress Your Key, Controller, or Wheel Input Now.", 4000) elseif InvokeBool(0x580417101DDB492F, 0, Binds.cancelKey) then Binds.state = 0 GUI.AddToast("Bind Manager", "Cancelled.", 2000) end elseif Binds.state == 2 then local captured = false for i = 0, Binds.maxKey do if InvokeBool(0x580417101DDB492F, 0, i) and i ~= Binds.selectKey and i ~= Binds.cancelKey then local f = FeatureMgr.GetFocusedFeature() if f then Binds.global[f:GetName()] = { key = i, hash = f:GetHash(), cachedFeature = nil, cacheAttempted = false } SaveBinds() GUI.AddToast("Bind Manager", "Bound " .. f:GetName() .. " To Key " .. i, 3000) end captured = true break end end if not captured then for i = 0, Binds.maxMouse do if ImGui.IsMouseClicked(i) then local f = FeatureMgr.GetFocusedFeature() if f then Binds.global[f:GetName()] = { key = 1000 + i, hash = f:GetHash(), cachedFeature = nil, cacheAttempted = false } SaveBinds() GUI.AddToast("Bind Manager", "Bound " .. f:GetName() .. " To Mouse " .. i, 3000) end captured = true break end end end
if not captured then for i = 0, Binds.maxController do if InvokeBool(0x580417101DDB492F, 2, i) then local f = FeatureMgr.GetFocusedFeature() if f then Binds.global[f:GetName()] = { key = 2000 + i, hash = f:GetHash(), cachedFeature = nil, cacheAttempted = false } SaveBinds() GUI.AddToast("Bind Manager", "Bound " .. f:GetName() .. " To Controller " .. i, 3000) end captured = true break end end end if not captured then for i = 0, Binds.maxWheel do if InvokeBool(0x580417101DDB492F, 2, i) or InvokeBool(0x580417101DDB492F, 27, i) then local f = FeatureMgr.GetFocusedFeature() if f then Binds.global[f:GetName()] = { key = 3000 + i, hash = f:GetHash(), cachedFeature = nil, cacheAttempted = false } SaveBinds() GUI.AddToast("Bind Manager", "Bound " .. f:GetName() .. " To Wheel Input " .. i, 3000) end captured = true break end end end if captured then Binds.state = 0 end elseif Binds.state == 0 then for name, data in pairs(Binds.global) do if not data.cachedFeature and not data.cacheAttempted then data.cacheAttempted = true if data.hash and data.hash ~= 0 then data.cachedFeature = FeatureMgr.GetFeature(data.hash) end if not data.cachedFeature then local all = FeatureMgr.GetAllFeatures() if all then local count = (type(all.size) == "function") and all:size() or #all for i = 0, count - 1 do local f = all[i] if f and f:GetName() == name then data.cachedFeature = f
if (not data.hash or data.hash == 0) and type(f.GetHash) == "function" then data.hash = f:GetHash() SaveBinds() end break end end end end end local pressed = false if data.key >= 3000 then local wheelIdx = data.key - 3000 pressed = InvokeBool(0x580417101DDB492F, 2, wheelIdx) or InvokeBool(0x580417101DDB492F, 27, wheelIdx) elseif data.key >= 2000 then pressed = InvokeBool(0x580417101DDB492F, 2, data.key - 2000) elseif data.key >= 1000 then pressed = ImGui.IsMouseDown(data.key - 1000) else pressed = InvokeBool(0x580417101DDB492F, 0, data.key) end if pressed then if not Binds.held[name] then if data.cachedFeature then local f = data.cachedFeature if type(f.Fire) == "function" then f:Fire() elseif type(f.Toggle) == "function" and not string.find(name, "Refill") then f:Toggle() elseif type(f.OnClick) == "function" then f:OnClick() end end Binds.held[name] = true end else Binds.held[name] = nil end end end return true end)
