-- Cargobob Module
vr_inCargobob = function() local ped = Natives.InvokeInt(0xD80958FC74E988A6) if not ped then return false end if not Natives.InvokeBool(0x997ABD671D25CA0B, ped, false) then return false end local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) if veh ~= 0 then local modelHash = Natives.InvokeInt(0x9F47B058362C84B5, veh) if modelHash == 0 then return false end if (modelHash == 8261 or modelHash == 8262 or modelHash == 8263 or modelHash == 9042 or modelHash == 17356 or modelHash == 1044954915) then return true end if Natives.InvokeInt(0x29439776AAA00A62, veh) == 15 then return true end end return false end
isMagnetActive = false holdStartTime = 0 magnetSettings = { strength = 0.01 } skyliftAttachedVeh = 0
