Script.RegisterLooped(function() if ShouldUnload() then if isMagnetActive then local heli = vr_myVehicle() if heli ~= 0 then local modelHash = Natives.InvokeInt(0x9F47B058362C84B5, heli) if modelHash == 1044954915 then if skyliftAttachedVeh ~= 0 then Natives.InvokeVoid(0x961AC54BF0613F5D, skyliftAttachedVeh, true, true) end else V(0x9A665550F8DA349B, heli, false) end end end return false end if vr_inCargobob() then local heli = vr_myVehicle() local modelHash = Natives.InvokeInt(0x9F47B058362C84B5, heli) local activateControl = 86 local dPadControl = 176 if modelHash == 1044954915 then if skyliftAttachedVeh ~= 0 then if VR_IS_CONTROL_PRESSED(0, activateControl) or VR_IS_CONTROL_PRESSED(0, dPadControl) then if holdStartTime == 0 then holdStartTime = os.clock() end if (os.clock() - holdStartTime) > 0.5 then Natives.InvokeVoid(0x961AC54BF0613F5D, skyliftAttachedVeh, true, true) skyliftAttachedVeh = 0 isMagnetActive = false holdStartTime = 0 end else holdStartTime = 0 end else if VR_IS_CONTROL_PRESSED(0, activateControl) or VR_IS_CONTROL_PRESSED(0, dPadControl) then if holdStartTime == 0 then holdStartTime = os.clock() end else if holdStartTime > 0 and (os.clock() - holdStartTime) < 0.5 then isMagnetActive = not isMagnetActive end holdStartTime = 0 end if isMagnetActive then local coords = V3(0x3FEF770D40960D5A, heli) if coords then local foundVeh = Natives.InvokeInt(0xF73EB622C4F1689B, coords.x, coords.y, coords.z, 15.0, 0, 70) if foundVeh ~= 0 and foundVeh ~= heli then Natives.InvokeVoid(0x6B9BBD38AB0796DF, foundVeh, heli, 0, 0.0, -2.5, -1.125, 0.0, 0.0, 0.0, false, false, true, false, 2, true) skyliftAttachedVeh = foundVeh end end end end else if VR_IS_CONTROL_PRESSED(0, activateControl) or VR_IS_CONTROL_PRESSED(0, dPadControl) then if holdStartTime == 0 then holdStartTime = os.clock() end if (os.clock() - holdStartTime) > 0.5 then if isMagnetActive then isMagnetActive = false end end else if holdStartTime > 0 and (os.clock() - holdStartTime) < 0.5 then isMagnetActive = not isMagnetActive end holdStartTime = 0 end if isMagnetActive then V(0x9A665550F8DA349B, heli, true) V(0xBCBFCD9D1DAC19E2, heli, magnetSettings.strength) V(0xED8286F71A819BAA, heli, magnetSettings.strength) else V(0x9A665550F8DA349B, heli, false) V(0x66979ACF5102FD2F, heli, 0.0) V(0xBCBFCD9D1DAC19E2, heli, 0.0) V(0xED8286F71A819BAA, heli, 0.0) local attached = I(0x873B82D42AC2B9E5, heli) if attached ~= 0 then VR_DETACH_ENTITY(attached, true, true) end end end else isMagnetActive = false skyliftAttachedVeh = 0 end Script.Yield(10) return true end)
