Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then return false end if FeatureMgr.IsFeatureEnabled(alwaysCrosshairHash) then local playerPed = Natives.InvokeInt(0x43A66C31C68491C0, -1) if playerPed and playerPed ~= 0 then local currentWeaponHash = Natives.InvokeInt(0x0A6DB4965674D243, playerPed) local isInVehicle = Natives.InvokeInt(0x997ABD671D25CA0B, playerPed, false) ~= 0 if (currentWeaponHash and currentWeaponHash ~= 0 and currentWeaponHash ~= 0xA2719263) or isInVehicle then local r, g, b = crosshair_r, crosshair_g, crosshair_b if crosshair_rainbow then  local hueProgress = (os.clock() * (crosshair_rainbow_speed * 0.1)) % 1.0  r, g, b = VR_HSLToRGB(hueProgress, 1.0, 0.5)  end  local dotW = 0.0012 local dotH = dotW * 1.777 Natives.InvokeVoid(0x3A618A217E5154F0, 0.5, 0.5, dotW, dotH, r, g, b, crosshair_opacity, false) local spreadFactor = math.max(0.0, (crosshair_size - 0.421) / (50.0 - 0.421)) local cappedSize = math.min(crosshair_size, 15.0) local lengthFactor = math.max(0.0, (cappedSize - 0.421) / (15.0 - 0.421)) if spreadFactor > 0.0 then local lineThickness = 0.0010 local gap = 0.0020 + (spreadFactor * 0.0200) local lineLen = 0.0015 + (lengthFactor * 0.0040) local vW = lineThickness local vH = lineLen * 1.777 local vOffset = (dotH * 0.5) + gap + (vH * 0.5) Natives.InvokeVoid(0x3A618A217E5154F0, 0.5, 0.5 - vOffset, vW, vH, r, g, b, crosshair_opacity, false) Natives.InvokeVoid(0x3A618A217E5154F0, 0.5, 0.5 + vOffset, vW, vH, r, g, b, crosshair_opacity, false) local hW = lineLen local hH = lineThickness * 1.777 local hOffset = (dotW * 0.5) + gap + (hW * 0.5) Natives.InvokeVoid(0x3A618A217E5154F0, 0.5 - hOffset, 0.5, hW, hH, r, g, b, crosshair_opacity, false) Natives.InvokeVoid(0x3A618A217E5154F0, 0.5 + hOffset, 0.5, hW, hH, r, g, b, crosshair_opacity, false) end end end end return true end)
