function RestoreVehicleAudio(veh) if veh ~= 0 and InvokeBool(0x7239B21A38F536BA, veh) then if FeatureMgr.IsFeatureEnabled(engineSwapHash) and selectedEngine ~= "" then VR_FORCE_USE_AUDIO_GAME_OBJECT(veh, selectedEngine) else VR_FORCE_USE_AUDIO_GAME_OBJECT(veh, "") end end end
applied_vehicle = 0 original_horn_index = -1 was_enabled_last_frame = false sound_playing = false sound_id = -1 engine_horn_active = false saved_radio_station = -1 horn_toggle_hash = Utils.Joaat("VR_CUSTOM_HORNS") horn_combo_hash  = Utils.Joaat("VR_SELECT_HORN") FeatureMgr.AddFeature(horn_toggle_hash, "Custom Horns", eFeatureType.Toggle, "Forces Custom Horn On Any Vehicle\n(Local Only)\n ", function(f) end) combo_feature = FeatureMgr.AddFeature(horn_combo_hash, "", eFeatureType.Combo, "", function(f) end, false) if combo_feature then combo_feature:SetList(gta_horns_list) end
Script.RegisterLooped(function() if ShouldUnload() then return false end local is_enabled = FeatureMgr.IsFeatureEnabled(horn_toggle_hash) local veh = vr_myVehicle() if is_enabled and veh ~= 0 then if veh ~= applied_vehicle then saved_radio_station = InvokeInt(0xE8AF77C4C06ADC93) end local current_station = InvokeInt(0xE8AF77C4C06ADC93) if current_station ~= saved_radio_station then if saved_radio_station == 255 then InvokeVoid(0x1B9C0099CB942AC6, veh, "OFF") else InvokeVoid(0xA619B168B8A8570F, saved_radio_station) end end end if is_enabled then if veh ~= 0 then if combo_feature then local selectedIndex = combo_feature:GetListIndex() local chosenEntry = gta_horns_map[selectedIndex + 1] or gta_horns_map[1] if veh ~= applied_vehicle or not was_enabled_last_frame then original_horn_index = InvokeInt(0x772960298DA26FDB, veh, 14, false) or -1 applied_vehicle = veh end local is_horn_pressed = InvokeBool(0xF3A21BCD95725A4A, 0, 86) if chosenEntry.engine_audio then InvokeVoid(0x6AF0636DDEDCB6DD, veh, 14, -1, false) if is_horn_pressed then if not engine_horn_active then VR_FORCE_USE_AUDIO_GAME_OBJECT(veh, chosenEntry.engine_audio) engine_horn_active = true end else if engine_horn_active then RestoreVehicleAudio(veh) engine_horn_active = false end end elseif chosenEntry.index and chosenEntry.index <= 56 then
if engine_horn_active then RestoreVehicleAudio(veh) engine_horn_active = false end InvokeVoid(0x6AF0636DDEDCB6DD, veh, 14, chosenEntry.index, false) else if engine_horn_active then RestoreVehicleAudio(veh) engine_horn_active = false end InvokeVoid(0x6AF0636DDEDCB6DD, veh, 14, -1, false) if is_horn_pressed then if not sound_playing then sound_id = InvokeInt(0x430386FE9BF80B45) if sound_id ~= -1 then local soundName = "HORN_" .. tostring(chosenEntry.index) InvokeVoid(0xE65F427EB70AB1ED, sound_id, soundName, veh, 0, 0, 0) sound_playing = true end end else if sound_playing then if sound_id ~= -1 then InvokeVoid(0xA3B0C41BA5CC0BB5, sound_id) InvokeVoid(0x353FC880830B88FA, sound_id) end sound_playing = false sound_id = -1 end end end end else applied_vehicle = 0 saved_radio_station = nil end else if sound_playing and sound_id ~= -1 then InvokeVoid(0xA3B0C41BA5CC0BB5, sound_id) InvokeVoid(0x353FC880830B88FA, sound_id) sound_playing = false sound_id = -1 end if engine_horn_active then RestoreVehicleAudio(applied_vehicle) engine_horn_active = false end if applied_vehicle ~= 0 and InvokeBool(0x7239B21A38F536BA, applied_vehicle) then InvokeVoid(0x6AF0636DDEDCB6DD, applied_vehicle, 14, original_horn_index, false) end applied_vehicle = 0 original_horn_index = -1 saved_radio_station = nil end was_enabled_last_frame = is_enabled Script.Yield(0) return true end)
