-- Draggy
vr_roundNumber = function(n, d) local m = 10^(d or 0) return math.floor(n * m + 0.5) / m end
FeatureMgr.AddFeature(Utils.Joaat("VR_DRAGGY"), "Start Draggy", eFeatureType.Button, "Log 0-60 & 1/4 Mile\nHold Gas And E-Brake\nThen Release E-Brake\n ", function() local ped = GTA.GetLocalPed() if not ped then return end local timer, qm, z60 = 0, true, true local pos = ped.Position local timeout = os.clock() + 30.0 while os.clock() < timeout do ped = GTA.GetLocalPed() if not ped then break end if (ped.Position ~= pos) and VR_IS_CONTROL_PRESSED(0, 71) and VR_IS_CONTROL_RELEASED(0, 76) then Script.Yield(50) if VR_IS_CONTROL_RELEASED(0, 76) then timer = os.clock() GUI.AddToast("Draggy", "Draggy In Progress", 3000) while qm do local veh = vr_myVehicle() if veh == 0 then break end if (VR_GET_ENTITY_SPEED(veh) * 2.23694) > 60 and z60 then z60 = false GUI.AddToast("Draggy", "0-60 in "..vr_roundNumber(os.clock()-timer, 3).."s", 5000) end ped = GTA.GetLocalPed() if not ped then break end local cPos = ped.Position local d = math.sqrt((pos.x-cPos.x)^2 + (pos.y-cPos.y)^2 + (pos.z-cPos.z)^2) if (d >= 402.336) and qm then qm = false GUI.AddToast("Draggy", "1/4 mile: "..vr_roundNumber(os.clock()-timer,3).."s", 8000) end Script.Yield() end return end end Script.Yield() end end)
