drift_tires_initialized = false vr_drift_intensity = 0.5 is_drift_tires_applied = false driftTiresHash = Utils.Joaat("VR_DRIFT_TYRES") function ApplyNaturalDrift(veh) if veh ~= 0 then VR_SET_DRIFT_TYRES(veh, true) local powerModifier = 1.0 + (vr_drift_intensity * 0.5) VR_SET_VEHICLE_CHEAT_POWER_INCREASE(veh, powerModifier) end end
