scoreFile = vroomDir .. "highscore.json" VR_OFFSET_1, VR_OFFSET_2, VR_OFFSET_3 = 1234567, 89, 427345
function loadHighScore() local file = io.open(scoreFile, "r") if file then local content = file:read("*a") file:close() local masked = tonumber(content) if masked then local score = (masked - VR_OFFSET_3) / VR_OFFSET_2 return math.floor(score ~ VR_OFFSET_1) end end return 0 end
function saveHighScore(score) local file = io.open(scoreFile, "w") if file then local maskedScore = ((score ~ VR_OFFSET_1) * VR_OFFSET_2) + VR_OFFSET_3 file:write(tostring(maskedScore)) file:close() else print("[VROOM] Error: Could Not Write High Score To " .. scoreFile) end end
-- Drift Points
vr_drifting, vr_grace_timer, vr_in_grace_period = false, 0, false vr_drift_points, vr_drift_highscore = 0, 0 vr_file_highscore = loadHighScore() vr_isWheelspinning = function(v) local s = VR_GET_ENTITY_SPEED(v) local t = math.abs((LV() or {}).Throttle or 0) if s < 5.0 and t > 0.5 then return true elseif s >= 5.0 then return (vr_getRevRatio() > 0.74 and s < (vr_getRevRatio() * 35.0)) end return false end vr_drift_multiplier, vr_multiplier_step, vr_max_multiplier = 1.0, 0.5, 20.0 vr_current_drift_raw, vr_show_speedo, vr_use_mph = 0, false, true drift_initialized = false lastAccumulation = 0
FeatureMgr.AddFeature(Utils.Joaat("VR_DRIFTPOINTS"), "Drift Points", eFeatureType.Toggle, "Display Drift Points And High Score\nCan Be Moved\n ", function(f) end)
Script.RegisterLooped(function() if ShouldUnload() then vr_drifting, vr_in_grace_period, vr_drift_points = false, false, 0 return false end if FeatureMgr.IsFeatureEnabled(Utils.Joaat("VR_DRIFTPOINTS")) then local veh = vr_myVehicle() local vehData = nil if GTA and GTA.GetLocalVehicle then vehData = GTA.GetLocalVehicle() elseif LV then vehData = LV() end if veh ~= 0 and vehData ~= nil then local speedMPH = VR_GET_ENTITY_SPEED(veh) * 2.23694 local isMovingForward = (vr_getCurrentGear() > 0) local isDrifting = isMovingForward and (speedMPH > 10) and (math.abs(vehData.Throttle or 0) > 0.1) and (math.abs(vehData.SteeringAngle or 0) > 0.15 or vr_isWheelspinning(veh)) if isDrifting then vr_drifting, vr_in_grace_period = true, false if (os.clock() - lastAccumulation) > 0.05 then vr_current_drift_raw = vr_current_drift_raw + 5 vr_drift_points = vr_current_drift_raw if (vr_current_drift_raw % 750 == 0) and vr_drift_multiplier < vr_max_multiplier then vr_drift_multiplier = vr_drift_multiplier + vr_multiplier_step end lastAccumulation = os.clock() end elseif vr_drifting then vr_grace_timer, vr_drifting, vr_in_grace_period = os.clock(), false, true elseif vr_in_grace_period and (os.clock() - vr_grace_timer) > 1.5 then local bankedPoints = math.floor(vr_current_drift_raw * vr_drift_multiplier) if bankedPoints > vr_drift_highscore then vr_drift_highscore = bankedPoints end if bankedPoints > vr_file_highscore then vr_file_highscore = bankedPoints saveHighScore(vr_file_highscore) end vr_drift_points, vr_current_drift_raw, vr_drift_multiplier, vr_in_grace_period = 0, 0, 1.0, false end else vr_drifting, vr_in_grace_period, vr_drift_points = false, false, 0 end else vr_drifting, vr_in_grace_period, vr_drift_points = false, false, 0 end Script.Yield(10) return true end)
