function ExecuteEngineSwap(modelName) selectedEngine = modelName if not FeatureMgr.IsFeatureEnabled(engineSwapHash) then return end if modelName == lastSwapModel then return end Script.QueueJob(function() local veh = vr_myVehicle() if veh ~= 0 then lastSwapModel = modelName local rn = VR_GET_PLAYER_RADIO_STATION_NAME() VR_FORCE_USE_AUDIO_GAME_OBJECT(veh, modelName) Script.Yield(100) if not rn or rn == "" then VR_SET_RADIO_TO_STATION_NAME("OFF") else VR_SET_RADIO_TO_STATION_NAME(rn) end GUI.AddToast("Engine Swap", "Swapped to: " .. modelName:upper(), 2000) end end) end
function getFilteredEngines() local filtered = {} local query = string.lower(engineswap_search_filter.text or "") for i, label in ipairs(vr_engineswap_list) do if query == "" or string.find(string.lower(label), query, 1, true) then table.insert(filtered, { label = label, model = vr_engineswap_model_list[i] }) end end return filtered end
