Force = 0.5 targetForce = 150 targetRange = 20 targetHash = Utils.Joaat("ForceTarget") targetGrabbed = nil targetKeyDown = false targetThrowWaiting = false targetThrowDelay = 0 ForceAnimCore = "amb@world_human_aa_coffee@base" ForceAnim     = "base" PushAnimCore  = "anim@mp_player_intcelebrationmale@thumbs_up" PushAnim = "thumbs_up"
function executeThrow(pid, playerCoord) if targetGrabbed == nil then return end SET_ENTITY_INVINCIBLE(targetGrabbed, false) if not NETWORK_HAS_CONTROL_OF_ENTITY(targetGrabbed) then NETWORK_REQUEST_CONTROL_OF_ENTITY(targetGrabbed) end local coord = GET_ENTITY_COORDS(targetGrabbed) local fx = coord.x - playerCoord.x local fy = coord.y - playerCoord.y local fz = coord.z - playerCoord.z local len = math.sqrt(fx*fx + fy*fy + fz*fz) if len > 0 then fx=fx/len; fy=fy/len; fz=fz/len end for _ = 1, 3 do APPLY_FORCE_TO_ENTITY(targetGrabbed, 1, targetForce*fx, targetForce*fy, targetForce*fz+40, 0.0, 0.0, 0.0, true, false, true, true, true, true) end PLAY_SOUND_FRONTEND(-1, "FocusOut", "HintCamSounds", true) CLEAR_PED_TASKS(pid) targetGrabbed = nil targetThrowWaiting = false end
FeatureMgr.AddFeature(targetHash, "Force Target", eFeatureType.Toggle, "Press E To Grab Nearest Vehicle\nAnd Levitate It. Press E Again To Fling.\nRange: " .. targetRange .. "m\n ", function(f) end)
Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then if targetGrabbed then SET_ENTITY_INVINCIBLE(targetGrabbed, false) end targetGrabbed = nil targetKeyDown = false targetThrowWaiting = false return false end if FeatureMgr.IsFeatureEnabled(targetHash) then local pid = getPlayerPed() local playerVeh = GET_VEHICLE_PED_IS_IN(pid) local keyNow = Natives.InvokeBool(0xE2587F8CBBD87B1D, 0, 38) local justPressed = keyNow and not targetKeyDown targetKeyDown = keyNow if justPressed and not targetThrowWaiting then if targetGrabbed == nil then local closest = nil local closestDist = targetRange for _, veh in ipairs(getAllVehicles()) do if veh ~= playerVeh then local d = getDistance3D(pid, veh) if d < closestDist then closestDist = d closest = veh end end end if closest then if not NETWORK_HAS_CONTROL_OF_ENTITY(closest) then NETWORK_REQUEST_CONTROL_OF_ENTITY(closest) end loadAndPlayAnim(ForceAnimCore, ForceAnim, 2.0, 49) SET_ENTITY_INVINCIBLE(closest, true) targetGrabbed = closest PLAY_SOUND_FRONTEND(-1, "FocusOut", "HintCamSounds", true) end else CLEAR_PED_TASKS(pid) loadAndPlayAnim(PushAnimCore, PushAnim, 10.0, 1) targetThrowWaiting = true targetThrowDelay = 13 end end if targetThrowWaiting and targetGrabbed ~= nil then targetThrowDelay = targetThrowDelay + 1 if targetThrowDelay >= 75 then local playerCoord = GET_ENTITY_COORDS(pid) executeThrow(pid, playerCoord) end end if targetGrabbed ~= nil then local loc = GET_ENTITY_COORDS(pid) local cam = GET_GAMEPLAY_CAM_ROT() local camX = ((cam.x + 90) * 0.08) - 2 camX = camX * camX local mx = loc.x - (math.sin(math.rad(cam.z)) * camX) local my = loc.y + (math.cos(math.rad(cam.z)) * camX) local mz = loc.z + 1.5 local vp = GET_ENTITY_COORDS(targetGrabbed) local dist = GET_DISTANCE_BETWEEN_COORDS(loc.x, loc.y, loc.z, vp.x, vp.y, vp.z) if dist > 0 then local vel = GET_ENTITY_VELOCITY(targetGrabbed) APPLY_FORCE_TO_ENTITY(targetGrabbed, 1, -vel.x*0.005+(mx-vp.x)/(dist*2), -vel.y*0.005+(my-vp.y)/(dist*2), 1.0-vel.z+(mz-vp.z)/(dist*2), 0.0, 0.0, 0.0, true, false, true, true, true, true) end end if targetGrabbed ~= nil then Script.Yield(0) else Script.Yield(100) end else if targetGrabbed then SET_ENTITY_INVINCIBLE(targetGrabbed, false) targetGrabbed = nil end targetKeyDown = false targetThrowWaiting = false Script.Yield(100) end return true end)
