FeatureMgr.AddFeature(hornRocketsHash, "Homing Rockets", eFeatureType.Toggle, "Enables Player Lock Missiles On\nHorn Press & Auto-Godmode\n ", function(f) hornRocketsEnabled = f:IsToggled() local playerPed = Natives.InvokeInt(0x43A66C31C68491C0, -1) if hornRocketsEnabled then if playerPed and playerPed ~= 0 then Natives.InvokeVoid(0x3882114BDE571AD4, playerPed, true) local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, playerPed, false) if veh and veh ~= 0 then Natives.InvokeVoid(0x3882114BDE571AD4, veh, true) end end GUI.AddToast("Homing Rockets", "Rockets Enabled (Godmode Active)", 2000) else if playerPed and playerPed ~= 0 then Natives.InvokeVoid(0x3882114BDE571AD4, playerPed, false) local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, playerPed, false) if veh and veh ~= 0 then Natives.InvokeVoid(0x3882114BDE571AD4, veh, false) end end GUI.AddToast("Homing Rockets", "Rockets Disabled", 2000) end end)
