function getNearestPlayerEntity(excludePed) local nearestEntity = nil local shortestDist = horn_rockets_range or 125.0 local myVeh = Natives.InvokeInt(0x9A9112A0FE9A4713, excludePed, false) local friendCount = Natives.InvokeInt(0x203F1CFD823B27A4) or 0 local friendNames = {} for f = 0, friendCount - 1 do local fname = Natives.InvokeString(0xE11EBBB2A783FE8B, f) if fname then friendNames[string.lower(fname)] = true end end for i = 0, 32 do local targetPlayer = Natives.InvokeInt(0x43A66C31C68491C0, i) if targetPlayer and targetPlayer ~= 0 and targetPlayer ~= excludePed then local isFriend = false local playerName = Natives.InvokeString(0x6D0DE6A7B5DA71F8, i) if playerName and friendNames[string.lower(playerName)] then isFriend = true end if not isFriend then local isDead = InvokeBool(0x3317DEDB88C95038, targetPlayer, true) local interiorHandle = InvokeInt(0x2107BA504071A6BB, targetPlayer) local isInInterior = interiorHandle and interiorHandle ~= 0 if InvokeBool(0x7239B21A38F536BA, targetPlayer) and not isDead and not isInInterior then local isInVeh = InvokeBool(0x997ABD671D25CA0B, targetPlayer) local checkEntity = targetPlayer local targetVeh = 0 if isInVeh then targetVeh = Natives.InvokeInt(0x9A9112A0FE9A4713, targetPlayer, false) if targetVeh and targetVeh ~= 0 then checkEntity = targetVeh end end local skipDueToSameVehicle = false if myVeh and myVeh ~= 0 then if targetPlayer == excludePed or targetVeh == myVeh then skipDueToSameVehicle = true end end if not skipDueToSameVehicle then local pCoords = InvokeV3(0x3FEF770D40960D5A, checkEntity, false) local myCoords = InvokeV3(0x3FEF770D40960D5A, excludePed, false) if pCoords and myCoords then local dx = pCoords.x - myCoords.x local dy = pCoords.y - myCoords.y local dz = pCoords.z - myCoords.z local dist = math.sqrt(dx*dx + dy*dy + dz*dz) if dist < shortestDist then shortestDist = dist nearestEntity = checkEntity end end end end end end end return nearestEntity end
Script.QueueJob(function() local weaponHash = Utils.Joaat("WEAPON_VEHICLE_ROCKET") local hornWasPressed = false while true do if hornRocketsEnabled then local playerPed = Natives.InvokeInt(0x43A66C31C68491C0, -1) if playerPed and playerPed ~= 0 then local veh = InvokeInt(0x9A9112A0FE9A4713, playerPed, false) if veh and veh ~= 0 then Natives.InvokeVoid(0x3882114BDE571AD4, veh, true) local isHornActive = InvokeBool(0x580417101DDB492F, 0, 86) or InvokeBool(0x9D6BFC12B05C6121, veh) if isHornActive then if not hornWasPressed then hornWasPressed = true local playerCoords = InvokeV3(0x3FEF770D40960D5A, veh, false) local forwardVector = InvokeV3(0x0A794A5A57F8DF91, veh) if playerCoords and forwardVector then local rightX = -forwardVector.y local rightY = forwardVector.x local fOffset = 4.0 local sOffset = 1.8 local targetEntity = nil if not hornRocketsManualEnabled then targetEntity = getNearestPlayerEntity(playerPed) end local endX, endY, endZ if targetEntity and targetEntity ~= 0 then local tCoords = InvokeV3(0x3FEF770D40960D5A, targetEntity, false) local tVelocity = InvokeV3(0x4805D2B1D8CF94A9, targetEntity, false) if tCoords then endX, endY, endZ = tCoords.x, tCoords.y, tCoords.z if tVelocity then local dx = endX - playerCoords.x local dy = endY - playerCoords.y local dz = endZ - playerCoords.z local distance = math.sqrt(dx*dx + dy*dy + dz*dz) local leadFactor = math.min(distance / 100.0, 1.5) endX = endX + (tVelocity.x * leadFactor) endY = endY + (tVelocity.y * leadFactor) endZ = endZ + (tVelocity.z * leadFactor) end end end local currentRange = horn_rockets_range or 125.0 if not endX or not endY or not endZ then local camCoords = InvokeV3(0x14D6F5678D8F1B37, 0) local camRot = InvokeV3(0x837765A25378F0BB, 0) if camCoords and camRot then local radZ = math.rad(camRot.z) local radX = math.rad(camRot.x) local cosX = math.cos(radX) local camDirX = -math.sin(radZ) * cosX local camDirY = math.cos(radZ) * cosX local camDirZ = math.sin(radX) endX = playerCoords.x + (camDirX * currentRange) endY = playerCoords.y + (camDirY * currentRange) endZ = playerCoords.z + (camDirZ * currentRange) + 2.0 local dotAim = (forwardVector.x * camDirX) + (forwardVector.y * camDirY) if dotAim < 0 then fOffset = -4.0 end else endX = playerCoords.x + (forwardVector.x * currentRange) endY = playerCoords.y + (forwardVector.y * currentRange) endZ = playerCoords.z + (forwardVector.z * currentRange) + 2.0 end else local toTargetDot = (forwardVector.x * (endX - playerCoords.x)) + (forwardVector.y * (endY - playerCoords.y)) if toTargetDot < 0 then fOffset = -4.0 end end local startX1 = playerCoords.x + (forwardVector.x * fOffset) + (rightX * sOffset) local startY1 = playerCoords.y + (forwardVector.y * fOffset) + (rightY * sOffset) local startZ1 = playerCoords.z + (forwardVector.z * 0.5) local startX2 = playerCoords.x + (forwardVector.x * fOffset) - (rightX * sOffset) local startY2 = playerCoords.y + (forwardVector.y * fOffset) - (rightY * sOffset) local startZ2 = playerCoords.z + (forwardVector.z * 0.5) InvokeVoid(0x867654CBC7606F2C, startX1, startY1, startZ1, endX, endY, endZ, 400, true, weaponHash, playerPed, true, false, 3000.0) InvokeVoid(0x867654CBC7606F2C, startX2, startY2, startZ2, endX, endY, endZ, 400, true, weaponHash, playerPed, true, false, 3000.0) end end else hornWasPressed = false end end end end Script.Yield(0) end end)
