-- Manual Transmission
manualTransHash = Utils.Joaat("VR_MANUALTRANS") disableMouseHash = Utils.Joaat("VR_DISABLE_MOUSE") vr_getHighGear = function() local a = GV() return a and Memory.ReadByte(a + 0x0886) or 0 end vr_setNextGear = function(v) local a = GV() if a then Memory.WriteByte(a + 0x0880, v) end end vr_keybinds = vr_keybinds or {up = 21, down = 36} mt = { wasInVehicle = false, activationDelay = 0, isDelaying = false, currentGear = 1, wasBrakeHeld = false }
FeatureMgr.AddFeature(manualTransHash, "Manual Trans", eFeatureType.Toggle, "L-Shift/M1 = Upshift\nL-Ctrl/M2 Downshift\n ", function(f) end)
Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then if vr_myVehicle() ~= 0 then vr_setNextGear(0) end mt.currentGear, mt.wasInVehicle, mt.isDelaying, mt.activationDelay = 1, false, false, 0 return false end local isToggled = FeatureMgr.IsFeatureEnabled(manualTransHash) if isToggled then local veh = GTA.GetLocalVehicle() local isDriving = (veh ~= nil and veh:GetDriver() ~= nil) and (veh:GetDriver() == GTA.GetLocalPed()) and (vr_getHighGear() > 1) if isDriving then if not mt.wasInVehicle then if not mt.isDelaying then mt.activationDelay, mt.isDelaying = 0, true end if mt.activationDelay < 10 then mt.activationDelay = mt.activationDelay + 1; vr_setNextGear(0) else mt.currentGear, mt.wasInVehicle, mt.isDelaying, mt.activationDelay = math.max(1, math.min(vr_getCurrentGear(), vr_getHighGear())), true, false, 0 end else VR_DISABLE_CONTROL_ACTION(0, 68, true); VR_DISABLE_CONTROL_ACTION(0, 69, true); VR_DISABLE_CONTROL_ACTION(0, 70, true); VR_DISABLE_CONTROL_ACTION(0, 25, true) vr_setNextGear(mt.currentGear) local isBrakeHeld = VR_IS_CONTROL_PRESSED(0, 72) if mt.currentGear == 0 then if mt.wasBrakeHeld and not isBrakeHeld then mt.currentGear = 1 end end mt.wasBrakeHeld = isBrakeHeld local useMouse = not FeatureMgr.IsFeatureEnabled(disableMouseHash) local shiftDown = (VR_IS_CONTROL_JUST_PRESSED(0, vr_keybinds.down) or (useMouse and VR_IS_CONTROL_JUST_PRESSED(2, 225))) if (VR_IS_CONTROL_JUST_PRESSED(0, vr_keybinds.up) or (useMouse and VR_IS_CONTROL_JUST_PRESSED(2, 223))) and mt.currentGear < vr_getHighGear() then mt.currentGear = mt.currentGear + 1 elseif shiftDown and mt.currentGear > 0 then local currentSpeed = VR_GET_ENTITY_SPEED(veh) if mt.currentGear == 1 then if currentSpeed < 2.0 and isBrakeHeld then mt.currentGear = 0 else GUI.AddToast("Manual Trans", "Must Be Holding Brake To Shift To R", 2000) end else mt.currentGear = mt.currentGear - 1 end end end else mt.wasInVehicle, mt.isDelaying, mt.activationDelay = false, false, 0 end elseif mt.wasInVehicle or mt.activationDelay > 0 or mt.isDelaying then if vr_myVehicle() ~= 0 then vr_setNextGear(0) end mt.currentGear, mt.wasInVehicle, mt.isDelaying, mt.activationDelay = 1, false, false, 0 end return true end)
