-- NAT Spoofing
VR_NAT = {} VR_NAT.SCRIPT_NAME = "NAT Spoofing" VR_NAT.VERSION = "1.0.1" VR_NAT.LOGS_ENABLED = true VR_NAT.LOG_MAX_ENTRIES = 300 VR_NAT.log_entries = {} VR_NAT.TOASTS_ENABLED = true VR_NAT.TOAST_POS = 0 VR_NAT.TOAST_DURATION = 4000
function VR_NAT.ring_push(buffer, text) table.insert(buffer, 1, {ts = Time.GetEpocheMs(), text = tostring(text)}) while #buffer > VR_NAT.LOG_MAX_ENTRIES do table.remove(buffer) end end
function VR_NAT.log(message) if not VR_NAT.LOGS_ENABLED then return end local msg = tostring(message) VR_NAT.ring_push(VR_NAT.log_entries, msg) if Logger and Logger.LogInfo then Logger.LogInfo(VR_NAT.SCRIPT_NAME .. ": " .. msg) else print(VR_NAT.SCRIPT_NAME .. ": " .. msg) end end
function VR_NAT.toast(text, pos, duration) if not VR_NAT.TOASTS_ENABLED then return end GUI.AddToast(VR_NAT.SCRIPT_NAME, tostring(text), duration or VR_NAT.TOAST_DURATION, pos or VR_NAT.TOAST_POS) end VR_NAT.TOGGLE_STATES_FILE = FileMgr.GetMenuRootPath() .. "\\NAT_Spoofing\\ToggleStates.json" VR_NAT.toggle_states = {} VR_NAT.FORCE_OVERRIDE = false
function VR_NAT.load_toggle_states() VR_NAT.toggle_states = {} if not FileMgr.DoesFileExist(VR_NAT.TOGGLE_STATES_FILE) then return 0 end local content = FileMgr.ReadFileContent(VR_NAT.TOGGLE_STATES_FILE) or "" if content == "" then return 0 end local count = 0 for key, raw in content:gmatch('"([%w_]+)"%s*:%s*(.-)[,\n}]') do  local val = raw:match("^%s*(.-)%s*$") if val == "true" then VR_NAT.toggle_states[key] = true elseif val == "false" then VR_NAT.toggle_states[key] = false else local n = tonumber(val) if n then VR_NAT.toggle_states[key] = n end end count = count + 1 end return count end VR_NAT.load_toggle_states()
function VR_NAT.save_toggle_states_file() FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. "\\NAT_Spoofing") local keys = {} for key in pairs(VR_NAT.toggle_states) do keys[#keys + 1] = key end table.sort(keys) local parts = {} for _, key in ipairs(keys) do local raw = VR_NAT.toggle_states[key] local v if type(raw) == "number" then v = tostring(raw) else v = raw and "true" or "false" end parts[#parts + 1] = '    "' .. key .. '": ' .. v end local content if #parts == 0 then content = "{}" else content = "{\n" .. table.concat(parts, ",\n") .. "\n}" end return FileMgr.WriteFileContent(VR_NAT.TOGGLE_STATES_FILE, content, false) end
function VR_NAT.persist_toggle_state(key, value) VR_NAT.toggle_states[key] = value and true or false if not VR_NAT.save_toggle_states_file() then VR_NAT.log("Could not write ToggleStates.json") end end
function VR_NAT.register_toggle(key, default, apply) local value if VR_NAT.FORCE_OVERRIDE then value = default and true or false elseif VR_NAT.toggle_states[key] ~= nil then value = VR_NAT.toggle_states[key] else value = default and true or false end VR_NAT.toggle_states[key] = value apply(value) return value end
function VR_NAT.is_attempting_rid_join() return Natives.InvokeBool(0xD9D2CFFF49FAB35F) end VR_NAT.FEATURE_NAT_COMBO = Utils.Joaat("VR_NAT_SPOOF_TYPE") VR_NAT.FEATURE_NAT_TOGGLE = Utils.Joaat("VR_NAT_SPOOF") VR_NAT.NAT_FILE = FileMgr.GetMenuRootPath() .. "\\NAT_Spoofing\\NAT.json" VR_NAT.NAT_SPOOF_ENABLED = false VR_NAT.NAT_TYPE_INDEX = 1 VR_NAT.nat_address = 0 VR_NAT.nat_original = nil VR_NAT.nat_current_index = nil VR_NAT.nat_current_spoofed = false VR_NAT.nat_was_in_grace = false VR_NAT_TYPE_NAMES = {"Open", "Moderate", "Strict"} if GTA.GetEdition() == "EE" then VR_NAT.NAT_PATTERN = "04 49 EC 84 4B 61 ? ? ? ? 41 C6 31" GUI.AddToast("Nat Spoofing", "Patching Enhanced NAT Pattern..", 2000) else VR_NAT.NAT_PATTERN = "48 83 EC 28 8B 05 ? ? ? ? 85 C0 75 ? E8 ? ? ? ? 8B 05 ? ? ? ? 48 83 C4 28" GUI.AddToast("Nat Spoofing", "Patching Legacy NAT Pattern..", 2000) end
function VR_NAT.resolve_address() local base = Memory.Scan(VR_NAT.NAT_PATTERN) local addr = (base and base ~= 0) and Memory.Rip(base + 0x6) or 0 if addr and addr ~= 0 then VR_NAT.nat_address = addr local val = Memory.ReadInt(addr) if type(val) == "number" then VR_NAT.nat_original = val end return true end VR_NAT.nat_address = 0  end
function VR_NAT.write(index) if VR_NAT.nat_address == 0 then return false end index = tonumber(index) or VR_NAT.NAT_TYPE_INDEX if index < 1 then index = 1 elseif index > 3 then index = 3 end Memory.WriteInt(VR_NAT.nat_address, index) return true end
function VR_NAT.restore() if VR_NAT.nat_address == 0 or VR_NAT.nat_original == nil then return false end Memory.WriteInt( VR_NAT.nat_address, VR_NAT.nat_original) return true end
function VR_NAT.apply() if VR_NAT.NAT_SPOOF_ENABLED then VR_NAT.write(VR_NAT.NAT_TYPE_INDEX) else VR_NAT.restore() end end
function VR_NAT.capture_baseline() local index if VR_NAT.NAT_SPOOF_ENABLED then index = VR_NAT.NAT_TYPE_INDEX else local val = (VR_NAT.nat_address ~= 0) and Memory.ReadInt(VR_NAT.nat_address) or nil if type(val) == "number" and val >= 1 and val <= 3 then index = val end end VR_NAT.nat_current_index = index VR_NAT.nat_current_spoofed = VR_NAT.NAT_SPOOF_ENABLED end
function VR_NAT.needs_session_change() if VR_NAT.nat_current_index == nil then return false end if VR_NAT.NAT_SPOOF_ENABLED then return VR_NAT.NAT_TYPE_INDEX ~= VR_NAT.nat_current_index end return VR_NAT.nat_current_spoofed == true end
function VR_NAT.save_nat_file() FileMgr.CreateDir(FileMgr.GetMenuRootPath() .. "\\NAT_Spoofing") local content = "{\n" .. '    "type_index": ' .. tostring(VR_NAT.NAT_TYPE_INDEX) .. "\n}" return FileMgr.WriteFileContent(VR_NAT.NAT_FILE, content, false) end
function VR_NAT.load_nat_file() if not FileMgr.DoesFileExist(VR_NAT.NAT_FILE) then return false end local content = FileMgr.ReadFileContent(VR_NAT.NAT_FILE) or "" if content == "" then return false end local idx = content:match('"type_index"%s*:%s*(%d+)') if idx then idx = tonumber(idx) or 1 if idx < 1 then idx = 1 elseif idx > 3 then idx = 3 end VR_NAT.NAT_TYPE_INDEX = idx end return true end VR_NAT.resolve_address() VR_NAT.load_nat_file() VR_NAT.capture_baseline()
