Script.QueueJob(function() local slickWeaponHash = Utils.Joaat("VEHICLE_WEAPON_MINE_SLICK") local xWasPressed = false while true do if oilSlickEnabled then local playerPed = InvokeInt(0x43A66C31C68491C0, -1) if playerPed and playerPed ~= 0 and InvokeBool(0x7239B21A38F536BA, playerPed) then if not InvokeBool(0x36E353271F0E90EE, slickWeaponHash) then InvokeVoid(0x5443438F033E29C3, slickWeaponHash, 31, 0) end local veh = InvokeInt(0x9A9112A0FE9A4713, playerPed, false) if veh and veh ~= 0 and InvokeBool(0x7239B21A38F536BA, veh) then local isXPressed = InvokeBool(0x580417101DDB492F, 0, 73) if isXPressed then if not xWasPressed then xWasPressed = true if InvokeBool(0x36E353271F0E90EE, slickWeaponHash) then local vehCoords = InvokeV3(0x3FEF770D40960D5A, veh, false) local forwardVector = InvokeV3(0x0A794A5A57F8DF91, veh) if vehCoords and forwardVector then local backX = -forwardVector.x local backY = -forwardVector.y local rightX = -forwardVector.y local rightY = forwardVector.x local rearDistance = 3.5 local sideWidth = 1.2 local spawnHeight = 0.2 local startX1 = vehCoords.x + (backX * rearDistance) + (rightX * sideWidth) local startY1 = vehCoords.y + (backY * rearDistance) + (rightY * sideWidth) local startZ1 = vehCoords.z + spawnHeight local startX2 = vehCoords.x + (backX * rearDistance) - (rightX * sideWidth) local startY2 = vehCoords.y + (backY * rearDistance) - (rightY * sideWidth) local startZ2 = vehCoords.z + spawnHeight local horizontalDistance = 8.0 local endX1 = vehCoords.x + (backX * horizontalDistance) + (rightX * (sideWidth * 2.5)) local endY1 = vehCoords.y + (backY * horizontalDistance) + (rightY * (sideWidth * 2.5)) local endX2 = vehCoords.x + (backX * horizontalDistance) - (rightX * (sideWidth * 2.5)) local endY2 = vehCoords.y + (backY * horizontalDistance) - (rightY * (sideWidth * 2.5)) local endZ = vehCoords.z + spawnHeight InvokeVoid(0x867654CBC7606F2C, startX1, startY1, startZ1, endX1, endY1, endZ, 100, true, slickWeaponHash, playerPed, true, false, 1000.0) InvokeVoid(0x867654CBC7606F2C, startX2, startY2, startZ2, endX2, endY2, endZ, 100, true, slickWeaponHash, playerPed, true, false, 1000.0) end end end else xWasPressed = false end end end end Script.Yield(0) end end)
