function SaveVehicleState(veh) if veh==0 then return end if PoliceState.vehicle==veh and PoliceState.saved then return end PoliceState={ vehicle=veh, saved=true, xenon={enabled=false,color=255}, neon={color={255,255,255},enabled={}}, headlights=false } PoliceState.headlights=InvokeBool(0xC45C27EF50F36ADC,veh) InvokeVoid(0x1F2AA07F00B3217A,veh,0) PoliceState.xenon.enabled=InvokeBool(0x84B233A8C8FC8AE7,veh,22) if PoliceState.xenon.enabled then PoliceState.xenon.color=InvokeInt(0x3DFF319A831E0CDB,veh) end local rgb=xenonToNeonRGB[PoliceState.xenon.color] or {255,255,255} PoliceState.neon.color={rgb[1],rgb[2],rgb[3]} for i=0,3 do PoliceState.neon.enabled[i]=InvokeBool(0x8C4B92553E4766A5,veh,i) end end
