d(0x3882114BDE571AD4, currentPed, false) Natives.InvokeVoid(0x6B76DC1F3AE6E6A3, currentPed, 0, 0) local px, py, pz = Natives.InvokeV3(0x3FEF770D40960D5A, currentPed, true) if type(px) == "table" then Natives.InvokeVoid(0xE3AD2BDBAEE269AC, px.x, px.y, px.z, 0, 9999.0, false, true, 0.0) elseif px and py and pz then Natives.InvokeVoid(0xE3AD2BDBAEE269AC, px, py, pz, 0, 9999.0, false, true, 0.0) end Script.Yield(100) end end) end else vr_sittingPlayers[sid] = nil end else vr_sittingPlayers[sid] = nil end end end end end Script.Yield(500) end end)
