-- Setting Manager
vroomSpeedometer = nil vroomSpeedoEnabled = false State = { settingsFolder = vroomDir, cachedFeatures = {}, featureMap = {}, cacheTime = 0, timeoutSeconds = 5 } State.settingsFile = State.settingsFolder .. "settings.json"
function ClearCache() State.cachedFeatures = {} State.featureMap = {} State.cacheTime = 0 end
function ParseBool(val) if val == true or val == "true" or val == "1" or val == 1 then return true end return false end
function GetFeatureValue(feature) local fType = feature:GetType() if fType == eFeatureType.SliderFloatToggle then return string.format('{"t":%s,"v":%.4f}', tostring(feature:IsToggled() == true or feature:IsToggled() == 1), feature:GetFloatValue()) elseif fType == eFeatureType.SliderIntToggle then return string.format('{"t":%s,"v":%d}', tostring(feature:IsToggled() == true or feature:IsToggled() == 1), feature:GetIntValue()) elseif fType == eFeatureType.SliderFloat then return feature:GetFloatValue() elseif fType == eFeatureType.SliderInt then return feature:GetIntValue() elseif fType == eFeatureType.Choice or fType == eFeatureType.Scroll then return feature:GetIntValue() elseif fType == eFeatureType.Toggle or feature:IsToggleFeature() then return tostring(feature:IsToggled() == true or feature:IsToggled() == 1) end return nil end
function RefreshFeatureList() ClearCache() local features = FeatureMgr.GetAllFeatures() if features then local count = (type(features.size) == "function") and features:size() or #features for i = 0, count - 1 do local feature = features[i] if feature and type(feature.GetName) == "function" then local name = feature:GetName() if name and name ~= "Speedometer" then if not State.featureMap[name] then table.insert(State.cachedFeatures, feature) State.featureMap[name] = feature end end end end end State.cacheTime = os.time() end
function ApplyToggleState(feature, targetState) if not feature then return end local currentState = (feature:IsToggled() == true or feature:IsToggled() == 1) if currentState ~= targetState then if type(feature.Toggle) == "function" then feature:Toggle() elseif type(feature.SetToggle) == "function" then feature:SetToggle(targetState) elseif type(feature.SetState) == "function" then feature:SetState(targetState) end end if targetState then if type(feature.SetVisible) == "function" then feature:SetVisible(true) end if type(feature.OnSettingsLoad) == "function" then feature:OnSettingsLoad() end end end
function LoadSettings() local earlyFile = io.open(State.settingsFile, "r") if earlyFile then local content = earlyFile:read("*all") earlyFile:close() content = content:gsub("\r", "") local speedoVal = content:match('"VROOM_Speedometer"%s*:%s*([^,}]+)') if speedoVal then vroomSpeedoEnabled = ParseBool(speedoVal:match("^%s*(.-)%s*$")) end local attachVal = content:match('"vr_attachProt"%s*:%s*([^,}]+)') if attachVal then local attachFeature = FeatureMgr.GetFeature(Utils.Joaat("vr_attachProt")) if attachFeature then ApplyToggleState(attachFeature, ParseBool(attachVal:match("^%s*(.-)%s*$"))) end end end
RefreshFeatureList() local file = io.open(State.settingsFile, "r") if file then local content = file:read("*all") file:close() content = content:gsub("\r", "") for name, rawVal in string.gmatch(content, '"([^"]+)":([^,{}]+)') do local val = rawVal:match("^%s*(.-)%s*$") if name == "VROOM_Speedometer" and vroomSpeedometer then ApplyToggleState(vroomSpeedometer, vroomSpeedoEnabled) elseif name ~= "vr_attachProt" then local feature = State.featureMap[name] if feature then local fType = feature:GetType() if fType == eFeatureType.Toggle or feature:IsToggleFeature() then ApplyToggleState(feature, ParseBool(val)) elseif fType == eFeatureType.Choice or fType == eFeatureType.Scroll then local num = tonumber(val) if num then feature:SetIntValue(math.floor(num)) feature:TriggerCallback() end end end end end for name, objStr in string.gmatch(content, '"([^"]+)":({[^}]+})') do 
local feature = State.featureMap[name] if feature then local fType = feature:GetType() local t = objStr:match('"t":([^,}]+)') local v = objStr:match('"v":([^,}]+)') if t and v then t = t:match("^%s*(.-)%s*$") v = v:match("^%s*(.-)%s*$") local targetState = ParseBool(t) if fType == eFeatureType.SliderFloatToggle or fType == eFeatureType.SliderIntToggle then ApplyToggleState(feature, targetState) if fType == eFeatureType.SliderFloatToggle then feature:SetFloatValue(tonumber(v) or 0.0) else feature:SetIntValue(math.floor(tonumber(v) or 0)) end feature:TriggerCallback() end end end end for name, rawVal in string.gmatch(content, '"([^"]+)":([^,{}]+)') do local feature = State.featureMap[name] if feature then local val = rawVal:match("^%s*(.-)%s*$") local fType = feature:GetType() if fType == eFeatureType.SliderFloat then local num = tonumber(val)
if num then feature:SetFloatValue(num) feature:TriggerCallback() end elseif fType == eFeatureType.SliderInt then local num = tonumber(val) if num then feature:SetIntValue(math.floor(num)) feature:TriggerCallback() end end end end GUI.AddToast("Settings Manager", "Settings Loaded", 2000) else GUI.AddToast("Settings Manager", "No Saved Settings Found.", 2000) end end
local function SaveSettings() RefreshFeatureList() if vroomSpeedometer then vroomSpeedoEnabled = (vroomSpeedometer:IsToggled() == true or vroomSpeedometer:IsToggled() == 1) end local file = io.open(State.settingsFile, "w") if file then local entries = {} for _, feature in ipairs(State.cachedFeatures) do local val = GetFeatureValue(feature) if val ~= nil then table.insert(entries, string.format('"%s":%s', feature:GetName(), tostring(val))) end end	 local attachFeature = FeatureMgr.GetFeature(Utils.Joaat("vr_attachProt")) if attachFeature then local attachVal = (attachFeature:IsToggled() == true or attachFeature:IsToggled() == 1) table.insert(entries, string.format('"vr_attachProt":%s', tostring(attachVal))) end table.insert(entries, string.format('"VROOM_Speedometer":%s', tostring(vroomSpeedoEnabled))) if #entries > 0 then file:write("{" .. table.concat(entries, ",") .. "}") file:close() GUI.AddToast("Settings Manager", "Settings Saved", 2000) else file:close() GUI.AddToast("Settings Manager", "No Valid Settings Found", 2000) end ClearCache() else GUI.AddToast("Settings Manager", "Failed To Open File", 2000) end end
