Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then if is_shift_drift_applied then local veh = vr_myVehicle() if veh ~= 0 then VR_SET_DRIFT_TYRES(veh, false) end is_shift_drift_applied = false end return false end if FeatureMgr.IsFeatureEnabled(shiftDriftHash) then local veh = vr_myVehicle() if veh ~= 0 then local isShiftPressed = VR_IS_CONTROL_PRESSED(0, 21) if isShiftPressed then if ApplyNaturalDrift then ApplyNaturalDrift(veh) end is_shift_drift_applied = true else if is_shift_drift_applied then VR_SET_DRIFT_TYRES(veh, false) is_shift_drift_applied = false end end end else if is_shift_drift_applied then local veh = vr_myVehicle() if veh ~= 0 then VR_SET_DRIFT_TYRES(veh, false) end is_shift_drift_applied = false end end Script.Yield(10) return true end)
