-- Speedo Plate
speedoPlateRegistered = false
FeatureMgr.AddFeature(Utils.Joaat("VR_SPEEDO_PLATE"), "Speedometer on Plate", eFeatureType.Toggle, "Displays Speed On The License Plate\n ", function(f) if not speedoPlateRegistered then speedoPlateRegistered = true local function GetCenteredPlateText(text) local len = #text if len == 1 then return "    " .. text .. "    " end if len == 2 then return "   " .. text .. "   " end if len == 3 then return "   " .. text .. "  " end if len == 4 then return "  " .. text .. "  " end return text end local last_speed = -1 Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then return false end if f and f:IsToggled() then local veh = vr_myVehicle() if veh ~= 0 then local is_metric = Natives.InvokeBool(0xD3D15555431AB793) local multiplier = is_metric and 3.6 or 2.23694 local speed_val = math.floor(Natives.InvokeFloat(0xD5037BA82E12416F, veh) * multiplier) if speed_val ~= last_speed then last_speed = speed_val local s = tostring(speed_val) local display_text = GetCenteredPlateText(s) Natives.InvokeVoid(0x95A88F0B409CDA47, veh, display_text) end end else last_speed = -1 end return true end) end end)
