FeatureMgr.AddFeature(Utils.Joaat("VR_SHOWYAPPERS"), "Show Yappers", eFeatureType.Toggle, "Shows Who Is Talking On Screen\nCan Be Moved\n ", function(f) VR_YAPPERS = {} end)
Script.RegisterLooped(function() local feat = FeatureMgr.GetFeature(Utils.Joaat("VR_SHOWYAPPERS")) if feat and feat:IsToggled() then local players = Players.Get() if players then for _, pid in pairs(players) do local n = Players.GetName(pid) if n then local talking = VR_NETWORK_IS_PLAYER_TALKING(pid) local found_in_table = false for _, v in pairs(VR_YAPPERS) do if v == n then found_in_table = true; break end end if talking and not found_in_table then table.insert(VR_YAPPERS, n) elseif not talking and found_in_table then for i, v in pairs(VR_YAPPERS) do if v == n then table.remove(VR_YAPPERS, i); break end end end end end end else VR_YAPPERS = {} end return true end)
if yappin and yappin:IsToggled() and VR_YAPPERS then ImGui.PushStyleColor(ImGuiCol.WindowBg, 0.1, 0.1, 0.1, 0.8) ImGui.Begin("##VRTalkingPlayers", true, ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoDecoration) ImGui.Text("Talking Players:") for _, n in ipairs(VR_YAPPERS) do ImGui.Text(n) end ImGui.End() ImGui.PopStyleColor() end
-- Slam
vr_slam_speed_override = vr_slam_speed_override or false vr_slam_threshold = vr_slam_threshold or 5.0
FeatureMgr.AddFeature(Utils.Joaat("VR_SLAM"), "Slam Vehicle", eFeatureType.SliderFloatToggle, "Lowers Any Vehicle (Pump It For A Greater Effect)", function(feature)
Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then return false end if feature and feature:IsToggled() then local ped = GTA.GetLocalPed() if ped then local v = ped.LastVehicle if v then local vehicleHandle = GTA.PointerToHandle(v) if vehicleHandle ~= 0 then local isAirborne = B(0x886E37EC497200B6, vehicleHandle) if not isAirborne then local threshold = (vr_slam_threshold or 5.0) * 0.44704 if (vr_slam_speed_override or VR_GET_ENTITY_SPEED(vehicleHandle) < threshold) then VR_APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS(vehicleHandle, 0, 0, 0, -(feature:GetFloatValue() / 10.0), true, true, true, true) end end end end end end return true end) end):SetLimitValues(0.0, 1.0)
FeatureMgr.AddFeature(Utils.Joaat("VR_SLAM_OVERRIDE"), "Slam Speed Override", eFeatureType.Toggle, "Allows Slamming While Driving Fast", function(f)
Script.RegisterLooped(function() vr_slam_speed_override = f:IsToggled() return true end) end)
FeatureMgr.AddFeature(Utils.Joaat("VR_SLAM_THRESHOLD"), "Slam Speed Threshold", eFeatureType.SliderFloat, "Speed To Raise The Vehicle Up Again\n ", function(f) vr_slam_threshold = f:GetFloatValue() end):SetLimitValues(0.0, 100.0):SetFloatValue(5.0)
-- Soft Steer
isDampeningEnabled = false steeringDampenFactor = 0.060 isSteering = false steerStartTime = 0 DAMPEN_DURATION = 0.3
FeatureMgr.AddFeature(Utils.Joaat("VR_STEER_TOGGLE"), "Smooth Steering", eFeatureType.Toggle, "Smoothes Out The Initial Key\nPress When Steering With A & D\n ", function(f) isDampeningEnabled = f:IsToggled() end)
Script.RegisterLooped(function() local veh = vr_myVehicle() if isDampeningEnabled and veh ~= 0 then local isA = VR_IS_CONTROL_PRESSED(0, 34) local isD = VR_IS_CONTROL_PRESSED(0, 35) if (isA or isD) then if not isSteering then isSteering = true steerStartTime = os.clock() end local elapsed = os.clock() - steerStartTime if elapsed < DAMPEN_DURATION then local progress = elapsed / DAMPEN_DURATION local direction = isD and 1.0 or -1.0 local dampenValue = (1.0 - progress) * steeringDampenFactor Natives.InvokeVoid(0x42A8EC77D5150CBE, veh, dampenValue * direction) else Natives.InvokeVoid(0x42A8EC77D5150CBE, veh, 0.0) end else isSteering = false Natives.InvokeVoid(0x42A8EC77D5150CBE, veh, 0.0) end end Script.Yield(0) return true end)
-- Spike Strips
spawnedSpikeStrips = {}
FeatureMgr.AddFeature(Utils.Joaat("VR_DROP_SPIKE_STRIP"), "Drop Spike Strip", eFeatureType.Button, "Spawns A Spike Strip Behind Your Vehicle\n ", function() local vehicleHandle = vr_myVehicle() if vehicleHandle ~= 0 then local vCoords = VR_GET_ENTITY_COORDS(vehicleHandle, true)  local vHeading = Natives.InvokeFloat(0xE83D4F9BA2A38914, vehicleHandle)  local rad = math.rad(vHeading) local distBack = 4.0  local spawnX = vCoords.x + (math.sin(rad) * distBack) local spawnY = vCoords.y - (math.cos(rad) * distBack) local zPtr = Memory.Alloc(8) local foundGround, groundZ = false, vCoords.z if zPtr then foundGround = Natives.InvokeBool(0xC906A7DAB05C8D2B, spawnX, spawnY, vCoords.z + 5.0, zPtr, true) if foundGround then groundZ = Memory.ReadFloat(zPtr) end Memory.Free(zPtr) end local modelHash = Utils.Joaat("p_ld_stinger_s") Natives.InvokeVoid(0x963D27A58DF860AC, modelHash) local timeout = 0 while not Natives.InvokeBool(0x98A4EB5D89A0C952, modelHash) and timeout < 50 do Script.Yield() timeout = timeout + 1 end if Natives.InvokeBool(0x98A4EB5D89A0C952, modelHash) then local objHandle = Natives.InvokeInt(0x509D5878EB39E842, modelHash, spawnX, spawnY, groundZ, true, true, false) if objHandle and objHandle ~= 0 then local stripHeading = (vHeading + 90.0) % 360.0 Natives.InvokeVoid(0x8E2530AA8ADA980E, objHandle, stripHeading) Natives.InvokeVoid(0x58A850EAEE20FAA3, objHandle)  table.insert(spawnedSpikeStrips, { handle = objHandle, popped = {} }) end end end end)
Script.RegisterLooped(function() if #spawnedSpikeStrips > 0 then local myVeh = vr_myVehicle() local pCoords = nil if myVeh ~= 0 then pCoords = VR_GET_ENTITY_COORDS(myVeh, true) end for i = #spawnedSpikeStrips, 1, -1 do local stripData = spawnedSpikeStrips[i] local strip = stripData and stripData.handle if strip and strip ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, strip) then local stripCoords = VR_GET_ENTITY_COORDS(strip, true) if not pCoords or (math.abs(pCoords.x - stripCoords.x) < 150.0 and math.abs(pCoords.y - stripCoords.y) < 150.0) then local vehicles = {} local poolResult = Natives.GetGamePool and Natives.GetGamePool("CVehicle") if type(poolResult) == "table" and #poolResult > 0 then vehicles = poolResult else local allVehs = Natives.GetAllVehicles and Natives.GetAllVehicles() if type(allVehs) == "table" and #allVehs > 0 then vehicles = allVehs else local foundVeh = Natives.InvokeInt(0xF73EB622C4F1689B, stripCoords.x, stripCoords.y, stripCoords.z, 20.0, 0, 70) if foundVeh and foundVeh ~= 0 then table.insert(vehicles, foundVeh) end end end if myVeh ~= 0 then local foundPlayer = false for _, v in ipairs(vehicles) do if v == myVeh then foundPlayer = true break end end if not foundPlayer then table.insert(vehicles, myVeh) end end for _, veh in ipairs(vehicles) do if veh and veh ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, veh) then local vCoords = VR_GET_ENTITY_COORDS(veh, true) local zDiff = math.abs(vCoords.z - stripCoords.z) if zDiff < 1.8 and math.abs(vCoords.x - stripCoords.x) < 8.0 and math.abs(vCoords.y - stripCoords.y) < 8.0 then local vHeading = Natives.InvokeFloat(0xE83D4F9BA2A38914, veh) local sHeading = Natives.InvokeFloat(0xE83D4F9BA2A38914, strip) local sRad = math.rad(sHeading) local cosS, sinS = math.cos(sRad), math.sin(sRad) local vRad = math.rad(vHeading) local fwdX, fwdY = -math.sin(vRad), math.cos(vRad) local rightX, rightY = math.cos(vRad), math.sin(vRad) local halfWidth = 0.95 local halfLength = 1.45 local wheels = { {index = 0, dx = (fwdX * halfLength) - (rightX * halfWidth), dy = (fwdY * halfLength) - (rightY * halfWidth)}, {index = 1, dx = (fwdX * halfLength) + (rightX * halfWidth), dy = (fwdY * halfLength) + (rightY * halfWidth)}, {index = 4, dx = (-fwdX * halfLength) - (rightX * halfWidth), dy = (-fwdY * halfLength) - (rightY * halfWidth)}, {index = 5, dx = (-fwdX * halfLength) + (rightX * halfWidth), dy = (-fwdY * halfLength) + (rightY * halfWidth)} } for _, wheel in ipairs(wheels) do local wheelKey = tostring(veh) .. "_" .. tostring(wheel.index) local isBurst = Natives.InvokeBool(0xBA291848A0815CA9, veh, wheel.index, false) if not isBurst and stripData.popped[wheelKey] then stripData.popped[wheelKey] = nil end if math.abs(vCoords.x - stripCoords.x) > 10.0 or math.abs(vCoords.y - stripCoords.y) > 10.0 then stripData.popped[wheelKey] = nil end if not stripData.popped[wheelKey] then local wheelX = vCoords.x + wheel.dx local wheelY = vCoords.y + wheel.dy local diffX = wheelX - stripCoords.x local diffY = wheelY - stripCoords.y local localX = math.abs((diffX * cosS) + (diffY * sinS)) local localY = math.abs((-diffX * sinS) + (diffY * cosS)) if localY < 1.9 and localX < 0.5 then stripData.popped[wheelKey] = true if Natives.InvokeBool and not Natives.InvokeBool(0x01BF60A500E28887, veh) then Natives.InvokeVoid(0xB69317BF5E782347, veh) end Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, true)   Natives.InvokeVoid(0xEC6A202EE4960385, veh, wheel.index, true, 1000.0) end end end end end end end else table.remove(spawnedSpikeStrips, i) end end end Script.Yield(0) return true end)
FeatureMgr.AddFeature(Utils.Joaat("VR_DELETE_SPIKE_STRIPS"), "Delete Spike Strips", eFeatureType.Button, "Removes All Spawned Spike Strips\n ", function() for i = #spawnedSpikeStrips, 1, -1 do local stripData = spawnedSpikeStrips[i] local handle = stripData and stripData.handle if handle and handle ~= 0 then if Natives.InvokeBool(0x7239B21A38F536BA, handle) then local ptr = Memory.Alloc(8)  if ptr then Memory.WriteInt(ptr, handle) Natives.InvokeVoid(0x539E0AE3E6634B9F, ptr) Memory.Free(ptr) end end end end spawnedSpikeStrips = {} end)
