Script.RegisterLooped(function() if is_squattie_active then local veh = vr_myVehicle() local feature = FeatureMgr.GetFeature(Utils.Joaat("VR_SQUATTIE")) local base_strength = (feature and feature:GetFloatValue() or 0.035) if veh ~= 0 then local speed = VR_GET_ENTITY_SPEED(veh) if speed < 50.0 then local isInAir = B(0x886E37EC497200B6, veh) if not isInAir then local rear_force = base_strength * 2.5 VR_InvokeVoid(0xC5F68BE9613E2D18, veh, 1, 0.0, 0.0, -rear_force, 0.0, -2.5, 0.0, true, true, true, true, false, true) end end end end Script.Yield(0) return true end)
-- Stay High
currently_active_effect = nil cleanup_high_effect = function() if VR_ANIMPOSTFX_IS_RUNNING(selected_high_effect) then VR_ANIMPOSTFX_STOP(selected_high_effect) end end selected_high_effect = "BikerFilter"
high_effects = { "BeastLaunch", "BikerFilter", "ChopVision", "CrossLine", "DeadlineNeon", "DeathFailFranklinIn", "DeathFailMichaelIn", "DeathFailMPDark", "DeathFailMPIn", "DeathFailNeutralIn", "DMT_flight", "DMT_flight_intro", "Dont_tazeme_bro", "DrugsDrivingOut", "DrugsMichaelAliensFight", "DrugsMichaelAliensFightIn", "DrugsMichaelAliensFightOut", "DrugsTrevorClownsFight", "DrugsTrevorClownsFightIn", "DrugsTrevorClownsFightOut", "FocusIn", "HeistCelebEnd", "HeistCelebPass", "HeistCelebPassBW", "InchOrange", "InchPickup", "InchPurple", "LostTimeDay", "LostTimeNight", "MenuMGHeistIntro", "MenuMGHeistTint", "MP_Bull_tost", "MP_Celeb_Lose", "MP_Celeb_Preload", "MP_Celeb_Win", "MP_corona_switch", "MP_intro_logo", "MP_job_load", "MP_Killstreak", "MP_OrbitalCannon", "MP_Powerplay", "pennedIn", "PeyoteIn", "PPFilter", "PPGreen", "PPOrange", "PPPink", "PPPurple", "RaceTurbo", "Rampage", "TinyRacerGreen", "TinyRacerIntroCam", "TinyRacerPink" }
FeatureMgr.AddFeature(Utils.Joaat("VR_STAY_HIGH"), "Stay High", eFeatureType.Toggle, "Keeps You Permanently High\n(Until You Turn It Off)\n ", function(f) if not f:IsToggled() then if type(cleanup_high_effect) == "function" then cleanup_high_effect() end end end)
Script.RegisterLooped(function() local f = FeatureMgr.GetFeature(Utils.Joaat("VR_STAY_HIGH")) if not f then Script.Yield(1000) return true end local target_effect = (type(selected_high_effect) ~= "nil") and selected_high_effect or "DrugsTrevorClownFight" local isEnabled = f:IsToggled() if isEnabled then if currently_active_effect ~= target_effect then if currently_active_effect then VR_ANIMPOSTFX_STOP(currently_active_effect) end VR_ANIMPOSTFX_PLAY(target_effect) currently_active_effect = target_effect elseif not VR_ANIMPOSTFX_IS_RUNNING(currently_active_effect) then VR_ANIMPOSTFX_PLAY(target_effect) end else if currently_active_effect then VR_ANIMPOSTFX_STOP(currently_active_effect) currently_active_effect = nil end end Script.Yield(500) return true end)
-- Steal Engine
stealEngineHash = Utils.Joaat("VR_STEAL_ENGINE") is_steal_engine_active = false heldEngineProp = 0 isHoldingEngine = false stolenEngineVehicle = 0
FeatureMgr.AddFeature(stealEngineHash, "Steal Engine", eFeatureType.Toggle, "Removes The Engine From Nearby Vehicle\n ", function(f) iW_StealEngine(FeatureMgr.IsFeatureEnabled(stealEngineHash)) end)
function CleanupEngine() if heldEngineProp ~= 0 then if Natives.InvokeBool(0x7239B21A38F536BA, heldEngineProp) then Natives.InvokeVoid(0xAD738C3085FE7E11, heldEngineProp, true, true) local ptr = Memory.Alloc(8) if ptr then Memory.WriteInt(ptr, heldEngineProp) Natives.InvokeVoid(0x539E0AE3E6634B9F, ptr) Memory.Free(ptr) end end heldEngineProp = 0 end isHoldingEngine = false end
function iW_StealEngine(enable) is_steal_engine_active = enable if not enable then CleanupEngine() stolenEngineVehicle = 0 return end
Script.RegisterLooped(function() if not is_steal_engine_active then return false end local localPed = Natives.InvokeInt(0x43A66C31C68491C0, GTA.GetLocalPlayerId()) if not localPed or localPed == 0 or Natives.InvokeBool(0x997ABD671D25CA0B, localPed, false) then return true end if stolenEngineVehicle ~= 0 then if Natives.InvokeBool(0x7239B21A38F536BA, stolenEngineVehicle) then if not Natives.InvokeBool(0x01BF60A500E28887, stolenEngineVehicle) then Natives.InvokeVoid(0xB69317BF5E782347, stolenEngineVehicle) end Natives.InvokeVoid(0x3882114BDE571AD4, stolenEngineVehicle, false) Natives.InvokeVoid(0x1760FFA8AB074D66, stolenEngineVehicle, true) Natives.InvokeVoid(0x45F6D8EEF34ABEF1, stolenEngineVehicle, -4000.0) Natives.InvokeVoid(0x8ABA6AF54B942B95, stolenEngineVehicle, true) Natives.InvokeVoid(0x2497C4717C8B881E, stolenEngineVehicle, false, true, true) else stolenEngineVehicle = 0 end end local lx, ly, lz = Natives.InvokeV3(0x3FEF770D40960D5A, localPed, true) local nearby = Natives.InvokeInt(0xF73EB622C4F1689B, lx, ly, lz, 4.0, 0, 1|2|4|8|16|32|64|2048|32768|65536|131072|262144|524288) local canGrab = false if nearby ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, nearby) then local vx, vy, vz = Natives.InvokeV3(0x3FEF770D40960D5A, nearby, true) local dist = Natives.InvokeFloat(0x31698AA80E0223F8, lx, ly, lz, vx, vy, vz, true) if dist < 5.0 then canGrab = true end end if Natives.InvokeBool(0x580417101DDB492F, 0, 38) then if isHoldingEngine then CleanupEngine() Natives.InvokeVoid(0xE1EF3C1216AFF2CD, localPed) Script.Yield(1000) elseif canGrab then local hasControl = false if Natives.InvokeBool(0x01BF60A500E28887, nearby) then hasControl = true else local reqDl = Time.GetEpocheMs() + 1500 while Time.GetEpocheMs() < reqDl and not hasControl do Natives.InvokeVoid(0xB69317BF5E782347, nearby) if Natives.InvokeBool(0x01BF60A500E28887, nearby) then hasControl = true break end Script.Yield(10) end end if hasControl or not Natives.InvokeBool(0x01BF60A500E28887, nearby) then local workDict = "anim@amb@clubhouse@tutorial@bkr_tut_ig3@" local workAnim = "machinic_loop_mechandplayer" Natives.InvokeVoid(0xD3BD40951412FEF6, workDict) local loadTimeout = Time.GetEpocheMs() + 1500 while not Natives.InvokeBool(0xD031A9162D01088C, workDict) and Time.GetEpocheMs() < loadTimeout do Script.Yield(10) end Natives.InvokeVoid(0xEA47FE3719165B94, localPed, workDict, workAnim, 8.0, -8.0, -1, 49, 0, false, false, false) local animTimer = Time.GetEpocheMs() + 2000 while Time.GetEpocheMs() < animTimer do Script.Yield(10) end local propHash = Utils.Joaat("prop_car_engine_01") local carryDict = "anim@heists@box_carry@" Natives.InvokeVoid(0xD3BD40951412FEF6, carryDict) Natives.InvokeVoid(0x963D27A58DF860AC, propHash) local propTimeout = Time.GetEpocheMs() + 1500 while Time.GetEpocheMs() < propTimeout and (not Natives.InvokeBool(0xD031A9162D01088C, carryDict) or not Natives.InvokeBool(0x98A4EB5D89A0C952, propHash)) do Script.Yield(10) end if Natives.InvokeBool(0x98A4EB5D89A0C952, propHash) then heldEngineProp = Natives.InvokeInt(0x509D5878EB39E842, propHash, lx, ly, lz + 0.5, true, true, false) if heldEngineProp ~= 0 then Natives.InvokeVoid(0x1A9205C1B9EE827F, heldEngineProp, false, false) Natives.InvokeVoid(0xAD738C3085FE7E11, heldEngineProp, true, true) local boneIndex = Natives.InvokeInt(0xFB71170B7E76ACBA, localPed, "IK_R_Hand") Natives.InvokeVoid(0x6B9BBD38AB0796DF, heldEngineProp, localPed, boneIndex, 0.0, 0.05, -0.2, -90.0, 0.0, 0.0, true, true, false, true, 2, true) isHoldingEngine = true end end Natives.InvokeVoid(0xE1EF3C1216AFF2CD, localPed) if not Natives.InvokeBool(0x01BF60A500E28887, nearby) then Natives.InvokeVoid(0xB69317BF5E782347, nearby) Script.Yield(50) end if Natives.InvokeBool(0x01BF60A500E28887, nearby) then Natives.InvokeVoid(0x3882114BDE571AD4, nearby, false) Natives.InvokeVoid(0x1760FFA8AB074D66, nearby, true) Natives.InvokeVoid(0x45F6D8EEF34ABEF1, nearby, -4000.0) Natives.InvokeVoid(0x8ABA6AF54B942B95, nearby, true) Natives.InvokeVoid(0x2497C4717C8B881E, nearby, false, true, true) stolenEngineVehicle = nearby end end Script.Yield(1000) end end if isHoldingEngine then local carryDict = "anim@heists@box_carry@" if not Natives.InvokeBool(0x1F0B79228E461EC9, localPed, carryDict, "idle", 3) then Natives.InvokeVoid(0xD3BD40951412FEF6, carryDict) Natives.InvokeVoid(0xEA47FE3719165B94, localPed, carryDict, "idle", 8.0, -8.0, -1, 49, 0, false, false, false) end end return true end) end
