angle = 180 pushDelay = 0 forceKeyDown = false forceActive = false animWaiting = false pushPending = false ragdolled = false featureHash = Utils.Joaat("TheForce")
FeatureMgr.AddFeature(featureHash, "The Force", eFeatureType.Toggle, "Star Wars Style Force Grab And Push.\nPress E To Grab, Press E Again To Push.\n ", function(feature) end)
Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then if pushPending or animWaiting then SET_TIME_SCALE(1.0) end forceActive = false; animWaiting = false; pushPending = false; ragdolled = false pushDelay = 0 CLEAR_PED_TASKS(getPlayerPed()) return false end if FeatureMgr.IsFeatureEnabled(featureHash) then local pid = getPlayerPed() local keyNow = Natives.InvokeBool(0xE2587F8CBBD87B1D, 0, 38) local justPressed = keyNow and not forceKeyDown forceKeyDown = keyNow if justPressed and not animWaiting then if not forceActive then forceActive = true; ragdolled = false PLAY_SOUND_FRONTEND(-1, "FocusOut", "HintCamSounds", true) loadAndPlayAnim(ForceAnimCore, ForceAnim, 2.0, 49) else CLEAR_PED_TASKS(pid) loadAndPlayAnim(PushAnimCore, PushAnim, 10.0, 1) animWaiting = true pushDelay = 0 end end if animWaiting then pushDelay = pushDelay + 1 if pushDelay >= 60 then animWaiting = false; pushPending = true; forceActive = false end end if pushPending then pushPending = false PLAY_SOUND_FRONTEND(-1, "FocusOut", "HintCamSounds", true) SET_TIME_SCALE(0.2) GUI.AddToast("The Force", "PUSH!", 2000) Script.Yield(1000) SET_TIME_SCALE(1.0) CLEAR_PED_TASKS(pid) local vec = GET_ENTITY_FORWARD_VECTOR(pid) local loc = GET_ENTITY_COORDS(pid) local cam = GET_GAMEPLAY_CAM_ROT() local f = 50 local Fx = -(math.sin(math.rad(cam.z)) * f * 20) local Fy =  math.cos(math.rad(cam.z)) * f * 20 local Fz = f * (cam.x * 0.1) for _, veh in ipairs(getAllVehicles()) do SET_ENTITY_INVINCIBLE(veh, false) if IS_ENTITY_IN_ANGLED_AREA(veh,loc.x,loc.y,loc.z,loc.x+(vec.x*100),loc.y+(vec.y*100),loc.z,angle,false,false,100) then APPLY_FORCE_TO_ENTITY(veh,1,Fx,Fy,Fz,0,0,0,true,false,true,true,true,true) end end for _, ped in ipairs(getAllPeds()) do if ped ~= pid and IS_ENTITY_IN_ANGLED_AREA(ped,loc.x,loc.y,loc.z,loc.x+(vec.x*100),loc.y+(vec.y*100),loc.z,angle,false,false,100) then APPLY_FORCE_TO_ENTITY(ped,1,Fx,Fy,Fz,0,0,0,true,false,true,true,true,true) end end end if forceActive then local loc = GET_ENTITY_COORDS(pid) local cam = GET_GAMEPLAY_CAM_ROT() 
local playerVeh = GET_VEHICLE_PED_IS_IN(pid) local camX = ((cam.x + 90) * 0.08) - 2; camX = camX * camX local mx = loc.x - (math.sin(math.rad(cam.z)) * camX) local my = loc.y + (math.cos(math.rad(cam.z)) * camX) local mz = loc.z for _, veh in ipairs(getAllVehicles()) do if veh ~= playerVeh then SET_ENTITY_INVINCIBLE(veh, true) if not NETWORK_HAS_CONTROL_OF_ENTITY(veh) then NETWORK_REQUEST_CONTROL_OF_ENTITY(veh) end local vp = GET_ENTITY_COORDS(veh) local dist = GET_DISTANCE_BETWEEN_COORDS(mx,my,mz,vp.x,vp.y,vp.z) if dist > 0 then local vel = GET_ENTITY_VELOCITY(veh) APPLY_FORCE_TO_ENTITY(veh,1,-vel.x*0.005+(mx-vp.x)/(dist*2),-vel.y*0.005+(my-vp.y)/(dist*2),Force*2-vel.z+(mz-vp.z)/(dist*2),0,0,0,true,false,true,true,true,true) end end end end Script.Yield(0) else if forceActive or animWaiting or pushPending then SET_TIME_SCALE(1.0) CLEAR_PED_TASKS(getPlayerPed()) end forceActive = false animWaiting = false pushPending = false ragdolled = false pushDelay = 0 Script.Yield(100) end return true end)
