local function RequestControl(ent) if not NETWORK_HAS_CONTROL_OF_ENTITY(ent) then NETWORK_REQUEST_CONTROL_OF_ENTITY(ent) for i = 1, 50 do if NETWORK_HAS_CONTROL_OF_ENTITY(ent) then return true end Script.Yield(10) end end return NETWORK_HAS_CONTROL_OF_ENTITY(ent) end
FeatureMgr.AddFeature(Utils.Joaat("VR_TOWING_SPAWN"), "Spawn Tow Truck", eFeatureType.Button, "Spawns The Selected Tow Truck", function() local oldTruck = vr_myVehicle() if oldTruck ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, oldTruck) then local ped = vr_myPed() Natives.InvokeVoid(0xD3DBCE61A490BE02, ped, oldTruck, 16) Script.Yield(500) Natives.InvokeVoid(0x06843DA7060A026B, oldTruck, -10000.0, -10000.0, -500.0, true, false, false, true) end local ped = vr_myPed() local c = VR_GET_ENTITY_COORDS(ped, false) local heading = VR_GET_ENTITY_HEADING(ped) local ti = FeatureMgr.GetFeature(Utils.Joaat("VR_COMBO_TOWTRUCKS")):GetListIndex() local truck = GTA.SpawnVehicle(vr_towtrucks[ti+1], c.x, c.y, c.z, heading, true, false) if truck ~= 0 then Natives.InvokeVoid(0x1A9205C1B9EE827F, truck, false) Script.Yield(150) Natives.InvokeBool(0x49733E92263139D1, truck, 0.0) Natives.InvokeVoid(0x1A9205C1B9EE827F, truck, true, true) Natives.InvokeVoid(0xAD738C3085FE7E11, truck, false, true) VR_SET_PED_INTO_VEHICLE(ped, truck, -1) end end)
FeatureMgr.AddFeature(Utils.Joaat("VR_TOWING_ATTACH"), "Force Attach", eFeatureType.Button, "Attaches Nearest Towable Vehicle", function() local myTruck = vr_myVehicle() if myTruck == 0 then return end local pid = getPlayerPed() local closest = nil local closestDist = 20.0 for _, veh in ipairs(getAllVehicles()) do if veh ~= myTruck then local vehClass = Natives.InvokeInt(0x29439776AAA00A62, veh) if vehClass ~= 13 and vehClass ~= 14 and vehClass ~= 15 and vehClass ~= 16 and vehClass ~= 21 then local d = getDistance3D(pid, veh) if d < closestDist then closestDist = d; closest = veh end end end end if closest and RequestControl(closest) then Natives.InvokeVoid(0x29A16F8D621C4508, myTruck, closest, true, 0.0, 10.0, 0.0) Natives.InvokeVoid(0x2497C4717C8B881E, closest, false, true, true) Natives.InvokeVoid(0x8ABA6AF54B942B95, closest, true) GUI.AddToast("Towing Module", "Vehicle Attached", 3000) else GUI.AddToast("Towing Module", "No Towable Vehicles Found", 3000) end end)
FeatureMgr.AddFeature(Utils.Joaat("VR_TOWING_DETACH"), "Detach Tow", eFeatureType.Button, "Detaches Vehicle", function() local myTruck = vr_myVehicle() if myTruck ~= 0 then local towed = Natives.InvokeInt(0xEFEA18DCF10F8F75, myTruck) if towed ~= 0 and RequestControl(towed) then Natives.InvokeVoid(0xC2DB6B6708350ED8, myTruck, towed) GUI.AddToast("Towing Module", "Vehicle Detached", 3000) else GUI.AddToast("Towing Module", "Nothing Attached", 3000) end end end)
FeatureMgr.AddFeature(Utils.Joaat("VR_TOWING_DELETE"), "Delete Truck", eFeatureType.Button, "Disposes Of Truck", function() local myTruck = vr_myVehicle() if myTruck ~= 0 and RequestControl(myTruck) then local ped = vr_myPed() Natives.InvokeVoid(0xD3DBCE61A490BE02, ped, myTruck, 16) Script.Yield(1000) Natives.InvokeVoid(0x06843DA7060A026B, myTruck, -10000.0, -10000.0, -500.0, true, false, false, true) end end)
FeatureMgr.AddFeature(Utils.Joaat("VR_FLATBED_ATTACH"), "Attach Vehicle", eFeatureType.Button, "Attaches Nearest Vehicle To Flatbed", function() local myTruck = vr_myVehicle() if myTruck == 0 then return end local closest = 0 local minDst = 10.0 local truckPos = VR_GET_ENTITY_COORDS(myTruck, true) for _, veh in ipairs(getAllVehicles()) do if veh ~= myTruck and Natives.InvokeBool(0x7239B21A38F536BA, veh) then local vPos = VR_GET_ENTITY_COORDS(veh, true) local dist = math.sqrt((vPos.x - truckPos.x)^2 + (vPos.y - truckPos.y)^2 + (vPos.z - truckPos.z)^2) if dist < minDst then minDst = dist; closest = veh end end end if closest ~= 0 and RequestControl(closest) then Natives.InvokeVoid(0x6B9BBD38AB0796DF, myTruck, closest, 0, 0.0, -2.5, 0.865, 0.0, 0.0, 0.0, 1, 1, 0, 1, 0, 1) GUI.AddToast("Flatbed", "Vehicle Attached", 2000) else GUI.AddToast("Flatbed", "No Vehicle Nearby", 2000) end end)
-- Traffic Fucker
trafficFuckerEnabled = false trafficFuckerHash = Utils.Joaat("VR_TRAFFIC_FUCKER") rampConfig = { { name = "Root Ramp", model = "phantom2", x = 0.0, y = 0.0, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 1", model = "phantom2", x = 1.2, y = -1.8, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 2", model = "phantom2", x = -1.2, y = -1.8, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 3", model = "phantom2", x = -2.4, y = -3.6, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 4", model = "phantom2", x = 2.4,  y = -3.6, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 5", model = "phantom2", x = 3.6, y = -5.4, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 6", model = "phantom2", x = -3.6, y = -5.4, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 7", model = "phantom2", x = 4.8, y = -7.2, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 8", model = "phantom2", x = -4.8, y = -7.2, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 9", model = "phantom2", x = 6.0, y = -9.0, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 10", model = "phantom2", x = -6.0, y = -9.0, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 11", model = "phantom2", x = 7.2, y = -10.8, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 }, { name = "Ramp 12", model = "phantom2", x = -7.2, y = -10.8, z = -0.02, rx = 0.0, ry = 0.0, rz = 0.0 } } spawnedRamps = {}
function CleanupRamps() for i = 1, #spawnedRamps do local ramp = spawnedRamps[i] if ramp and ramp ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, ramp) then Natives.InvokeVoid(0x961AC54BF0613F5D, ramp, true, true) Natives.InvokeVoid(0xAD738C3085FE7E11, ramp, true, true) local ptr = Memory.Alloc(8) if ptr then Memory.WriteInt(ptr, ramp) Natives.InvokeVoid(0xEA386986E786A54F, ptr) Memory.Free(ptr) end end end spawnedRamps = {} end
function BuildRampAssembly(targetVeh) CleanupRamps() local pos = VR_InvokeV3(0x3FEF770D40960D5A, targetVeh, true) if not pos or not pos.x then return end local heading = Natives.InvokeFloat(0xE83D4F9BA2A38914, targetVeh) local minVec = Memory.Alloc(24) local maxVec = Memory.Alloc(24) local targetModel = Natives.InvokeInt(0x9F47B058362C84B5, targetVeh) Natives.InvokeVoid(0x03E8D3D5F549087A, targetModel, minVec, maxVec) local hostMinZ = Memory.ReadFloat(minVec + 16)  Memory.Free(minVec) Memory.Free(maxVec) local phantomMinZ = -1.15 local baseZOffset = hostMinZ - phantomMinZ local rampModelHash = Utils.Joaat("phantom2") RequestModelAndWait(rampModelHash) for i = 1, #rampConfig do local entry = rampConfig[i] local ramp = GTA.SpawnVehicle(rampModelHash, pos.x, pos.y, pos.z, heading, true, false) if ramp and ramp ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, ramp) then Natives.InvokeVoid(0x1718DE8E3F2823CA, ramp, true) Natives.InvokeVoid(0xE05E81A888FA63C8, ramp, true) Natives.InvokeVoid(0x0DC7CABAB1E9B67E, ramp, true) Natives.InvokeVoid(0x3882114BDE571AD4, ramp, true) Natives.InvokeVoid(0xFAEE099C6F890BB8, ramp, true, true, true, true, true, true, true, true) Natives.InvokeVoid(0x25BC98A59C2EA962, ramp, 1) Natives.InvokeVoid(0x710311ADF0E20730, ramp, true) Natives.InvokeVoid(0xACAD101E1FB66689, ramp, true) Natives.InvokeVoid(0x3910051CCECDB00C, ramp, true) Natives.InvokeVoid(0xF19D095E42D430CC, ramp, true) Natives.InvokeVoid(0xAB54A438726D25D5, ramp, 1.0) Natives.InvokeVoid(0xA53ED5520C07654A, ramp, targetVeh, false) Natives.InvokeVoid(0xA53ED5520C07654A, targetVeh, ramp, false) for j = 1, #spawnedRamps do local prevRamp = spawnedRamps[j] if prevRamp and prevRamp ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, prevRamp) then Natives.InvokeVoid(0xA53ED5520C07654A, ramp, prevRamp, false) Natives.InvokeVoid(0xA53ED5520C07654A, prevRamp, ramp, false) end end Natives.InvokeVoid(0x1A9205C1B9EE827F, ramp, true, true) Natives.InvokeVoid(0x0A50A1EEDAD01E65, ramp, true) local adjustedZ = (entry.z or 0.0) + baseZOffset Natives.InvokeVoid(0x6B9BBD38AB0796DF, ramp, targetVeh, 0, entry.x, entry.y, adjustedZ, entry.rx or 0.0, entry.ry or 0.0, entry.rz or 0.0, false, false, true, false, 2, true) table.insert(spawnedRamps, ramp) end end end
FeatureMgr.AddFeature(trafficFuckerHash, "Traffic Fucker", eFeatureType.Toggle, "Attaches An Array Of Phantom\nWedge Around Your Vehicle\n ", function(f) trafficFuckerEnabled = f:IsToggled() end)
Script.QueueJob(function() local lastVeh = 0 while true do if trafficFuckerEnabled then local localPed = Natives.InvokeInt(0xD80958FC74E988A6) if localPed and localPed ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, localPed) then local currentVeh = Natives.InvokeInt(0x9A9112A0FE9A4713, localPed, false) if currentVeh and currentVeh ~= 0 and Natives.InvokeBool(0x7239B21A38F536BA, currentVeh) then if #spawnedRamps == 0 or currentVeh ~= lastVeh then lastVeh = currentVeh BuildRampAssembly(currentVeh) end else if #spawnedRamps > 0 then CleanupRamps() lastVeh = 0 end end end else if #spawnedRamps > 0 then CleanupRamps() lastVeh = 0 end end Script.Yield(10) end end)
-- Traffic Yeeter
traffic_yeeter_enabled = false yeeter_ram_cooldown = 0
FeatureMgr.AddFeature(Utils.Joaat("VR_TRAFFIC_YEETER"), "Traffic Yeeter", eFeatureType.Toggle, "Fling Cars Out Of The Way\nWhen Holding The Horn\n ", function(f) traffic_yeeter_enabled = f:IsToggled() end)
Script.RegisterLooped(function() if not traffic_yeeter_enabled then return end local veh = vr_myVehicle() if veh == 0 then return end local is_holding_horn = InvokeBool(0xF3A21BCD95725A4A, 0, 86) if is_holding_horn then local current_time = os.clock() if current_time - yeeter_ram_cooldown > 0.15 then local playerSpeed = Natives.InvokeFloat(0xD5037BA82E12416F, veh) if playerSpeed > 8.0 then local playerPos = VR_GET_ENTITY_COORDS(veh, false) local forward = VR_GET_ENTITY_FORWARD_VECTOR(veh) local bumperX = playerPos.x + (forward.x * 4.5) local bumperY = playerPos.y + (forward.y * 4.5) local bumperZ = playerPos.z local allVehs = getAllVehicles() for _, otherVeh in ipairs(allVehs) do if otherVeh ~= veh then local otherPos = VR_GET_ENTITY_COORDS(otherVeh, false) local dx = otherPos.x - bumperX local dy = otherPos.y - bumperY local dz = otherPos.z - bumperZ local dist = math.sqrt(dx*dx + dy*dy + dz*dz) if dist < 6.5 and dist > 0.1 then local dot = (dx * forward.x + dy * forward.y + dz * forward.z) / dist if dot > 0.55 then local forceMult = playerSpeed * 40.0 local pushX = (dx / dist) * forceMult * 0.5 + forward.x * forceMult local pushY = (dy / dist) * forceMult * 0.5 + forward.y * forceMult local pushZ = 1500.0 + (playerSpeed * 2.0) Natives.InvokeVoid(0xC5F68BE9613E2D18, otherVeh, 1, pushX, pushY, pushZ, 0, 0, 0, 0, false, false, true, false, true) Natives.InvokeVoid(0xC5F68BE9613E2D18, otherVeh, 1, pushY * 0.2, -pushX * 0.2, 0, 0, 0, 0, false, false, true, false, true) yeeter_ram_cooldown = current_time end end end end end end end end)
