extraToggleHash = Utils.Joaat("VR_VEHICLE_EXTRA_TOGGLE") vr_selected_extra_index = 1 vr_extras_list, vr_extras_id_list = {}, {}
function update_vehicle_extras() vr_extras_list = {} vr_extras_id_list = {} local ped = Natives.InvokeInt(0xD80958FC74E988A6) if not ped or not Natives.InvokeBool(0x997ABD671D25CA0B, ped, false) then table.insert(vr_extras_list, "Not In A Vehicle") table.insert(vr_extras_id_list, 0) return end local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, ped, false) if not veh or veh == 0 then table.insert(vr_extras_list, "Not In A Vehicle") table.insert(vr_extras_id_list, 0) return end for i = 1, 50 do if Natives.InvokeBool(0x1262D55792428154, veh, i) then table.insert(vr_extras_id_list, i) local is_on = Natives.InvokeBool(0xD2E6822DBFD6C8BD, veh, i) local status = is_on and " [ON]" or " [OFF]" table.insert(vr_extras_list, ("EXTRA " .. i .. status):upper()) end end if #vr_extras_list == 0 then table.insert(vr_extras_list, "No Extras Found") table.insert(vr_extras_id_list, 0) end end
FeatureMgr.AddFeature(Utils.Joaat("VR_SELECT_EXTRA_COMBO"), "Select Extra", eFeatureType.Combo, "", function(f) vr_selected_extra_index = f:GetListIndex() + 1 end, false):SetList(vr_extras_list)
