-- Vehicle Forge
TEMP_MODEL = 0 eModelHash = { BR8 = Utils.Joaat("openwheel1"), Tailgater = Utils.Joaat("tailgater"), SultanRS = Utils.Joaat("sultanrs") } modelNames = { "BR8", "Tailgater", "Sultan RS" }
function ExecuteForge(isToggled) local playerVehicle = GTA.GetLocalVehicle() if playerVehicle == nil then GUI.AddToast("Vehicle Forge", "You Must Be In A Vehicle", 3000) return false end local baseModelInfo = playerVehicle.ModelInfo if baseModelInfo == nil then GUI.AddToast("Vehicle Forge", "Unable To Retrieve Base Model Info.", 3000) return false end local vehicleModelInfo = CVehicleModelInfo.FromBaseModelInfo(baseModelInfo) if vehicleModelInfo == nil or not (vehicleModelInfo:IsCar() or vehicleModelInfo:IsEmergency() or vehicleModelInfo:IsIndustrial()) then GUI.AddToast("Vehicle Forge", "Target Vehicle Model Is Invalid", 3000) return false end if isToggled then local selectedIndex = FeatureMgr.GetFeature(Utils.Joaat("VR_VEH_MODEL")):GetListIndex() local selectedName = modelNames[selectedIndex + 1] local selectedKey = selectedName:gsub("%s+", "") local targetHash = eModelHash[selectedKey] if vehicleModelInfo.Model == targetHash then GUI.AddToast("Vehicle Forge", "Cannot Forge To The Same Model", 3000) return false end if TEMP_MODEL == 0 then TEMP_MODEL = vehicleModelInfo.Model vehicleModelInfo.Model = targetHash GUI.AddToast("Vehicle Forge", "Vehicle Model Forged To: " .. selectedName, 3000) else GUI.AddToast("Vehicle Forge", "Vehicle Model Is Already Forged", 3000) end else if TEMP_MODEL ~= 0 then vehicleModelInfo.Model = TEMP_MODEL TEMP_MODEL = 0 GUI.AddToast("Vehicle Forge", "Vehicle Model Has Been Restored", 3000) else GUI.AddToast("Vehicle Forge", "Vehicle Model Is Not Forged", 3000) end end end
FeatureMgr.AddFeature(Utils.Joaat("VR_VEH_MODEL"), "", eFeatureType.Combo, "Select The Model To Forge To\n ", function(f) local selectedName = modelNames[f:GetListIndex() + 1] GUI.AddToast("Vehicle Forge", "Selected Forge Model: " .. selectedName, 3000) end):SetList(modelNames)
FeatureMgr.AddFeature(Utils.Joaat("VR_VEH_FORGE"), "Forge Vehicle", eFeatureType.Toggle, "Swap Your Vehicle Model To The Selected Model\n ", function(f) local success = ExecuteForge(f:IsToggled()) if success == false then f:SetBoolValue(false) end end)
Script.RegisterLooped(function() if ShouldUnload and ShouldUnload() then if TEMP_MODEL ~= 0 then TEMP_MODEL = 0 end return false end if TEMP_MODEL ~= 0 and GTA.GetLocalVehicle() == nil then TEMP_MODEL = 0 local forgeFeature = FeatureMgr.GetFeature(Utils.Joaat("VR_VEH_FORGE")) if forgeFeature then forgeFeature:SetBoolValue(false) end end Script.Yield(200) return true end)
-- Vehicle Levitation
iW_levOn = false iW_levForce = 50.0 iW_levRange  = 50.0 iW_levKeys = { up = false, down = false } iW_levOn = false
function iW_dist(a, b) if not a or not b then return 9999 end local dx, dy, dz = b.x-a.x, b.y-a.y, b.z-a.z return math.sqrt(dx*dx + dy*dy + dz*dz) end
function iW_VehicleLev(enable) iW_levOn = enable if enable then GUI.AddToast("Vehicle Levitation", "Vehicle Lev ON  |  R = Lift    F = Slam", 3000, eToastPos.TOP_RIGHT) else GUI.AddToast("Vehicle Levitation", "Vehicle Lev OFF", 2000, eToastPos.TOP_RIGHT) end end
Script.RegisterLooped(function() if iW_levOn then local is_up_held = VR_IS_CONTROL_PRESSED(0, 45) local is_down_held = VR_IS_CONTROL_PRESSED(0, 23) if is_up_held or is_down_held then local lped = GTA.GetLocalPed() if lped then local lpos = lped.Position for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do local v = PoolMgr.GetCVehicle(i) if v and iW_dist(lpos, v.Position) <= iW_levRange then local vh = GTA.PointerToHandle(v) if vh and vh ~= 0 then local fz = is_up_held and iW_levForce * 2 or -iW_levForce * 2 Natives.InvokeVoid(0x1C99BB7B6E96D16F, vh, 0.0, 0.0, fz) end end end end end end Script.Yield(0) return true end)
