Script.RegisterLooped(function() if ShouldUnload() then vehicle_lock_bindingMode = 0 return false end if vehicle_lock_bindingMode > 0 then for i = 0, 350 do if VR_IS_CONTROL_JUST_PRESSED(0, i) then vehicle_lock_key = i vehicle_lock_bindingMode = 0 GUI.AddToast("Vehicle Lock", "Vehicle Lock Key Bound Successfully!", 3000) break end end return true end if not vehicle_lock_enabled then return true end Natives.InvokeVoid(0xFE99B66D079CF6BC, 0, vehicle_lock_key, true) if Natives.InvokeBool(0x91AEF906BCA88877, 0, vehicle_lock_key) then local playerPed = Natives.InvokeInt(0xD80958FC74E988A6) local isPedInAnyVehicle = Natives.InvokeBool(0x997ABD671D25CA0B, playerPed, false) local targetVehicle = 0 if isPedInAnyVehicle then targetVehicle = Natives.InvokeInt(0x9A9112A0FE9A4713, playerPed, false) else local playerCoords = VR_InvokeV3(0x3FEF770D40960D5A, playerPed, true) targetVehicle = Natives.InvokeInt(0xF73EB622C4F1689B, playerCoords.x, playerCoords.y, playerCoords.z, 5.0, 0, 70) end if Natives.InvokeBool(0x7239B21A38F536BA, targetVehicle) then local currentLockStatus = Natives.InvokeInt(0x25BC98A59C2EA962, targetVehicle) local newLockState = (currentLockStatus >= 2) and 1 or (isPedInAnyVehicle and 4 or 2) if not Natives.InvokeBool(0x01BF60A500E28887, targetVehicle) then Natives.InvokeVoid(0xB69317BF5E782347, targetVehicle) end if not isPedInAnyVehicle then local animDict = "anim@mp_player_intmenu@key_fob@" local animName = "fob_click" Natives.InvokeVoid(0xD3BD40951412FEF6, animDict) local timeout = 0 while not Natives.InvokeBool(0xD031A9162D01088C, animDict) and timeout < 100 do Natives.InvokeVoid(0xFE99B66D079CF6BC, 0, 29, true) Script.Yield(10) timeout = timeout + 1 end if Natives.InvokeBool(0xD031A9162D01088C, animDict) then Natives.InvokeVoid(0xEA47FE3719165B94, playerPed, animDict, animName, 8.0, -8.0, -1, 48, 0.0, false, false, false) end end Natives.InvokeVoid(0xB664292EAECF7FA6, targetVehicle, newLockState) Natives.InvokeVoid(0xA2F80B8D040727CC, targetVehicle, newLockState >= 2) local flashes = (newLockState >= 2) and 1 or 2 for i = 1, flashes do for j = 1, 6 do Natives.InvokeVoid(0xFE99B66D079CF6BC, 0, 29, true) Natives.InvokeVoid(0x34E710FF01247C5A, targetVehicle, 2) Natives.InvokeVoid(0x92B35082E0B42F66, targetVehicle, true) if j == 1 then Natives.InvokeVoid(0x9C8C6504B5B63D2C, targetVehicle, 100, 0, false) end Script.Yield(0) end Natives.InvokeVoid(0x34E710FF01247C5A, targetVehicle, 0) Natives.InvokeVoid(0x92B35082E0B42F66, targetVehicle, false) if i < flashes then for j = 1, 6 do Natives.InvokeVoid(0xFE99B66D079CF6BC, 0, 29, true) Script.Yield(0) end end end end end return true end)
