ocal grabClip = "hands_up_idle_a_player_one" Natives.InvokeVoid(0xD3BD40951412FEF6, grabDict) while not Natives.InvokeBool(0xD031A9162D01088C, grabDict) do Script.Yield(10) end Natives.InvokeVoid(0x5F9532F3B5CC2551, localPed, false) Natives.InvokeVoid(0xEA47FE3719165B94, localPed, grabDict, grabClip, 8.0, -8.0, -1, 49, 0, false, false, false) Script.Yield(100) while iW_throw.on do Natives.InvokeVoid(0x28D1A16553C51776, localPed, grabDict, grabClip, 0.5) if iW_throw.playerVehs and not Natives.InvokeBool(0x01BF60A500E28887, nearby) then Natives.InvokeVoid(0xB69317BF5E782347, nearby) end if Natives.InvokeBool(0x580417101DDB492F, 0, 38) then break end Script.Yield(0) end Natives.InvokeVoid(0x5F9532F3B5CC2551, localPed, true) Natives.InvokeVoid(0x176CECF6F920D707, localPed) local throwDict = "anim@mp_player_intcelebrationmale@thumbs_up" local throwAnim = "thumbs_up" Natives.InvokeVoid(0xD3BD40951412FEF6, throwDict) while not Natives.InvokeBool(0xD031A9162D01088C, throwDict) do Script.Yield(10) end Natives.InvokeVoid(0xEA47FE3719165B94, localPed, throwDict, throwAnim, 8.0, -8.0, -1, 48, 0, false, false, false) local animDuration = Natives.InvokeFloat(0xFEDDF04D62B8D790, throwDict, throwAnim) * 1000 local triggerTime = animDuration * 0.22 local startThrowTime = Time.GetEpocheMs() if iW_throw.playerVehs then local throwReqDl = Time.GetEpocheMs() + 500 while Time.GetEpocheMs() < throwReqDl and not Natives.InvokeBool(0x01BF60A500E28887, nearby) do Natives.InvokeVoid(0xB69317BF5E782347, nearby) Script.Yield(0) end end while (Time.GetEpocheMs() - startThrowTime) < triggerTime do if iW_throw.playerVehs and not Natives.InvokeBool(0x01BF60A500E28887, nearby) then Natives.InvokeVoid(0xB69317BF5E782347, nearby) Natives.InvokeVoid(0x1A9205C1B9EE827F, nearby, true, true) end Script.Yield(0) end if iW_throw.playerVehs then Natives.InvokeVoid(0xB69317BF5E782347, nearby) Natives.InvokeVoid(0x1A9205C1B9EE827F, nearby, true, true) end Natives.InvokeVoid(0x961AC54BF0613F5D, nearby, true, true) Natives.InvokeVoid(0x1A9205C1B9EE827F, nearby, true) local rx, _, rz = Natives.InvokeV3(0x5B4E4C817FCC2DFB, 2) local cosPitch = math.cos(math.rad(rx)) local camDirX, camDirY, camDirZ = -math.sin(math.rad(rz)) * cosPitch, math.cos(math.rad(rz)) * cosPitch, math.sin(math.rad(rx)) if iW_throw.playerVehs then Natives.InvokeVoid(0xB69317BF5E782347, nearby) Natives.InvokeVoid(0x1A9205C1B9EE827F, nearby, true, true) end Natives.InvokeVoid(0xC5F68BE9613E2D18, nearby, 3, camDirX * iW_throw.force, camDirY * iW_throw.force, camDirZ * iW_throw.force, 0, 0, 0, 0, false, false, true, false, true) Script.Yield(100) Natives.InvokeVoid(0x176CECF6F920D707, localPed) local flightEndTime = Time.GetEpocheMs() + 1000 while Time.GetEpocheMs() < flightEndTime do Natives.InvokeVoid(0x1A9205C1B9EE827F, nearby, false, true) Script.Yield(0) end Natives.InvokeVoid(0x1A9205C1B9EE827F, nearby, true, true) Natives.InvokeVoid(0xCCF1E97BEFDAE480, localPed, true, true) end return true end) end
-- VR GPS
vr_gps_enabled = false vr_gps_max_nodes = 25 vr_gps_arrow_spacing = 2.0 vr_gps_line_smoothing = 0.2 vr_gps_line_z_offset = 0.8 vr_gps_lowering_strength = 6.0 vr_gps_rainbow_mode = false vr_gps_rainbow_speed = 0.5 vr_myPed = function() local p = GTA.GetLocalPed() return p and GTA.PointerToHandle(CPed.FromAddress(p:GetAddress())) or 0 end VR_GET_ENTITY_COORDS = function(e, a) return V3(0x3FEF770D40960D5A, e, a) end vr_gps_colors = {r = 136, g = 63, b = 200, a = 100} marker_arrow = 2
function VR_QuadraticBezierCurve(p0, p1, p2, t) local u = 1 - t local tt = t * t local uu = u * u local result = {x = uu * p0.x + 2 * u * t * p1.x + tt * p2.x, y = uu * p0.y + 2 * u * t * p1.y + tt * p2.y, z = uu * p0.z + 2 * u * t * p1.z + tt * p2.z} local dir = { x = 2 * u * (p1.x - p0.x) + 2 * t * (p2.x - p1.x), y = 2 * u * (p1.y - p0.y) + 2 * t * (p2.y - p1.y), z = 2 * u * (p1.z - p0.z) + 2 * t * (p2.z - p1.z)} local len = math.sqrt(dir.x * dir.x + dir.y * dir.y + dir.z * dir.z) if len > 0 then dir.x = dir.x / len dir.y = dir.y / len dir.z = dir.z / len end return result, dir end
function VR_DrawArrowsBetweenPoints(point_a, point_b, player_pos, r, g, b, a) local dx = point_b.x - point_a.x local dy = point_b.y - point_a.y local dz = point_b.z - point_a.z local dist = math.sqrt(dx * dx + dy * dy + dz * dz) if dist < 0.1 then return end local count = math.floor(dist / vr_gps_arrow_spacing) local dir = {x = dx / dist, y = dy / dist, z = dz / dist} for i = 0, count do local draw_pos = {x = point_a.x + dir.x * (i * vr_gps_arrow_spacing), y = point_a.y + dir.y * (i * vr_gps_arrow_spacing), z = point_a.z + dir.z * (i * vr_gps_arrow_spacing)} local pdx = draw_pos.x - player_pos.x local pdy = draw_pos.y - player_pos.y local pdz = draw_pos.z - player_pos.z local player_dist = math.sqrt(pdx * pdx + pdy * pdy + pdz * pdz) if player_dist > 0.1 then draw_pos.z = draw_pos.z - (vr_gps_lowering_strength / player_dist) + vr_gps_line_z_offset end VR_InvokeVoid(0x28477EC23D892089, marker_arrow, draw_pos.x, draw_pos.y, draw_pos.z, dir.x, dir.y, dir.z, 90.0, 0.0, 0.0, 1.0, 1.0, 1.0, r, g, b, a, false, false, 0, false, 0, 0, false) end end
function VR_DrawArrowsSmooth(point_a, point_b, point_c, player_pos, r, g, b, a) local dx1 = point_b.x - point_a.x local dy1 = point_b.y - point_a.y local dz1 = point_b.z - point_a.z local dx2 = point_c.x - point_b.x local dy2 = point_c.y - point_b.y local dz2 = point_c.z - point_b.z local dist1 = math.sqrt(dx1 * dx1 + dy1 * dy1 + dz1 * dz1) local dist2 = math.sqrt(dx2 * dx2 + dy2 * dy2 + dz2 * dz2) local total_dist = dist1 + dist2 if total_dist < 0.1 then return end local count = math.floor(total_dist / vr_gps_arrow_spacing) for i = 1, count do local t = 1 - (i / count) local draw_pos, dir = VR_QuadraticBezierCurve(point_a, point_b, point_c, t) local pdx = draw_pos.x - player_pos.x local pdy = draw_pos.y - player_pos.y local pdz = draw_pos.z - player_pos.z local player_dist = math.sqrt(pdx * pdx + pdy * pdy + pdz * pdz) if player_dist > 0.1 then draw_pos.z = draw_pos.z - (vr_gps_lowering_strength / player_dist) + vr_gps_line_z_offset end VR_InvokeVoid(0x28477EC23D892089, marker_arrow, draw_pos.x, draw_pos.y, draw_pos.z, dir.x, dir.y, dir.z, 90.0, 0.0, 0.0, 1.0, 1.0, 1.0, r, g, b, a, false, false, 0, false, 0, 0, false) end end
function VR_GetCornerPoints(point_a, point_b, point_c) local b_to_a = {x = point_a.x - point_b.x, y = point_a.y - point_b.y, z = point_a.z - point_b.z} local b_to_c = {x = point_c.x - point_b.x, y = point_c.y - point_b.y, z = point_c.z - point_b.z} local len_a = math.sqrt(b_to_a.x * b_to_a.x + b_to_a.y * b_to_a.y + b_to_a.z * b_to_a.z) local len_c = math.sqrt(b_to_c.x * b_to_c.x + b_to_c.y * b_to_c.y + b_to_c.z * b_to_c.z) local result_a, result_c if len_a > 0 then result_a = {x = point_b.x + (b_to_a.x / len_a) * vr_gps_line_smoothing * len_a, y = point_b.y + (b_to_a.y / len_a) * vr_gps_line_smoothing * len_a, z = point_b.z + (b_to_a.z / len_a) * vr_gps_line_smoothing * len_a} else result_a = point_b end if len_c > 0 then result_c = {x = point_b.x + (b_to_c.x / len_c) * vr_gps_line_smoothing * len_c, y = point_b.y + (b_to_c.y / len_c) * vr_gps_line_smoothing * len_c, z = point_b.z + (b_to_c.z / len_c) * vr_gps_line_smoothing * len_c} else result_c = point_b end return result_a, result_c end
function VR_GetGPSRoute(max_nodes) local result = {} local waypoint_blip = VR_InvokeInt(0x1BEDE233E6CD2A1F, 8) if waypoint_blip == 0 or not VR_InvokeBool(0xA6DB27D19ECBB7DA, waypoint_blip) then return result end local waypoint_coord = VR_InvokeV3(0xFA7C7F0AADF25D09, waypoint_blip) local player_coord = VR_GET_ENTITY_COORDS(vr_myPed(), true) local dx = waypoint_coord.x - player_coord.x local dy = waypoint_coord.y - player_coord.y local dist = math.sqrt(dx * dx + dy * dy) if dist < 1.0 then return result end local num_points = math.min(max_nodes, math.floor(dist / 10.0) + 1) for i = 1, num_points do local t = i / num_points local point = {x = player_coord.x + dx * t, y = player_coord.y + dy * t, z = player_coord.z + 0.5 } table.insert(result, point) end return result end
function VR_GetGPSRouteAdvanced(max_nodes) local result = {} local player_ped = vr_myPed() local player_coord = VR_GET_ENTITY_COORDS(player_ped, true) local waypoint_blip = VR_InvokeInt(0x1BEDE233E6CD2A1F, 8) if waypoint_blip == 0 or not VR_InvokeBool(0xA6DB27D19ECBB7DA, waypoint_blip) then  return result  end local waypoint_coord = VR_InvokeV3(0xFA7C7F0AADF25D09, waypoint_blip) local dx = waypoint_coord.x - player_coord.x local dy = waypoint_coord.y - player_coord.y local dz = waypoint_coord.z - player_coord.z local total_dist = math.sqrt(dx * dx + dy * dy + dz * dz) if total_dist < 5.0 then return result end local num_segments = math.max(3, max_nodes) for i = 0, num_segments do local t = i / num_segments local point = {x = player_coord.x + dx * t, y = player_coord.y + dy * t, z = player_coord.z + dz * t} local ground_z_ptr = Memory.Alloc(8) if ground_z_ptr then local success = VR_InvokeBool(0xC906A7DAB05C8D2B, point.x, point.y, point.z + 100.0, ground_z_ptr, false) if success then local ground_z = Memory.ReadFloat(ground_z_ptr) if ground_z and ground_z > -1000 then point.z = ground_z + vr_gps_line_z_offset end end Memory.Free(ground_z_ptr) end table.insert(result, point) end return result end
function VR_HSLToRGB(h, s, l) local r, g, b if s == 0 then r, g, b = l, l, l else local function hue2rgb(p, q, t) if t < 0 then t = t + 1 end if t > 1 then t = t - 1 end if t < 1/6 then return p + (q - p) * 6 * t end if t < 1/2 then return q end if t < 2/3 then return p + (q - p) * (2/3 - t) * 6 end return p end local q = l < 0.5 and l * (1 + s) or l + s - l * s local p = 2 * l - q r = hue2rgb(p, q, h + 1/3) g = hue2rgb(p, q, h) b = hue2rgb(p, q, h - 1/3) end return math.floor(r * 255), math.floor(g * 255), math.floor(b * 255) end
Script.RegisterLooped(function() if not vr_gps_enabled then Script.Yield(100) return true end local player_ped = vr_myPed() if player_ped == 0 then Script.Yield(100) return true end local player_pos = VR_GET_ENTITY_COORDS(player_ped, true) local points = VR_GetGPSRouteAdvanced(vr_gps_max_nodes) if #points < 2 then Script.Yield(100) return true end local r, g, b, a = vr_gps_colors.r, vr_gps_colors.g, vr_gps_colors.b, vr_gps_colors.a if vr_gps_rainbow_mode then local time = os.clock() * vr_gps_rainbow_speed r, g, b = VR_HSLToRGB(time % 1.0, 1.0, 0.5) end local start_point = nil for i = 1, #points do if points[i + 2] then local prev_point = start_point or points[i] local corner_a, corner_b = VR_GetCornerPoints(prev_point, points[i + 1], points[i + 2]) VR_DrawArrowsBetweenPoints(prev_point, corner_a, player_pos, r, g, b, a) VR_DrawArrowsSmooth(corner_a, points[i + 1], corner_b, player_pos, r, g, b, a) start_point = corner_b elseif points[i + 1] then local prev_point = start_point or points[i] VR_DrawArrowsBetweenPoints(prev_point, points[i + 1], player_pos, r, g, b, a) end end return true end)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS"), "GPS Waypoints", eFeatureType.Toggle, "Draws Smooth Arrow Markers Along Your GPS Route\n ", function(f) vr_gps_enabled = f:IsToggled() end)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_NODES"), "Max Route Nodes", eFeatureType.SliderInt, "Higher Numbers = Smoother Arrows\nBut More Performance Impact\n ", function(f) vr_gps_max_nodes = f:GetIntValue() end):SetLimitValues(5, 100):SetIntValue(25)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_SPACING"), "Arrow Spacing", eFeatureType.SliderFloat, "Distance Between Arrows (meters)\n ", function(f) vr_gps_arrow_spacing = f:GetFloatValue() end):SetLimitValues(1.0, 10.0):SetFloatValue(2.0)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_SMOOTH"), "Curve Smoothing", eFeatureType.SliderFloat, "Smoothing Factor For Corners (0.0 - 1.0)\n ", function(f) vr_gps_line_smoothing = f:GetFloatValue() end):SetLimitValues(0.0, 1.0):SetFloatValue(0.2)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_ZOFFSET"), "Height Offset", eFeatureType.SliderFloat, "Vertical Offset From Ground\n ", function(f) vr_gps_line_z_offset = f:GetFloatValue() end):SetLimitValues(0.0, 5.0):SetFloatValue(0.8)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_LOWER"), "Distance Lowering", eFeatureType.SliderFloat, "How Much Arrows Lower When Close To Player\n ", function(f) vr_gps_lowering_strength = f:GetFloatValue() end):SetLimitValues(0.0, 20.0):SetFloatValue(6.0)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_RAINBOW"), "Rainbow Arrows", eFeatureType.Toggle, "Cycles Arrow Colors Through Rainbow\n ", function(f) vr_gps_rainbow_mode = f:IsToggled() end)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_RAINBOW_SPEED"), "Rainbow Speed", eFeatureType.SliderFloat, "Speed Of Color Cycling\n ", function(f) vr_gps_rainbow_speed = f:GetFloatValue() end):SetLimitValues(0.1, 5.0):SetFloatValue(0.5)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_RED"), "Arrow Red", eFeatureType.SliderInt, "Red Component (0-255)\n ", function(f) vr_gps_colors.r = f:GetIntValue() end):SetLimitValues(0, 255):SetIntValue(136)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_GREEN"), "Arrow Green", eFeatureType.SliderInt, "Green Component (0-255)\n ", function(f) vr_gps_colors.g = f:GetIntValue() end):SetLimitValues(0, 255):SetIntValue(63)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_BLUE"), "Arrow Blue", eFeatureType.SliderInt, "Blue Component (0-255)\n ", function(f) vr_gps_colors.b = f:GetIntValue() end):SetLimitValues(0, 255):SetIntValue(200)
FeatureMgr.AddFeature(Utils.Joaat("VR_GPS_ALPHA"), "Arrow Alpha", eFeatureType.SliderInt, "Transparency (0-255)\n ", function(f) vr_gps_colors.a = f:GetIntValue() end):SetLimitValues(0, 255):SetIntValue(100)
-- Wall Climb
vr_wallclimb_stuck = false pop_lockout = 0 frame_counter = 0
FeatureMgr.AddFeature(Utils.Joaat("VR_WALLCLIMB"), "Wall Climb", eFeatureType.Toggle, "Sticks Vehicle To Surfaces\nPress X To Pop Up, E To Enable/Disable\n ", function(f) if not f:IsToggled() then vr_wallclimb_stuck = false frame_counter = 0 end end)
Script.RegisterLooped(function() local f = FeatureMgr.GetFeature(Utils.Joaat("VR_WALLCLIMB")) if not f or not f:IsToggled() then return true end local veh = vr_myVehicle() if veh == 0 then return true end if VR_IS_CONTROL_JUST_PRESSED(0, 73) then VR_APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS(veh, 1, 0, 0, 50.0, true, true, true, true) vr_wallclimb_stuck = false pop_lockout = os.clock() + 0.5 end local is_locked_out = os.clock() < pop_lockout if not is_locked_out then if VR_IS_CONTROL_JUST_PRESSED(0, 38) then vr_wallclimb_stuck = not vr_wallclimb_stuck end if vr_wallclimb_stuck and VR_GET_ENTITY_HEIGHT_ABOVE_GROUND(veh) > 2.5 then vr_wallclimb_stuck = false end else vr_wallclimb_stuck = false end if vr_wallclimb_stuck then frame_counter = frame_counter + 1 if frame_counter >= 10 then VR_APPLY_FORCE_TO_ENTITY_CENTER_OF_MASS(veh, 1, 0, 0, -8.0, true, true, true, true) frame_counter = 0 end else frame_counter = 0 end return true end)
-- Window Controller
win_states = { [0]=false, [1]=false, [2]=false, [3]=false } toggle_all_state = false
function ToggleWindow(idx) local v = vr_myVehicle() if v == 0 then return end win_states[idx] = not win_states[idx] if win_states[idx] then InvokeVoid(0x7AD9E6CE657D69E3, v, idx) else InvokeVoid(0x602E548F46E24D59, v, idx) end end
FeatureMgr.AddFeature(Utils.Joaat("VR_WIN_FL"), "FL Window", eFeatureType.Button, "Toggles The Front Left Window", function() ToggleWindow(0) end)
FeatureMgr.AddFeature(Utils.Joaat("VR_WIN_FR"), "FR Window", eFeatureType.Button, "Toggles The Front Righe Window", function() ToggleWindow(1) end)
FeatureMgr.AddFeature(Utils.Joaat("VR_WIN_LR"), "LR Window", eFeatureType.Button, "Toggles The Left Rear Window", function() ToggleWindow(2) end)
FeatureMgr.AddFeature(Utils.Joaat("VR_WIN_RR"), "RR Window", eFeatureType.Button, "Toggles The Righe Rear Window", function() ToggleWindow(3) end)
FeatureMgr.AddFeature(Utils.Joaat("VR_WIN_TOGGLE_ALL"), "Toggle All", eFeatureType.Button, "Toggles All Windows", function() local v = vr_myVehicle() if v == 0 then return end toggle_all_state = not toggle_all_state for i = 0, 3 do win_states[i] = toggle_all_state if toggle_all_state then InvokeVoid(0x7AD9E6CE657D69E3, v, i) else InvokeVoid(0x602E548F46E24D59, v, i) end end end)
FeatureMgr.AddFeature(Utils.Joaat("VR_WIN_REPAIR_ALL"), "Repair All", eFeatureType.Button, "Repairs All Windows", function() local v = vr_myVehicle() if v ~= 0 then for i = 0, 7 do InvokeVoid(0x772282EBEB95E682, v, i) end end end)
