-- Anon Kill
local iW_kill = {} do local isEE = false if Cherax and Cherax.GetEdition and Cherax.GetEdition() == "EE" then isEE = true end iW_kill.flags = 16|4096|524288 local addr = Memory.Scan(isEE and "E8 ? ? ? ? 66 90 FF C5" or "E8 ? ? ? ? 44 8B 7D 80") iW_kill.fn = (addr and addr ~= 0) and Memory.Rip(addr + 1) or nil local function waitMs(ms) local d = Time.GetEpocheMs() + ms while Time.GetEpocheMs() < d and not ShouldUnload() do Script.Yield() end end local function playerPos(pid) if pid == GTA.GetLocalPlayerId() then return Natives.InvokeV3(0x3FEF770D40960D5A, Natives.InvokeInt(0x43A66C31C68491C0, pid), true) end return Natives.InvokeV3(0x125E6D638B8605D4, pid) end local function lockEnt(ent) Natives.InvokeVoid(0x299EEB23175895FC, Natives.InvokeInt(0xA11700682F3AD45C, ent), false) end local function delEnt(ent) if not ent or ent == 0 or not Natives.InvokeBool(0x7239B21A38F536BA, ent) then return end local ptr = Memory.AllocInt() Memory.WriteInt(ptr, ent) Natives.InvokeVoid(0xAE3CBE5BF394C9C9, ptr) Memory.Free(ptr) end local function mkS(l, b) local o = {} for k,v in pairs(l) do o[k] = type(v)=="number" and v+b or (type(v)=="table" and mkS(v,b) or v) end return o end local function mkArr(l, b, s, c) local o = {} local cur = b+1 for i=0,c-1 do o[i]=mkS(l,cur) cur=cur+s end return o end local bdL  = {iGameState=0,interiorCurrent=204,iCurrentShop=210,SimpleInteriorBD={iBS=3,eCurrentSimpleInterior=4}} local bdFML = {propertyDetails={iCurrentlyInsideProperty=0}} local bd, bdFM, bdFM3 if isEE then bd    = mkArr(bdL,   2658019, 467, 32) bdFM  = mkArr(bdFML, 1845274, 877, 32) bdFM3 = mkArr({bInPassive=0}, 1888882, 611, 32) else bd    = mkArr(bdL,   2658016, 467, 32) bdFM  = mkArr(bdFML, 1845225, 874, 32) bdFM3 = mkArr({bInPassive=0}, 1888737, 611, 32) end local zV3 = Natives.InvokeV3(0x3FEF770D40960D5A, 0, false) iW_kill.sendAnon = function(pid, weapon, amount, flags) if not iW_kill.fn then GUI.AddToast("VROOM", "Kill: Damage Event Not Ready.", 3000) return end local tCPed = Players.GetCPed(pid) if not tCPed then return end local tAddr = tCPed:GetAddress() if not tAddr or tAddr == 0 then return end local x, y, z = playerPos(pid) local npc = GTA.CreateRandomPed(x, y, (z or 0) - 50) if not npc or npc == 0 then return end lockEnt(npc) Natives.InvokeVoid(0xEA1C610A04DB6BBB, npc, false, false) Natives.InvokeVoid(0x428CA6DBD1094446, npc, true) waitMs(500) local c = Players.GetCPed(pid) if c then local cAddr = c:GetAddress() local nPtr = GTA.HandleToPointer(npc) if cAddr and cAddr ~= 0 and nPtr then local nAddr = nPtr:GetAddress() if nAddr and nAddr ~= 0 then Memory.LuaCallCFunction(iW_kill.fn, nAddr, cAddr, cAddr + 0x90, 0, 1, Utils.sJoaat(weapon), amount, 0, 0, flags, 0, 0, 0, 0, 0, 0, 0, zV3) end end end waitMs(500) delEnt(npc) end end
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_ANON_KILL"), "MK2 Sniper", eFeatureType.Button, "Strips Godmode & Kills\nSelected Player Anonymously\n ", function(f) local sid = f:GetPlayerIndex() if sid ~= nil then Script.QueueJob(function() if Natives.InvokeBool(0x424D4687FA1E5652, sid) then return end local pPed = Natives.InvokeInt(0x43A66C31C68491C0, sid) if pPed ~= 0 then Natives.InvokeVoid(0xB69317BF5E782347, pPed) Natives.InvokeVoid(0x3882114BDE571AD4, sid, false) Natives.InvokeVoid(0x352E2B5CF420BF3B, pPed, false, false) Natives.InvokeVoid(0x6B76DC1F3AE6E6A3, pPed, 0, 1) local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, pPed, false) if veh ~= 0 then Natives.InvokeVoid(0xB69317BF5E782347, veh) Natives.InvokeVoid(0x352E2B5CF420BF3B, veh, false, false) end end for i = 1, 5 do iW_kill.sendAnon(sid, "weapon_heavysniper_mk2", 9999.0, iW_kill.flags) end end) else GUI.AddToast("VROOM", "No Player Selected!", 2000) end end)
