FeatureMgr.AddPlayerFeature(autoFlipVehicleHash, "Flip Onto Roof", eFeatureType.Button, "Flips The Selected Players Vehicle\nUpside Down Onto Its Roof\n ", function(f) local pid = f:GetPlayerIndex() if not pid then return end
Script.QueueJob(function() local cped = Players.GetCPed(pid) if not cped then return end local ph = GTA.PointerToHandle(cped) if not ph or ph == 0 then return end local veh = InvokeInt(0x9A9112A0FE9A4713, ph, false) if not veh or veh == 0 then return end local netId = InvokeInt(0xA11700682F3AD45C, veh) local hasControl = false for _ = 1, 25 do if netId and netId ~= 0 then InvokeVoid(0x299EEB23175895FC, netId, true) end InvokeVoid(0xB69317BF5E782347, veh, true) if InvokeInt(0x01BF60A500E28887, veh) == 1 then hasControl = true break end Script.Yield(10) end if not hasControl then return end Script.Yield(10) local velocity = InvokeV3(0x4805D2B1D8CF94A9, veh) local attempts = 0 while attempts < 40 do if not InvokeInt(0x7239B21A38F536BA, veh) then break end local coords = InvokeV3(0x3FEF770D40960D5A, veh, true) local rot = InvokeV3(0xAFBD61CC738D9EB9, veh, 2) if coords and rot then InvokeVoid(0x06843DA7060A026B, veh, coords.x + 0.0, coords.y + 0.0, coords.z + 2.0 + 0.0, true, true, true, false) Script.Yield(5) InvokeVoid(0x8524A8B0171D5E07, veh, 0.0 + 0.0, 180.0 + 0.0, rot.z + 0.0, 2, true) end Script.Yield(15) local currentRot = InvokeV3(0xAFBD61CC738D9EB9, veh, 2) if currentRot and math.abs(currentRot.y) >= 150.0 then break end attempts = attempts + 1 end if velocity then for _ = 1, 5 do if not InvokeInt(0x7239B21A38F536BA, veh) then break end InvokeVoid(0x1C99BB7B6E96D16F, veh, velocity.x, velocity.y, velocity.z) Script.Yield(5) end end end) end)
