function vr_requestControl(entity, timeout) timeout = timeout or 2500 local timer = Time.GetEpocheMs() + timeout repeat InvokeBool(0xB69317BF5E782347, entity) if Time.GetEpocheMs() > timer then return end Script.Yield() until InvokeBool(0x01BF60A500E28887, entity) end
-- Handling
vr_handlingVehicles = {}
local function RequestControl(ent) if Natives.InvokeBool(0x01BF60A500E28887, ent) then return true end Natives.InvokeVoid(0xB69317BF5E782347, ent, true) local start = os.clock() while not Natives.InvokeBool(0x01BF60A500E28887, ent) do if os.clock() - start > 0.2 then break end Script.Yield(10) end return Natives.InvokeBool(0x01BF60A500E28887, ent) end
function ApplyHandling(veh, data, initial) if veh == 0 then return false end if not RequestControl(veh) then return false end Natives.InvokeVoid(0x89F149B6131E57DA, veh, data.gravity) Natives.InvokeVoid(0xB59E4BD37AE292DB, veh, data.power) Natives.InvokeVoid(0xAFD262ACCA64479A, veh, data.traction) if data.reduceGrip ~= nil then Natives.InvokeVoid(0x222FF6A823D122E2, veh, data.reduceGrip) if data.reduceGrip then Natives.InvokeVoid(0x6DEE944E1EE90CFB, veh, data.gripLevel) end end if initial then Natives.InvokeVoid(0x93A3996368C94158, veh, data.topSpeed) end if data.tyres ~= nil and initial then Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, data.tyres) end return true end
function SetHandling(player, pid, gravity, topSpeed, power, traction, tyres, name, reduceGrip, gripLevel) local targetPid = pid or (player and player.id) or 0 local pPed = Natives.InvokeInt(0x50FAC3A3E030A6E1, targetPid) if pPed == 0 then GUI.AddToast("Handling", "Could Not Find Target Player!", 2000) return end if not Natives.InvokeBool(0x997ABD671D25CA0B, pPed) then GUI.AddToast("Handling", "Target Is Not In A Vehicle!", 2000) return end local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, pPed) if veh == 0 then GUI.AddToast("Handling", "Could Not Find Target Vehicle!", 2000) return end local data = { gravity = gravity, topSpeed = topSpeed, power = power, traction = traction, tyres = tyres, name = name, reduceGrip = reduceGrip, gripLevel = gripLevel } if not ApplyHandling(veh, data, true) then GUI.AddToast("Handling", "Could Not Obtain Vehicle Control!", 2000) return end vr_handlingVehicles[veh] = data GUI.AddToast("Handling", name .. " Applied!", 2000) end
Script.QueueJob(function() while not ShouldUnload() do for veh, data in pairs(vr_handlingVehicles) do if veh ~= 0 then ApplyHandling(veh, data, false) end end Script.Yield(100) end end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_HANDLING_STOCK"), "Normal Handling (Stock)", eFeatureType.Button, "Revert Vehicle Handling Back To Stock Default Values\n ", function(player, pid) SetHandling(player, pid, true, 1.0, 0.0, 1.0, true, "Stock Handling", false, 0) end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_HANDLING_DRIFT"), "Drift Tune", eFeatureType.Button, "Apply Custom Drift Handling Tune\n ", function(player, pid) SetHandling(player, pid, true, 1.15, 1.5, 2.0, nil, "Drift Tune", true, 3) end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_HANDLING_SPORT"), "Sport Handling", eFeatureType.Button, "Apply Enhanced Sport Handling Tune\n ", function(player, pid) SetHandling(player, pid, true, 1.25, 2.0, 0.65, nil, "Sport Handling") end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_HANDLING_RACE"), "Race Handling", eFeatureType.Button, "Apply Maximum Grip Race Handling Tune\n ", function(player, pid) SetHandling(player, pid, true, 1.5, 4.5, 0.45, nil, "Race Handling") end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_HANDLING_INSANE"), "Insane Handling", eFeatureType.Button, "Apply Chaotic Insane Speed And Physics Tune\n ", function(player, pid) SetHandling(player, pid, true, 2.5, 15.0, 0.85, nil, "Insane Handling") end)
-- Horn Boost
vr_pBoost = FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_PLAYER_HORNBOOST"), "Horn Boost", eFeatureType.SliderIntToggle, "Boosts Players Vehicle On Horn Press\n ", function(f)
Script.RegisterLooped(function() if f:IsToggled() then local vp = Players.GetCPed(f:GetPlayerIndex()) and Players.GetCPed(f:GetPlayerIndex()).CurVehicle if vp then local v = GTA.PointerToHandle(vp) if InvokeBool(0xFA1E2BF8B10598F9, f:GetPlayerIndex()) then vr_requestControl(v) local scaledForce = (f:GetIntValue() * 0.1) InvokeVoid(0x18FF00FC7EFF559E, v, 1, 0.0, scaledForce, 0.0, true, true, true, true) end end end end) end) for _, h in ipairs(vr_pBoost) do FeatureMgr.GetFeature(h):SetDefaultValue(25):SetLimitValues(1, 50):SetSaveable(false):Reset() end
-- Horn Repair
hornPressedState = {}
function DoRepairAndWash(veh) local vel = VR_InvokeV3(0x4805D2B1D8CF94A9, veh) local speed = VR_InvokeFloat(0xD5037BA82E12416F, veh) NatV(0xB69317BF5E782347, veh) NatV(0x115722B1B9C14C1C, veh) NatV(0x79D3B596FE44EE8B, veh, 0.0) if vel then VR_InvokeVoid(0x1C99BB7B6E96D16F, veh, vel.x, vel.y, vel.z) end if speed and speed > 0.1 then VR_InvokeVoid(0xAB54A438726D25D5, veh, speed) end end
vr_pHornRepair = FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_PLAYER_HORN_REPAIR"), "Horn Repair", eFeatureType.Toggle, "Repairs And Washes The Selected\nPlayers Vehicle On Horn Press\n ", function(f)
Script.RegisterLooped(function() if f:IsToggled() then local pId = f:GetPlayerIndex() if pId then local isPressing = InvokeBool(0xFA1E2BF8B10598F9, pId) if isPressing then if not hornPressedState[pId] then hornPressedState[pId] = true local vp = Players.GetCPed(pId) and Players.GetCPed(pId).CurVehicle if vp then local v = GTA.PointerToHandle(vp) DoRepairAndWash(v) end end else hornPressedState[pId] = false end end end end) end)
-- Lock Controls
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_LOCK_CONTROLS"), "Lock Controls", eFeatureType.Toggle, "Locks All Vehicle Control Inputs\n ", function(f) while f:IsToggled() do local playerId = f:GetPlayerIndex() local pPed = I(0x43A66C31C68491C0, playerId) if pPed ~= 0 and NatB(0x997ABD671D25CA0B, pPed, false) then local veh = I(0x9A9112A0FE9A4713, pPed, false) if veh ~= 0 then NatV(0xB69317BF5E782347, veh) local bias = 0.0 NatV(0x42A8EC77D5150CBE, veh, bias) local speed = VR_InvokeFloat(0xD5037BA82E12416F, veh) if speed > 0.5 then NatV(0xC429DCEEB339E129, pPed, veh, 23, 200) end end end Script.Yield(0) end end)
-- Magnetic Vehicles
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_MAGNETIC_VEHICLES"), "Magnetic Vehicles", eFeatureType.Toggle, "Hurls Nearby Vehicles At The Selected\nPlayer And Scrubs Them To Death\n ", function(feature) while feature:IsToggled() do local playerID = feature:GetPlayerIndex() local targetPed = VR_InvokeInt(0x50FAC3A3E030A6E1, playerID) if targetPed and targetPed ~= 0 then local playerCoords = VR_GET_ENTITY_COORDS(targetPed, true) local vehicles = getAllVehicles() if playerCoords and vehicles then for _, veh in pairs(vehicles) do if veh and veh ~= 0 and VR_InvokeInt(0x7239B21A38F536BA, veh) ~= 0 then local vehCoords = VR_GET_ENTITY_COORDS(veh, true) if vehCoords then local dx = playerCoords.x - vehCoords.x local dy = playerCoords.y - vehCoords.y local dz = playerCoords.z - vehCoords.z local realDistSq = (dx * dx) + (dy * dy) + (dz * dz) if realDistSq < (200.0 * 200.0) and realDistSq > 4.0 then local dist = math.sqrt(realDistSq) local pullSpeed = 25.0 local vx = (dx / dist) * pullSpeed local vy = (dy / dist) * pullSpeed local vz = (dz / dist) * pullSpeed VR_InvokeVoid(0x1C99BB7B6E96D16F, veh, vx, vy, vz) end end end end end end Script.Yield(200) end end)
-- Max Mods
function MaxOutAllVehicleMods(veh) NatV(0xB69317BF5E782347, veh) NatV(0x1F2AA07F00B3217A, veh, 0) local excludedSlots = { [11] = true, [12] = true, [13] = true, [15] = true, [16] = true, [18] = true, [23] = true, [24] = true } for modType = 0, 75 do if not excludedSlots[modType] then local maxVal = I(0xE38E9162A2500646, veh, modType) - 1 if maxVal >= 0 then NatV(0x6AF0636DDEDCB6DD, veh, modType, maxVal, false) end end end for _, wheelSlot in ipairs({23, 24}) do local maxWheels = I(0xE38E9162A2500646, veh, wheelSlot) - 1 if maxWheels >= 0 then NatV(0x6AF0636DDEDCB6DD, veh, wheelSlot, maxWheels, true) end end local maxLiveries = I(0xE38E9162A2500646, veh, 48) - 1 if maxLiveries >= 0 then NatV(0x6AF0636DDEDCB6DD, veh, 48, maxLiveries, false) NatV(0x60BF608F1B8CD1B6, veh, maxLiveries) else NatV(0x60BF608F1B8CD1B6, veh, 1) NatV(0x60BF608F1B8CD1B6, veh, 5) end local maxRoofLiveries = I(0xE38E9162A2500646, veh, 27) - 1 if maxRoofLiveries >= 0 then NatV(0x6AF0636DDEDCB6DD, veh, 27, maxRoofLiveries, false) end NatV(0x9088EB5A43FFB0A1, veh, 11) NatV(0x57C51E6BAD752696, veh, 1) local toggleMods = {20, 22} for _, modType in ipairs(toggleMods) do NatV(0x2A1F4F37F95BAD08, veh, modType, true) end end
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_PLAYER_MAX_ALL_MODS"), "Max Mods", eFeatureType.Button, "Upgrades All Available Cosmetic\nSlots To Their Highest Level\n ", function(f) local playerId = f:GetPlayerIndex() if not playerId then return end local pPed = I(0x43A66C31C68491C0, playerId) if pPed == 0 or not NatB(0x997ABD671D25CA0B, pPed, false) then return end local veh = I(0x9A9112A0FE9A4713, pPed, false) if veh == 0 then return end MaxOutAllVehicleMods(veh) end)
