-- Max Vehicle Performance
function MaxOutVehiclePerformance(veh) NatV(0xB69317BF5E782347, veh) NatV(0x1F2AA07F00B3217A, veh, 0) local perfMods = {11, 12, 13, 15, 16, 18} for _, modType in ipairs(perfMods) do local maxVal = 0 if modType == 18 then maxVal = 0 else maxVal = I(0xE38E9162A2500646, veh, modType) - 1 end if modType == 18 then NatV(0x6AF0636DDEDCB6DD, veh, modType, 1, false) elseif maxVal >= 0 then NatV(0x6AF0636DDEDCB6DD, veh, modType, maxVal, false) end end NatV(0x2A1F4F37F95BAD08, veh, 18, true) end
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_PLAYER_MAX_PERF"), "Max Performance", eFeatureType.Button, "Upgrades Performance Mods To Their Highest Level\n ", function(f) local playerId = f:GetPlayerIndex() if not playerId then return end local pPed = I(0x43A66C31C68491C0, playerId) if pPed == 0 or not NatB(0x997ABD671D25CA0B, pPed, false) then return end local veh = I(0x9A9112A0FE9A4713, pPed, false) if veh == 0 then return end MaxOutVehiclePerformance(veh) end)
-- Nuke Em
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_NUKE_EM"), "Nuke Em", eFeatureType.Button, "Strips Godmode & Explodes Them Until Dead\n ", function(f) local sid = f:GetPlayerIndex() if sid ~= nil then Script.QueueJob(function() local lastVehicle = 0 while not ShouldUnload() do local pPed = Natives.InvokeInt(0x43A66C31C68491C0, sid) if pPed == 0 then break end if Natives.InvokeBool(0x3317DEDB88C95038, pPed, true) then break end Natives.InvokeVoid(0xB69317BF5E782347, pPed) local vehicle = Natives.InvokeInt(0x9A9112A0FE9A4713, pPed, false) if vehicle ~= 0 and vehicle ~= lastVehicle then lastVehicle = vehicle Natives.InvokeVoid(0xB69317BF5E782347, vehicle) local vx, vy, vz = Natives.InvokeV3(0x3FEF770D40960D5A, vehicle, true) if vx and vy and vz then Natives.InvokeVoid(0xE3AD2BDBAEE269AC, vx, vy, vz, 0, 9999.0, false, true, 0.0) end elseif vehicle == 0 then lastVehicle = 0 end Natives.InvokeVoid(0x3882114BDE571AD4, pPed, false) Natives.InvokeVoid(0x6B76DC1F3AE6E6A3, pPed, 0, 0) local px, py, pz = Natives.InvokeV3(0x3FEF770D40960D5A, pPed, true) if px and py and pz then Natives.InvokeVoid(0xE3AD2BDBAEE269AC, px, py, pz, 0, 9999.0, false, true, 0.0) end Script.Yield(100) end end) else GUI.AddToast("Nuke Em", "No Player Selected!", 2000) end end)
