function getPlayerSettings(pid) if not _G.PlayerPedAttackerSettings then _G.PlayerPedAttackerSettings = {} end if not _G.PlayerPedAttackerSettings[pid] then _G.PlayerPedAttackerSettings[pid] = { selectedModelIndex = 1, selectedWeaponIndex = 1, invincible = false } end return _G.PlayerPedAttackerSettings[pid] end
function getPlayerPed(pid) return Natives.InvokeInt(0x50FAC3A3E030A6E1, pid) end
local function getPlayerCoords(pid) local ped = Players.GetCPed(pid) if not ped then return nil, nil, nil end local pos = ped.Position if pos then return pos.x, pos.y, pos.z end return nil, nil, nil end
function getOffsetFromEntity(entity, offX, offY, offZ) local x, y, z = Natives.InvokeV3(0x3FEF770D40960D5A, entity, true) local heading = Natives.InvokeFloat(0xE83D4F9BA2A38914, entity) local headRad = math.rad(heading) local cosH = math.cos(headRad) local sinH = math.sin(headRad) local worldX = x + (offX * cosH - offY * sinH) local worldY = y + (offX * sinH + offY * cosH) local worldZ = z + offZ return worldX, worldY, worldZ end
function requestModel(model) local hash = type(model) == "string" and Utils.Joaat(model) or model if not Natives.InvokeBool(0x98A4EB5D89A0C952, hash) then Natives.InvokeVoid(0x963D27A58DF860AC, hash) local timeout = 0 while not Natives.InvokeBool(0x98A4EB5D89A0C952, hash) and timeout < 100 do Script.Yield(10) timeout = timeout + 1 end end return Natives.InvokeBool(0x98A4EB5D89A0C952, hash) end
function createAttacker(pedHash, x, y, z, heading, weapon, invincible) if not requestModel(pedHash) then return nil end local ped = GTA.CreatePed(pedHash, 28, x, y, z, heading, true, true) if not ped or ped == 0 then return nil end Natives.InvokeVoid(0x9F7794730795E019, ped, 5, true) Natives.InvokeVoid(0x9F7794730795E019, ped, 46, true) Natives.InvokeVoid(0x7AEFB85C1D49DEB6, ped, 100) Natives.InvokeVoid(0xC7622C0D36B2FDA8, ped, 3)  Natives.InvokeVoid(0x90D2156198831D69, ped, true) Natives.InvokeVoid(0x971D38760FBC02EF, ped, true) if invincible then Natives.InvokeVoid(0x3882114BDE571AD4, ped, true) end if weapon and weapon ~= 0 then local weaponHash = type(weapon) == "string" and Utils.Joaat(weapon) or weapon Natives.InvokeVoid(0xBF0FD6E56C964FCB, ped, weaponHash, 9999, false, true) Natives.InvokeVoid(0xADF692B254977C0C, ped, weaponHash, true) end return ped end
function trackAttacker(pid, entity) if not PedAttackersByPid[pid] then PedAttackersByPid[pid] = {} end table.insert(PedAttackersByPid[pid], { ped = entity }) table.insert(PedState.spawnedEntities, entity) table.insert(PedState.attackers, entity) end
function sendGroundAttacker(pid, pedHash, weapon, invincible) local targetPed = getPlayerPed(pid) if not targetPed or targetPed == 0 then return end local tx, ty, tz = getPlayerCoords(pid) if not tx then return end local sx, sy, sz = getOffsetFromEntity(targetPed, 0, -5.0, 0) Script.QueueJob(function() local attacker = createAttacker(pedHash, sx, sy, sz, 0, weapon, invincible) if attacker then Natives.InvokeVoid(0xF166E48407BAC484, attacker, targetPed, 0, 16) trackAttacker(pid, attacker) GUI.AddToast("Ped Attacker", "Attacker Sent", 3000) end end) end
Script.QueueJob(function() while true do for pid, attackers in pairs(PedAttackersByPid) do for i = #attackers, 1, -1 do local data = attackers[i] if data and data.ped then local isDead = Natives.InvokeBool(0x5F9532F3B5CC2551, data.ped) if isDead then table.remove(attackers, i) end end end end Script.Yield(1000) end end)
