FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_PED_ATTACK"), "Spawn Attacker", eFeatureType.Button, "Spawn Selected NPC Attacker On Selected Player\n ", function(f) local pid = f:GetPlayerIndex() local settings = getPlayerSettings(pid) local modelName = AllAttackerModels[settings.selectedModelIndex] or "s_m_m_movalien_01" local modelHash = Utils.Joaat(modelName) local weaponModel = AllWeaponModels[settings.selectedWeaponIndex] or 0 local isInvincible = settings.invincible or false for i = 1, PedAttackerSettings.numAttackers do sendGroundAttacker(pid, modelHash, weaponModel, isInvincible) end end)
