FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_POP_TIRES"), "Pop Tires", eFeatureType.Toggle, "Repetitively Burst Tires On Vehicle\n ", function(f) local tires = {0, 4, 5, 1} local currentIndex = 1 while f:IsToggled() do local playerId = f:GetPlayerIndex() local pPed = Natives.InvokeInt(0x43A66C31C68491C0, playerId) if pPed ~= 0 and Natives.InvokeBool(0x997ABD671D25CA0B, pPed) then local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, pPed) if veh ~= 0 then Natives.InvokeVoid(0xB69317BF5E782347, veh) Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, true) local prevIndex = (currentIndex == 1) and tires[#tires] or tires[currentIndex - 1] local currIndex = tires[currentIndex] Natives.InvokeVoid(0x6E13FC662B882D1D, veh, prevIndex) Natives.InvokeVoid(0xEC6A202EE4960385, veh, currIndex, true, 1000.0) currentIndex = currentIndex + 1 if currentIndex > #tires then currentIndex = 1 end end end Script.Yield(300) end end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_POP_TIRES_LEFT"), "Pop Swerve Right", eFeatureType.Toggle, "Pops Their Tires In A Pattern\nTo Make Them Swerve Right\n ", function(f) local tires = {0, 4} local currentIndex = 1 while f:IsToggled() do local playerId = f:GetPlayerIndex() local pPed = Natives.InvokeInt(0x43A66C31C68491C0, playerId) if pPed ~= 0 and Natives.InvokeBool(0x997ABD671D25CA0B, pPed) then local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, pPed) if veh ~= 0 then Natives.InvokeVoid(0xB69317BF5E782347, veh) Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, true) local prevIndex = (currentIndex == 1) and tires[#tires] or tires[currentIndex - 1] local currIndex = tires[currentIndex] Natives.InvokeVoid(0x6E13FC662B882D1D, veh, prevIndex) Natives.InvokeVoid(0xEC6A202EE4960385, veh, currIndex, true, 1000.0) currentIndex = currentIndex + 1 if currentIndex > #tires then currentIndex = 1 end end end Script.Yield(250) end end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_POP_TIRES_RIGHT"), "Pop Swerve Left", eFeatureType.Toggle, "Pops Their Tires In A Pattern\nTo Make Them Swerve Left\n ", function(f) local tires = {1, 5} local currentIndex = 1 while f:IsToggled() do local playerId = f:GetPlayerIndex() local pPed = Natives.InvokeInt(0x43A66C31C68491C0, playerId) if pPed ~= 0 and Natives.InvokeBool(0x997ABD671D25CA0B, pPed) then local veh = Natives.InvokeInt(0x9A9112A0FE9A4713, pPed) if veh ~= 0 then Natives.InvokeVoid(0xB69317BF5E782347, veh) Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, true) local prevIndex = (currentIndex == 1) and tires[#tires] or tires[currentIndex - 1] local currIndex = tires[currentIndex] Natives.InvokeVoid(0x6E13FC662B882D1D, veh, prevIndex) Natives.InvokeVoid(0xEC6A202EE4960385, veh, currIndex, true, 1000.0) currentIndex = currentIndex + 1 if currentIndex > #tires then currentIndex = 1 end end end Script.Yield(250) end end)
FeatureMgr.AddPlayerFeature(Utils.Joaat("VR_PLAYER_REPAIR_WASH"), "Repair And Wash", eFeatureType.Button, "Repairs And Washes Selected Vehicle\n ", function(f) local playerId = f:GetPlayerIndex() if not playerId then return end local pPed = I(0x43A66C31C68491C0, playerId) if pPed == 0 or not NatB(0x997ABD671D25CA0B, pPed, false) then return end local veh = I(0x9A9112A0FE9A4713, pPed, false) if veh == 0 then return end DoRepairAndWash(veh) end)
