FD6E56C964FCB, passenger, 0x7FD62962, 9999, true)  Natives.InvokeVoid(0x7AEFB85C1D49DEB6, passenger, 100.0)   Natives.InvokeVoid(0x10AB107B887214D8, passenger, targetPed, 100.0) Natives.InvokeVoid(0x971D38760FBC02EF, passenger, true)   table.insert(passengers, passenger) end end local targetDead = false local cleanupTimer = 0 while true do Script.Yield(500) targetPed = Natives.InvokeInt(0x43A66C31C68491C0, sid) local isDead = Natives.InvokeInt(0x3317DEDB88C95038, targetPed, true) local vehExists = Natives.InvokeInt(0x7239B21A38F536BA, vehicle) if vehExists == 0 then break end if not targetDead and pilot and pilot ~= 0 then Natives.InvokeVoid(0x9454528DF15D657A, pilot, vehicle, targetPed, 0, 75.0, 4, 25.0, 25.0, 10.0, 0) Natives.InvokeVoid(0xF166E48407BAC484, pilot, targetPed, 100.0) Natives.InvokeVoid(0x971D38760FBC02EF, pilot, true) end if not targetDead then for _, passenger in ipairs(passengers) do if passenger and Natives.InvokeInt(0x997ABD671D25CA0B, passenger) ~= 0 then Natives.InvokeVoid(0x10AB107B887214D8, passenger, targetPed, 100.0) Natives.InvokeVoid(0x971D38760FBC02EF, passenger, true) end end end if not targetDead and (isDead == 1 or Natives.InvokeInt(0x5F9532F3B5CC2551, targetPed) == 1) then targetDead = true for _, passenger in ipairs(passengers) do if passenger and Natives.InvokeInt(0x997ABD671D25CA0B, passenger) ~= 0 then Natives.InvokeVoid(0xE1EF3C1216AFF2CD, passenger) Natives.InvokeVoid(0xF75B0D629E1C063D, passenger, vehicle, seat) end end Natives.InvokeVoid(0xE1EF3C1216AFF2CD, pilot) Script.Yield(100) Natives.InvokeVoid(0xE2A2AA2F659D77A7, pilot, vehicle, -3500.0, 3000.0, 50.0, 100.0, 1.0, 0, 786469, 5.0, 1) GUI.AddToast("Valkyrie Squad", "Target Eliminated... Clearing The Area", 3000) end if targetDead then cleanupTimer = cleanupTimer + 500 if cleanupTimer >= 30000 then if Natives.InvokeInt(0x7239B21A38F536BA, vehicle) ~= 0 then local coords = GTA.GetEntityCoords and GTA.GetEntityCoords(vehicle) or nil end Natives.InvokeVoid(0x3882114BDE571AD4,