() Memory.WriteInt(ptr, npc) Natives.InvokeVoid(0xAE3CBE5BF394C9C9, ptr) Memory.Free(ptr) end end) end) else GUI.AddToast("VROOM", "No Player Selected!", 2000) end end)
function StripVehiclePerformance(veh) NatV(0xB69317BF5E782347, veh) NatV(0x1F2AA07F00B3217A, veh, 0) local perfMods = {11, 12, 13, 15, 16, 18} for _, modType in ipairs(perfMods) do if modType == 18 then NatV(0x6AF0636DDEDCB6DD, veh, modType, 0, false) else NatV(0x6AF0636DDEDCB6DD, veh, modType, -1, false) end end NatV(0x2A1F4F37F95BAD08, veh, 18, false) end
