h, doorIndex, false) end Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, true) for tyreIndex = 0, 5 do Natives.InvokeVoid(0xEC6A202EE4960385, veh, tyreIndex, true, 1000.0) end Script.Yield(50) Natives.InvokeVoid(0x45F6D8EEF34ABEF1, veh, 1000.0) end) else GUI.AddToast("Strip Car", "No Player Selected!", 2000) end end)
