EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
	local yappin = FeatureMgr.GetFeature(Utils.Joaat("VR_SHOWYAPPERS")) if yappin and yappin:IsToggled() then ImGui.PushStyleColor(ImGuiCol.WindowBg, 0.1, 0.1, 0.1, 0.8) ImGui.Begin("##VRTalkingPlayers", true, ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoDecoration) ImGui.Text("Talking Players:") for _, n in ipairs(VR_YAPPERS) do ImGui.Text(n) end ImGui.End() ImGui.PopStyleColor() end
	local veh = GTA.GetLocalVehicle() if not (veh and (veh:GetDriver() == GTA.GetLocalPed())) then return end local w, h = ImGui.GetDisplaySize() local gaugeWidth = 206.0 local veh = vr_myVehicle() local rawSpeed = VR_GET_ENTITY_SPEED(veh) local multiplier = vr_use_mph and 2.23694 or 3.6 local speed = math.floor(rawSpeed * multiplier) local maxSpeed = vr_use_mph and 240.0 or 380.0 local speedPercent = math.min(speed / maxSpeed, 1.0)
	if FeatureMgr.GetFeature(Utils.Joaat("VR_DRIFTPOINTS")):IsToggled() then ImGui.SetNextWindowBgAlpha(0.35) ImGui.Begin("DriftPoints", true, ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoTitleBar | ImGuiWindowFlags.NoFocusOnAppearing) ImGui.SetWindowPos("DriftPoints", (w / 2) - 28, h / 10, ImGuiCond.Once) local isLinking = vr_in_grace_period and vr_drift_points > 0 local text = isLinking and ("LINKING... " .. vr_drift_points) or ("POINTS: " .. vr_drift_points) local color = isLinking and {1, 1, 0, 1} or {0, 1, 1, 1} ImGui.SetCursorPosY(ImGui.GetCursorPosY() - 2) ImGui.TextColored(color[1], color[2], color[3], color[4], text) ImGui.TextColored(0, 1, 1, 1, "SESSION BEST: " .. vr_drift_highscore) ImGui.End() end
	if FeatureMgr.GetFeature(Utils.Joaat("VR_DRIFTPOINTS")):IsToggled() then ImGui.SetNextWindowBgAlpha(0.35) ImGui.Begin("AllTimeHighScore", true, ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoTitleBar | ImGuiWindowFlags.NoFocusOnAppearing) ImGui.SetWindowPos("AllTimeHighScore", (w / 2) - 40, (h / 10) - 85, ImGuiCond.Once) local titleText = "ALL TIME HIGH" local scoreText = string.format("%d", vr_file_highscore) local titleSize = ImGui.CalcTextSize(titleText) local scoreSize = ImGui.CalcTextSize(scoreText) local availWidth = math.max(titleSize, scoreSize) local startX = ImGui.GetCursorPosX() ImGui.SetCursorPosX(startX + (availWidth - titleSize) * 0.5) ImGui.TextColored(0, 1, 1, 1, titleText) ImGui.SetCursorPosX(startX + (availWidth - scoreSize) * 0.5) ImGui.TextColored(0, 1, 1, 1, scoreText) ImGui.End() end
	if FeatureMgr.GetFeature(Utils.Joaat("VR_DRIFTPOINTS")):IsToggled() then if not vr_last_mult then vr_last_mult = 0; vr_flash_until = 0 end local current_mult = math.floor(vr_drift_multiplier) if current_mult > vr_last_mult and vr_last_mult > 0 then vr_flash_until = os.clock() + 1.0 end vr_last_mult = current_mult local isFlashing = os.clock() < vr_flash_until local flashToggle = math.fmod(os.clock(), 0.2) > 0.025 local r, g, b, a if isFlashing then r, g, b, a = flashToggle and 1.0 or 0.0, 1.0, flashToggle and 0.0 or 1.0, 1.0 else r, g, b, a = 0.0, 1.0, 1.0, 1.0 end ImGui.SetNextWindowBgAlpha(0.35) ImGui.Begin("DriftMulti", true, ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoTitleBar | ImGuiWindowFlags.NoFocusOnAppearing) ImGui.SetWindowPos("DriftMulti", (w / 2) - 73, (h / 10) + 6, ImGuiCond.Once) ImGui.SetCursorPosY(ImGui.GetCursorPosY() + 2) ImGui.TextColored(r, g, b, a, "x") ImGui.SameLine() ImGui.TextColored(r, g, b, a, string.format("%d", current_mult)) ImGui.End() end
	if vr_show_tach and FeatureMgr.GetFeature(Utils.Joaat("VR_TACHOMETER")):IsToggled() then ImGui.Begin("RPM##vr", true, ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoDecoration) ImGui.SetWindowPos("RPM##vr", w/2 - 100, h - 100, ImGuiCond.Once) local startX, startY = ImGui.GetCursorPos() local isAtRedline = vr_veh_rpm >= 0.95 local col = isAtRedline and (math.fmod(os.clock(), 0.2) > 0.1 and {1, 1, 1} or {1, 0, 0}) or (vr_veh_rpm < 0.4 and {0, 0.5, 0} or {0.5, 0.5, 0}) ImGui.PushStyleColor(ImGuiCol.PlotHistogram, col[1], col[2], col[3], 1.0) ImGui.ProgressBar(vr_veh_rpm, gaugeWidth - 2, 25, "") ImGui.PopStyleColor() local tSize = ImGui.CalcTextSize("RPM") ImGui.SetCursorPos(startX + (gaugeWidth / 2) - (tSize / 2), startY + 4) ImGui.TextColored(0, 0, 0, 1.0, "RPM") ImGui.SetCursorPos(startX + gaugeWidth + 5, startY + 3) if isAtRedline and math.fmod(os.clock(), 0.2) > 0.1 then ImGui.TextColored(1, 1, 1, 1, "SHIFT!") elseif isAtRedline then ImGui.TextColored(1, 0, 0, 1, "SHIFT!") else local gearDisplay = (vr_getCurrentGear() == 0) and "R" or vr_getCurrentGear() ImGui.Text(gearDisplay .. "/" .. vr_getHighGear()) end ImGui.End() end
	if vr_show_speedo and FeatureMgr.GetFeature(Utils.Joaat("VR_SPEEDOMETER")):IsToggled() then local veh = vr_myVehicle() local sizeFeature = FeatureMgr.GetFeature(Utils.Joaat("VR_SPEEDO_SIZE")) local scale = sizeFeature and sizeFeature:GetFloatValue() or 1.5 local rawSpeed = VR_GET_ENTITY_SPEED(veh) local multiplier = vr_use_mph and 2.23694 or 3.6 local speed = math.floor(rawSpeed * multiplier) local maxSpeed = vr_use_mph and 240.0 or 380.0 local speedPercent = math.min(speed / maxSpeed, 1.0) local r, g, b, a = ImGui.GetStyleColorVec4(ImGuiCol.Border) local cr, cg, cb, ca = math.floor(r * 255), math.floor(g * 255), math.floor(b * 255), math.floor(a * 255) local windowSize = 150 * scale local radius = 60 * scale local centerOffset = 75 * scale ImGui.SetNextWindowBgAlpha(0) ImGui.SetNextWindowSize(windowSize, windowSize, ImGuiCond.Always) ImGui.Begin("SpeedoWindow", true, ImGuiWindowFlags.NoTitleBar | ImGuiWindowFlags.NoResize | ImGuiWindowFlags.NoScrollbar | ImGuiWindowFlags.NoBackground) ImGui.SetWindowPos("SpeedoWindow", w - 825, h - 290, ImGuiCond.Once) local px, py = ImGui.GetCursorScreenPos() local centerX, centerY = px + centerOffset, py + centerOffset ImGui.AddCircleFilled(centerX, centerY, radius, 15, 15, 15, 90, 32) ImGui.AddCircle(centerX, centerY, radius, cr, cg, cb, ca, 255, 2.0 * scale) local totalSegments = 96 local tickStart, tickEnd = 16, 80 for i = 0, totalSegments do if i >= tickStart and i <= tickEnd then local tickAngle = (i * (2 * math.pi / totalSegments)) - (0.5 * math.pi) + math.pi local isMajor = (i % 8 == 0) local tickLen = isMajor and (12 * scale) or (5 * scale) local x1 = centerX + math.cos(tickAngle) * (radius - tickLen) local y1 = centerY + math.sin(tickAngle) * (radius - tickLen) local x2 = centerX + math.cos(tickAngle) * radius local y2 = centerY + math.sin(tickAngle) * radius ImGui.AddLine(x1, y1, x2, y2, 255, 255, 255, isMajor and 255 or 100) end end local startAngle = (tickStart * (2 * math.pi / totalSegments)) - (0.5 * math.pi) + math.pi local endAngle = (tickEnd * (2 * math.pi / totalSegments)) - (0.5 * math.pi) + math.pi local arcLength = endAngle - startAngle local angle = startAngle + (speedPercent * arcLength) local needleInnerOffset = 0 * scale local needleStartX = centerX + (math.cos(angle) * needleInnerOffset) local needleStartY = centerY + (math.sin(angle) * needleInnerOffset) local needleEndX = centerX + (math.cos(angle) * (radius - (5 * scale))) local needleEndY = centerY + (math.sin(angle) * (radius - (5 * scale))) ImGui.AddLine(needleStartX, needleStartY, needleEndX, needleEndY, 255, 255, 255, 255) local textSpeed = string.format("%d", speed) local tSizeSpeed = ImGui.CalcTextSize(textSpeed) * scale ImGui.AddText(centerX - (tSizeSpeed * 0.5), (centerY + (10 * scale)), textSpeed, 255, 255, 255, 255) local unitLabel = vr_use_mph and "MPH" or "KMH" ImGui.AddText(centerX - (ImGui.CalcTextSize(unitLabel) * 0.5), centerY + (25 * scale), unitLabel, cr, cg, cb, 255) ImGui.End() end
	if vr_show_input and FeatureMgr.GetFeature(Utils.Joaat("VR_INPUTWINDOW")):IsToggled() then ImGui.SetNextWindowPos((w / 2) - 230, h - 100, ImGuiCond.Once) ImGui.SetNextWindowSize(112, 67, ImGuiCond.Once) ImGui.Begin("VEHINPUT##vr", true, ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoDecoration) local pX, pY = ImGui.GetCursorPosX(), ImGui.GetCursorPosY() ImGui.PushStyleColor(ImGuiCol.PlotHistogram, 0, 1, 0, 1.0) ImGui.ProgressBar(math.abs(vr_veh_throttle), 100, 25, "") ImGui.PopStyleColor() ImGui.SetCursorPos(pX + 25, pY + 4) ImGui.TextColored(0, 0, 0, 1.0, "THROTTLE") ImGui.SetCursorPosY(ImGui.GetCursorPosY() + 6) local bX, bY = ImGui.GetCursorPosX(), ImGui.GetCursorPosY() ImGui.PushStyleColor(ImGuiCol.PlotHistogram, 1, 0, 0, 1.0) ImGui.ProgressBar(math.abs(vr_veh_braking), 100, 25, "") ImGui.PopStyleColor() ImGui.SetCursorPos(bX + 34, bY + 4) ImGui.TextColored(0, 0, 0, 1.0, "BRAKE") ImGui.End() end
	if vr_show_boost then local vehObj = vr_myVehicle() if vehObj ~= 0 and VR_IS_TOGGLE_MOD_ON(vehObj, 18) then local bVal = (vr_veh_throttle > 0.01) and vr_getBoostPressure() or 0.0 ImGui.SetNextWindowSize(243, 30, ImGuiCond.Always) ImGui.Begin("BOOST##vr", true, ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoDecoration | ImGuiWindowFlags.NoResize) ImGui.SetWindowPos("BOOST##vr", w/2 - 100, h - 65, ImGuiCond.Once) local sX, sY = ImGui.GetCursorPos() local r, g, b = ImGui.GetStyleColorVec4(ImGuiCol.Border) ImGui.PushStyleColor(ImGuiCol.PlotHistogram, r, g, b, 1.0) ImGui.ProgressBar(bVal, 202, 20, "") ImGui.PopStyleColor() ImGui.SetCursorPos(sX + 85, sY + 2) ImGui.TextColored(0, 0, 0, 1.0, "BOOST") ImGui.SetCursorPos(sX + 210, sY + 1) ImGui.Text(string.format("%3d%%", math.floor(bVal * 100))) ImGui.End() else vr_show_boost = false end end
end)

