local UI = { x = nil, y = nil, lx = nil, ly = nil, s = 0.75, path = vroomDir .. "launch_pos.json", start = os.clock(), dur = 4.75, barDur = 4.25, lastUpd = 1790033294, hOffset = -22, wasMouseDown = false }
local function loadPos() local file = io.open(UI.path, "r") if file then local d = file:read("*a") file:close() local x, y = d:match("([^,]+),([^,]+)") if x and y then UI.x, UI.y = tonumber(x), tonumber(y) end end end loadPos()

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    local f = FeatureMgr.GetFeature(hash)
    if f and f:IsToggled() then return end
    local elapsed = os.clock() - UI.start
    if elapsed >= UI.dur then return end
    local dw, dh = ImGui.GetDisplaySize()
    local sw, sh = 640 * UI.s, 260 * UI.s
    if not UI.x or not UI.y then
        UI.x, UI.y = (dw - sw) * 0.5, (20 * UI.s)
    end
    local mx, my = ImGui.GetMousePos()
    local isMouseDown = ImGui.IsMouseDown(0)
    if UI.lx and UI.ly and isMouseDown then
        if mx >= UI.x and mx <= UI.x + sw and my >= UI.y and my <= UI.y + sh then
            UI.x, UI.y = UI.x + (mx - UI.lx), UI.y + (my - UI.ly)
        end
    end
    if UI.wasMouseDown and not isMouseDown then
        local file = io.open(UI.path, "w")
        if file then
            file:write(UI.x .. "," .. UI.y)
            file:close()
        end
    end
    UI.wasMouseDown = isMouseDown
    UI.lx, UI.ly = mx, my
    local px, py = UI.x, UI.y
    local alpha = math.max(0, math.min(1, elapsed < 0.25 and (elapsed / 0.25) or (elapsed > UI.barDur and 1 - ((elapsed - UI.barDur) / (UI.dur - UI.barDur)) or 1)))
    local prog = math.min(elapsed / UI.barDur, 1.0)
    local cr, cg, cb = 31, 249, 255
    local re, lm = px + (620 * UI.s), px + (20 * UI.s)
    ImGui.AddRectFilled(px, py, px + sw, py + sh, 15, 15, 20, math.floor(230 * alpha), 4.0 * UI.s)
    ImGui.AddRect(px, py, px + sw, py + sh, cr, cg, cb, math.floor(alpha * 255), 2.0 * UI.s)
    ImGui.AddText(px + (320 * UI.s) - (ImGui.CalcTextSize("VROOM") * 0.5 * UI.s), py + (10 * UI.s), "VROOM", cr, cg, cb, math.floor(alpha * 255))
    ImGui.AddLine(lm, py + (35 * UI.s), re, py + (35 * UI.s), cr, cg, cb, math.floor(100 * alpha), 1.0 * UI.s)
    local name = (GTA and Players) and Players.GetName(GTA.GetLocalPlayerId()) or "User"
    local uid = (Cherax and Cherax.GetUID) and tostring(Cherax.GetUID()) or "0000"
    ImGui.AddText(lm, py + (45 * UI.s), "USER:  " .. name, 255, 255, 255, math.floor(220 * alpha))
    ImGui.AddText(lm, py + (62 * UI.s), "UID:    " .. uid, 255, 255, 255, math.floor(220 * alpha))
    local stats = {tostring(os.time()), os.date("%d/%m/%Y"), os.date("%H:%M:%S")}
    for i, v in ipairs(stats) do
        local shift = (i == 3) and (5 * UI.s) or 0
        ImGui.AddText(re - (ImGui.CalcTextSize(v) * UI.s) + (UI.hOffset * UI.s) + shift, py + (30 + (i * 15)) * UI.s, v, 255, 255, 255, math.floor(220 * alpha))
    end
	ImGui.AddText(lm, py + (195 * UI.s), "V - 1.2.1", 255, 255, 255, math.floor(220 * alpha))
	ImGui.AddText(lm, py + (210 * UI.s), "LAST UPDATE: " .. os.date("%d/%m/%Y", UI.lastUpd), 255, 255, 255, math.floor(220 * alpha))
    ImGui.AddText(re - (ImGui.CalcTextSize("Always Free") * UI.s) + (UI.hOffset * UI.s), py + (210 * UI.s), "Always Free", 255, 255, 255, math.floor(220 * alpha))
    local logs = {"Welcome " .. name, "Bind Ignition Key Added..", "Countermeasures Added..", "Engine Swap Search Added..", "Speed Limiter Back..", "Traffic Fucker Added..", "https://discord.gg/xsXHuVsJh3"}
    local lIdx = math.min(#logs, math.floor(elapsed / 0.5) + 1)
    for i = math.max(1, lIdx - 2), lIdx do
        ImGui.AddText(px + (250 * UI.s), py + (50 + ((i - math.max(1, lIdx - 2)) * 20)) * UI.s, "> " .. logs[i], cr, cg, cb, math.floor(((i == lIdx) and 255 or 100) * alpha))
    end
    local time = os.clock()
    local spinX, spinY = px + (318 * UI.s), py + (168 * UI.s)
    local rings = {{12, 32, 2.25, 1}, {12, 27, 2.0, -1}, {8, 22, 1.75, 1}, {8, 17, 1.5, -1}, {8, 12, 1.25, 1}, {6, 7, 1.0, -1}}
    for _, r in ipairs(rings) do
        for i = 0, r[1] - 1 do
            local a = (i * (math.pi * 2 / r[1])) + (time * r[4])
            ImGui.AddCircleFilled(spinX + math.cos(a) * (r[2] * UI.s), spinY + math.sin(a) * (r[2] * UI.s), r[3] * UI.s, cr, cg, cb, math.floor(alpha * 255))
        end
    end
    ImGui.AddRectFilled(lm, py + (235 * UI.s), re, py + (241 * UI.s), 40, 40, 45, math.floor(255 * alpha), 0.0)
    ImGui.AddRectFilled(lm, py + (235 * UI.s), lm + (600 * UI.s * prog), py + (241 * UI.s), cr, cg, cb, math.floor(200 * alpha), 0.0)
end)
RefreshFeatureList() LoadBinds() LoadSettings()

